INSERT INTO `bilibili_video` VALUES (4, 569646302, 'https://www.bilibili.com/video/av569646302', 383551518, '水论文的程序猿', 'https://i0.hdslb.com/bfs/face/7701115e565bd4335841c18bd2695234c7563de7.jpg', 46904, 1764559482052, 1764570524487, 'video', '35分钟教你从0到1，水出SCI（精品），学术裁缝必修课', '如何通过“西红柿鸡蛋堡配上老八秘制调料”水论文\n被小孩鞭策了，录一期35分钟的水论文的通用套路，从说到做再到写，事无巨细~\n为长视频争光。', 1680945300, '0', '562531', '45965', '7052', '33229', '1907', '1252', 'http://i1.hdslb.com/bfs/archive/892fe703f3379420ef321655809b332290836717.jpg', '论文');
