INSERT INTO `bilibili_video` VALUES (95, 945466883, 'https://www.bilibili.com/video/av945466883', 383551518, '水论文的程序猿', 'https://i0.hdslb.com/bfs/face/7701115e565bd4335841c18bd2695234c7563de7.jpg', 12758, 1764560131608, 1764569331355, 'video', 'sci灌水文每个部分都这样写就对了，模板链接在视频简介中', '高质量sci灌水文每个部分都这样写就对了\n中英文问题：先写中文，后机翻再润色（不要把精力放在能花钱解决的地方）\n配套博客链接：https://www.cnblogs.com/nickchen121/p/16919436.html', 1669189725, '0', '359629', '28616', '2274', '9309', '463', '536', 'http://i2.hdslb.com/bfs/archive/59e6895e50232ae3d9280430eae0c17c2f76e2fa.jpg', '论文');
