INSERT INTO `bilibili_video` VALUES (133, 1305909546, 'https://www.bilibili.com/video/av1305909546', 1668113965, '做科研的大师兄', 'https://i1.hdslb.com/bfs/face/eb6cf6015156a390d3736ed52ec31071a4d701bd.jpg', 1487, 1764569455135, 1764569455133, 'video', 'SCI写作手把手带教第一期！', 'ai快速总结、翻译、解析、阅读SCI文献工具UPDF免费下载链接：https://www.updf.cn/pdf-edu\n\n本次PPT获取方式：关注微信公众号BioAdvance，在公众号后台回复：写作第一期', 1719219600, '0', '42574', '3679', '239', '638', '8', '62', 'http://i1.hdslb.com/bfs/archive/4335a06ca897b7c0cfebb58f5747ae95ab3c04a3.jpg', '论文');
