INSERT INTO `bilibili_video` VALUES (151, 37249, 'https://www.bilibili.com/video/av37249', 6477, 'Otakuproject', 'https://i0.hdslb.com/bfs/face/c8a0faded592f7180df9a6241f953ca680a4f2ab.jpg', 6, 1764569588186, 1764569588185, 'video', '【雀龙门】うｐ主又役满了，抢暗杠纪念下', '渣视频，无技术，话说鸟笼门的确越做越欢乐了。。一晚上居然出了3个役满，一局几乎大车轮。。可惜，虽然还是数え役満。。绝地凹役满居然抢了暗杠，小小纪念下，另外鸟笼门2 BUG还真多。11番的牌居然显示役满动画。。', 1289940684, '0', '2189', '3', '13', '2', '64', '5', 'http://i0.hdslb.com/bfs/archive/db46c94b445f7bbab62b30b922c1677544242044.jpg', '论文');
