INSERT INTO `bilibili_video` VALUES (154, 115631726795416, 'https://www.bilibili.com/video/av115631726795416', 379883577, '论文清醒学姐', 'https://i0.hdslb.com/bfs/face/aa93d7980e5c3c55b2f5a94c2954671a09267dc9.jpg', 7, 1764569588233, 1764569588231, 'video', '2分钟刷论文文献？高效技巧让你快速搞定！', '文献阅读效率低影响研究进度，如何快速掌握核心内容？本期视频教你2分钟高效刷论文文献期刊的实用技巧，包括摘要抓取、图表速览、结论提炼等方法，助你精准定位关键信息，提升文献处理效率，轻松应对海量阅读任务。', 1764417600, '0', '318', '4', '0', '0', '0', '4', 'http://i1.hdslb.com/bfs/archive/875e339a1ebc8208cc04d58afd65c1ac1dea38d2.jpg', '论文');
