INSERT INTO `bilibili_video` VALUES (159, 205222150, 'https://www.bilibili.com/video/av205222150', 504698264, '知网研学', 'https://i2.hdslb.com/bfs/face/004228ecbc04d08069e5e3c09ffac0d32504a313.jpg', 636, 1764569716859, 1764571057452, 'video', '【知网研学公开课】学术小白必看，“论文读写入门”系列公益讲座', '第一讲 认识论文\n主要内容：什么是论文、学位论文框架、基本写作规范\n第二讲 论文前期的准备工作\n主要内容：写作规划的制定、查找资料的渠道和方法、文献阅读的基本方法\n第三讲 选题与开题报告 \n主要内容：选题的基本原则、知网选题技巧、开题报告的撰写 \n第四讲 毕业论文写作与学术规范\n主要内容：基本框架、写作流程、写作工具、学术规范', 1618814176, '0', '35312', '2650', '396', '225', '138', '50', 'http://i1.hdslb.com/bfs/archive/5862b2ac1d84210bb24ffd0d20a9b533bac572c7.png', '论文');
