INSERT INTO `bilibili_video` VALUES (187, 115575120467095, 'https://www.bilibili.com/video/av115575120467095', 16703853, '薇识学姐-只聊干货', 'https://i0.hdslb.com/bfs/face/555b9ea38ebc8d7a9e2594628499b806765de474.jpg', 14, 1764569984154, 1764570121422, 'video', '【手把手带读、带写论文期刊】一个系列视频讲透论文怎么写DeepSeek、Kimi、豆包通用论文初稿（带模板与指令）选题大纲文献综述根据大纲写论文数据分析与结果', 'DeepSeek、Kimi、豆包通用论文初稿（带模板）\n进度条：\n1:11正文开始（与11.13号的重叠，可跳过）\n6:10指令讲解（非常重要，不建议跳过）\n1. 确定选题\n2. 生成大纲\n3. 精准整理文献综述\n4. 根据大纲写论文初稿\n5. 引言\n6. 研究方法\n7. 数据分析与结果\n8. 研究理论指令\n9. 讨论与启示\n10. 结论与展望\n11. 论文致谢指令\n12. 参考文献指令\n\n超详细，全程演示手把手，包会！', 1763536615, '0', '748', '45', '2', '12', '0', '10', 'http://i2.hdslb.com/bfs/archive/270ddbcf9d244ac1a69093889577153f9d6149e2.jpg', '论文');
