INSERT INTO `bilibili_video` VALUES (264, 115571546916188, 'https://www.bilibili.com/video/av115571546916188', 35268408, '爱学术的霖学长', 'https://i0.hdslb.com/bfs/face/f709465f621425f3af186f249841f308d2e12854.jpg', 741, 1764570922611, 1764570922610, 'video', 'AI论文写作工具评测对比！为什么DeepSeek爆火却写不了论文？最后一款直接封神！', 'UP主花了大价钱帮大家测了三款好用的Ai论文软件如下：\n1、Ai一键生成论文（5万字以内，文献溯源，大纲定制，本科友好）\n【https://aicc.chachongz.com】\n2、Ai一键生成论文（10万字以内，带图表数据，实证分析，调查问卷，硕博友好）\n【https://tx2424.dashixiezuo.com】\n3、极速降重 、降低AI率）\n【https://tx2424.zaojiangchong.net】', 1763481991, '0', '31937', '1263', '372', '514', '10', '24', 'http://i0.hdslb.com/bfs/archive/bc53236f1d36d5238f4cc54d29a66f08cd5d0a08.jpg', '论文');
