INSERT INTO `bilibili_video_comment` VALUES (231, '12747464', '大青山道士', '保密', '芜湖！起飞', 'https://i2.hdslb.com/bfs/face/e5690594fd0a2108a432b213af134a04d14010ad.jpg', 1764559801036, 1764569144521, 251762237233, 113379435942977, 'letpub看评价，影响因子，自引率\n进官网，看作者须知\n看完前面后找到Latex模板，\n选择文章类型，提交手稿，附件 ,作者声明，权力声明，标题页\n选择研究领域\n推荐审稿人，可以填引用文章的作者以及认识的相关领域专家（用处不大）\n检查信息，提交', 1736819185, '0', '0', '85');
