INSERT INTO `bilibili_video_comment` VALUES (276, '1558004', '真情润无声', '保密', '我们都是这片土地上的既得利益者。我们的前辈用他们的一生，甚至生命换来了我们今天的和平。我们有什么理由不热爱这片土地，这个国家，这个党呢？', 'https://i2.hdslb.com/bfs/face/30457331fe635e35a88451a766a6cc71b96ef5fd.jpg', 1764559895196, 1764559895191, 247229818528, 113469093314890, '贬值的只是那一张没有含金量的毕业证书，而不是知识。', 1731716625, '6', '0', '292');
INSERT INTO `bilibili_video_comment` VALUES (277, '485400109', '破防是不可能的', '保密', '', 'https://i1.hdslb.com/bfs/face/8a9e595e9072d3a884928143767223a5705b01f5.jpg', 1764559895208, 1764559895206, 247227874096, 113469093314890, '我觉得本科论文的意义，知晓论文格式如何写一篇论文+获得word技能远远＞论文内容，当然部分想钻研的同学除外', 1731713080, '1', '0', '77');
