INSERT INTO `bilibili_video_comment` VALUES (279, '3546647791405930', '热心B站网民', '保密', '', 'https://i1.hdslb.com/bfs/face/f1317d88c91a3b3514bc3e8d4c0c7d8c47ad16b0.jpg', 1764559895227, 1764559895225, 250019322528, 113469093314890, '[滑稽]自己找文献找学姐朋友帮忙给我找了十个文献 然后自己看文献 提炼观点 再改写 借助公zh号上的 耳笔 ,一些没头绪的内容可以提供思路和框架 然后查重 在改写 降虫，绝绝子[热词表情_世萌双冠]', 1734511321, '0', '0', '23');
INSERT INTO `bilibili_video_comment` VALUES (280, '87487271', '账号已注销', '保密', '', 'https://i0.hdslb.com/bfs/face/member/noface.jpg', 1764559895232, 1764559895230, 246921362769, 113469093314890, '如何快速肝出一篇论文：和带你毕设的实验室的学长学姐打好关系，尤其是临近毕业的那些，他们手里都有很多成果甚至是现成的论文[doge]并且可以在你写论文的时候给予指导，别指望你的毕业设计老师手把手教你，这种可能性基本等于0', 1731731484, '0', '0', '23');
