INSERT INTO `bilibili_video_comment` VALUES (299, '604576465', 'flashxiaomang', '保密', '', 'https://i0.hdslb.com/bfs/face/member/noface.jpg', 1764559913245, 1764569118418, 223778858880, 620969943, '我觉得直接在PQDT（国外硕博论文的网站）搜自己毕业论文的关键词，然后找上两三篇跟自己的方向几乎一致的，就A+B（来自第一篇论文的）+C（来自第二篇论文的）会更快，因为从期刊和会议论文上抄毕竟一篇字数少', 1716989250, '6', '0', '93');
