INSERT INTO `bilibili_video_comment` VALUES (338, '344228122', '蓝梦基地', '保密', '', 'https://i0.hdslb.com/bfs/face/member/noface.jpg', 1764559953167, 1764559953164, 252067903728, 113784689530716, '不能一概而论，好论文是需要好的idea、数据分析和写作表达的！', 1736566505, '0', '0', '27');
INSERT INTO `bilibili_video_comment` VALUES (339, '397320755', '白贵妃不醉酒', '女', '我是白白，谢谢大家的关注（比心）', 'https://i2.hdslb.com/bfs/face/31f1bbf5500306fa48bd78f03bb3b70c3e6da0ce.jpg', 1764559957909, 1764560015049, 261205842305, 113928889704397, '检索文献：读摘要，筛选20-40篇足够\n参考文献：引用率高、近几年的文献、权威性高\n选题策略：不要前人研究少的，重点不需要创新，要细要具体\n论文框架：融合几篇论文的结构和小标题\n论文表达：模仿表达方式、每个人的文献提取字数不要多参考文献、适当改图表\n调查问卷方面：给老师看一下调研数据是否可用\n查重：免费网站先查重，再去知网\n关于优秀论文：不需要读博没必要，读博会有优秀毕业论文的加分', 1746503271, '3', '0', '424');
INSERT INTO `bilibili_video_comment` VALUES (340, '18211862', '流殇小蛇', '男', '我应在山林葱葱，酌半杯月光。拂衣轻拨山花红。', 'https://i2.hdslb.com/bfs/face/e846c71790dc58d65d7f01e1c28eb9956df1e605.jpg', 1764559957915, 1764560015064, 254655248305, 113928889704397, '得益于大三参加过省级本科论文征集比赛还拿了银奖，今年毕业，上个月院里突然要求月底交初稿。我二十号开始写，二十一号就甲流了，躺了两天，二十三号又撑起来把材料的结构分析了，二十四号一个通宵直接肝了5k字，最后初稿以8k＋的字数交上去了。要不是病那几天没有脑子去细写，初稿怎么也得往万字写，后续才好删改。我们专业的本科毕业论文要求5k5来着，这次院里要得太急了[笑哭]', 1739512441, '20', '0', '499');
INSERT INTO `bilibili_video_comment` VALUES (341, '379026391', '上进牌栅栏', '保密', '大嘎好，叫我贪牌就好.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n还瞅啥，没啦.', 'https://i1.hdslb.com/bfs/face/5a712def29f319c2b1198ad5c39107640ea1051a.jpg', 1764559957920, 1764560015085, 253751522321, 113928889704397, '我们老师不让我们用硕博论文，就让我们用期刊还得是近五年的…少之又少…九敏啊', 1738677589, '4', '0', '480');
