INSERT INTO `bilibili_video_comment` VALUES (343, '327364281', '逆风生来是天才', '男', '一位致力于摆烂的全方位UP', 'https://i0.hdslb.com/bfs/face/e6a32c465d2bab641a91da1a6e1cab6b75630c3e.jpg', 1764559957929, 1764560015122, 254300628081, 113928889704397, '本科鼠鼠提问，我这边是金融文科，我现在找了十几篇文章，每篇文章找一段缝成自己的论文，然后再把全文用自己的话写一遍可不可以。有点怕内容写的和摘抄内容太相似被看出来会有问题吗', 1739187126, '6', '0', '193');
