INSERT INTO `bilibili_video_comment` VALUES (364, '2128693194', '动次大次打', '保密', '', 'https://i0.hdslb.com/bfs/face/3c69d4479fc41308ed1a3671ba53ba59dbcd9fa0.jpg', 1764560032994, 1764560032990, 279187910177, 115462394416958, '我这段时间的时候感受一样，不能直接抛给它最终需求 —— “帮我就xx问题写一份大纲”，结果大概率就是测试了一堆问题然后发现”能用”的程度不过如此。但在我熟悉领域，我就会更耐心和一步步地提示，过程中确实有打开思路和提高效率。所以说带着玩一玩试一试的心态很可能就没有然后了，带着和它合作的目标真的可以打开新世界。', 1761823402, '0', '0', '3');
INSERT INTO `bilibili_video_comment` VALUES (365, '507035674', '归月寒锋', '保密', '', 'https://i0.hdslb.com/bfs/face/member/noface.jpg', 1764560033000, 1764560032994, 281539969569, 115462394416958, '已三连，666', 1764003006, '0', '0', '1');
INSERT INTO `bilibili_video_comment` VALUES (366, '1372994708', '薄情痞子猛', '保密', '', 'https://i2.hdslb.com/bfs/face/22712cb0ed42cbec32b842e8fe017f45bf852e91.jpg', 1764560033008, 1764560033006, 280899368544, 115462394416958, '不是AI太强了，而是国内的学术圈太弱了，滥竽充数者写的辣鸡论文占了80%(客气的说)。ChatGPT反而是一个契机，既然要卷那大家都用工具往死里卷，把那些个滥竽充数的老学究拍死[doge]', 1761823824, '0', '0', '1');
