INSERT INTO `bilibili_video_comment` VALUES (374, '65612373', 'Forrest___', '保密', '', 'https://i0.hdslb.com/bfs/face/aff60bfd8b540191a1f1f3e91239aa174999b0d8.jpg', 1764560041969, 1764560041966, 166287928752, 911387436, '这个观点我同意，我导师就这样，他说博士师兄的论文不行录不了，博士师姐的论文很好，容易录，但结果却是师兄的录了，师姐的被拒了。我小论文也是，他说估计录不了，然后就录了[藏狐][藏狐][藏狐]', 1684662756, '4', '0', '133');
INSERT INTO `bilibili_video_comment` VALUES (375, '4708929', '蜀国神童张顺飞', '保密', '你怎么说话都具有攻击性的呢，我觉得人与人之间的交流应该多点善意吧​', 'https://i0.hdslb.com/bfs/face/a6235156be56a5c1f87d5a2680c17740d5af42b5.jpg', 1764560041978, 1764560041972, 166317825744, 911387436, '我的论文终于投出去了，真希望有个眼瞎的能接了，不要拒我，大修也愿意😤', 1684673992, '4', '0', '85');
