INSERT INTO `bilibili_video_comment` VALUES (377, '300730365', '遇健李的幸运', '保密', '多思多谋多动手', 'https://i0.hdslb.com/bfs/face/a051403e00b8868c98136460f9605bc923d50379.jpg', 1764560042005, 1764560042000, 166310586320, 911387436, '问题是短周期期刊太难找了，找到了也是OA的三千多刀的，太蓝了[大哭]\n请问有没有好的方法找这类短点周期的期刊？', 1684671270, '4', '0', '29');
