INSERT INTO `bilibili_video_comment` VALUES (394, '256269296', '____逍遥____', '保密', '', 'https://i2.hdslb.com/bfs/face/49703447f59b10dfc76e59713ed6815027a1a528.jpg', 1764560059910, 1764569776658, 160343370384, 654793344, '根据我的经验，大部分专家其实都是外行，你的格式方面、条理逻辑的问题一定要尽量避免，因为他们会挑他们看得懂的去抓，太细节的基本上很难遇到懂的，那种囫囵吞枣知道个大概的居多', 1681229071, '22', '0', '389');
