INSERT INTO `bilibili_video_comment` VALUES (396, '1826037', 'D_Flun', '保密', '', 'http://i0.hdslb.com/bfs/face/20b696af9ba3968b666074444a83b4f4652bd5a1.jpg', 1764560059921, 1764569776669, 160317976576, 654793344, '我当初工科专业一篇一区一篇二区捏成自己的大论文。三个盲审专家混进去一个脑瘫，说硕士应该做不出这样的成果怀疑我剽窃导师的论文，直接给了40分', 1681219747, '10', '0', '286');
