INSERT INTO `bilibili_video_comment` VALUES (398, '14368515', '大程子0', '男', '天气好热，天天游泳', 'https://i0.hdslb.com/bfs/face/9b4be58f5e06833ec632482ebb0f77080440cf4c.jpg', 1764560059929, 1764569776677, 160343316368, 654793344, '论文不是那么好混的，硕士博士论文看个几篇，你也会觉得有些论文内容有想法，表征手段丰富，有深入研究（比如模型机理计算等等）。有一些就是以一个什么基掺杂改性，改一点点也算一章，拍拍电镜表征一下基础性能完事了，每一章都差不多。老师看得多了这些个套路都知道，只不过点不点破而已', 1681229093, '4', '0', '160');
