INSERT INTO `bilibili_video_comment` VALUES (561, '14184004', 'Oedon', '男', '就是一个臭打游戏的', 'https://i1.hdslb.com/bfs/face/c904079b0fa8c35b0f52d4a13c0875830e6696c1.jpg', 1764569354054, 1764569354052, 253969547808, 113912901013613, '[热词系列_知识增加]一直有个问题想请教，强化学习训练部分的reference model是如何得到的，用这种架构训练的模型为什么不会把模型的性能上限限制在reference model', 1738291051, '6', '0', '83');
