INSERT INTO `bilibili_video_comment` VALUES (564, '287874668', '神在明', '男', '制作进行', 'https://i2.hdslb.com/bfs/face/1f254489b20735881cd8c0eb81413e6c0050d353.jpg', 1764569354067, 1764569354065, 253491137553, 113912901013613, 'up能出一期省流版视频吗？讲讲deepseek它的意义和误区吗？我是一个很想了解deepseek的人，但是现在网上讨论特别混沌。\n有说deepseek颠覆ai业界的，有说deepseek纯粹是抄袭openai的数据的。但是始终没有一个真正的ai从业者给出准确的答案。我现在不知道deepseek究竟是吹的还是真材实料。', 1738430401, '11', '0', '57');
