INSERT INTO `bilibili_video_comment` VALUES (580, '441623437', '人笑癫狂', '保密', '从金钱末日视频开始，试图构建一套全新的符合时代发展的哲学观，辩证物心主义是为了纠正马克思唯物主义的不足，欢迎看完后给出批判，每个批判都有帮助', 'https://i1.hdslb.com/bfs/face/3e762e48311a81fc1b5dfcd24c81b5b92199afdc.jpg', 1764569404237, 1764569404234, 284014157824, 115638555250966, '我现在需要一个真正靠谱的大模型，因为这个很关键', 1764550762, '2', '0', '0');
