INSERT INTO `bilibili_video_comment` VALUES (624, '29676429', '李氪弱', '保密', '', 'https://i0.hdslb.com/bfs/face/e1f6394d622870c3b8c33f6b9dce641d74576502.jpg', 1764569521731, 1764569911571, 277604781824, 115285931592805, '拉瑞导，都教画图了，还需要一期SCI文章格式排版的教程！！！', 1759221633, '4', '0', '2');
INSERT INTO `bilibili_video_comment` VALUES (625, '258033449', '江晚予7', '女', '', 'https://i2.hdslb.com/bfs/face/7252789eb95fc0b7ecdcd75e7cc2e39e25787c44.jpg', 1764569537108, 1764570317422, 97505798896, 507380536, '课程论文如何写？\r\n一、选题：\r\n老师课堂提到的（方便，但易翻车）/自己选感兴趣的\r\n判断选题是否合适？选题范围不能太大太小\r\n选题+知网使用教程：\r\n1.主题词检索感兴趣的选题\r\n2.被引次数最高的，需重点关注-业内都会看的-忽略这些，老师会认为没认真查文献\r\n3.知网高级检索：北大核心，cssci---排除差期刊\r\n发表时间排序  最新的文献\r\n旧理论研究新现象 次主题进一步缩小范围。2-3篇 🉑️ ，没人写则没基础也不太ok\r\n\r\n二、论文框架：\r\n1.导言、引言\r\n（1）主题，写什么\r\n（2）研究问题，什么问题引导做研究\r\n（3）问题发生的背景，让读者认同你做的研究\r\n（4）前人相关研究情况（最重要）\r\n输入关键词-文章类别-综述型论文/或者次要主题选择综述—点击相关度排序\r\n名校硕博论文-中文知网,英文https://www.pqdten.com/,https://www.proquest.com/\r\n2.主体（不同学科不一样）\r\n3.结论\r\n（1）再次强调研究内容（重复）\r\n（2）总结主要观点（观点、方法总结）\r\n（3）提出解决方案或建议（回应导言部分的问题，给出方案建议）\r\n（4）指出研究不足（写出没做好的，很重要，让老师知道有些没办法解决）\r\n三、查重率\r\n1.调换句子顺序（因果互换，现象结论互换）\r\n2.改变关键动词或句式（主动句改被动句）\r\n3.对原文扩展或压缩\r\n四、格式模板：链接在学姐视频简介中自取', 1641351674, '3', '0', '1042');
