INSERT INTO `bilibili_video_comment` VALUES (631, '508913188', '连id也在摆烂', '男', '', 'https://i1.hdslb.com/bfs/face/fb15229eadb714d17b5725371a17690d663381eb.jpg', 1764569596872, 1764569596871, 282046667889, 115637632369760, '我rtdetr从一区kbs, 二区neurocomputing, 三区CVIU，四区rtip都被拒了[笑哭]。kbs是aim and scopes，nc是创新性不足，偏应用，cviu是we两个月，发了催稿被拒，rtip是重复度太高（我投了arxiv），rtip这个我已经在cover letter说明了是arxiv，还给他发了解释的邮件但没回，目标检测非oa感觉不太好投了，也有可能是我选刊不当[笑哭]。', 1764492214, '15', '0', '9');
INSERT INTO `bilibili_video_comment` VALUES (632, '701042004', 'bili54707862802', '保密', '', 'https://i0.hdslb.com/bfs/face/f777d28cdb22f1c4f745801fdcc75ac4501fcf6f.jpg', 1764569596878, 1764569596874, 284030103840, 115637632369760, '导，老师无指导，无要求，现在想用yolo11做,请问怎么去选择我的数据集？或者什么好做一些？', 1764563874, '1', '0', '0');
