INSERT INTO `bilibili_video_comment` VALUES (644, '1427918135', '紫薯小甜妹', '保密', '', 'https://i2.hdslb.com/bfs/face/187a27392d66150dc4e212beab56d1606463b5fb.jpg', 1764569616746, 1764569734676, 231425603104, 1206178820, '太太太有用了，谢谢师兄！！非常有帮助，但是我在阅读的时候有一个疑问，如果一直添加注释笔记的话，都是直接引用的作者的原文，那我们是在写的时候再进行改写吗？还是添加笔记的时候就用自己的话把原文说出来？', 1720951665, '2', '0', '30');
