INSERT INTO `bilibili_video_comment` VALUES (658, '3493286492768839', '宇迪讲AI', '女', '需要系统学习课程、论文指导、就业指导、项目指导的小伙伴可以后台私我！', 'https://i1.hdslb.com/bfs/face/3d9fc843b6f7b2302d7f094ba08185be74c18812.jpg', 1764569630145, 1764569630143, 283840018016, 115631508685184, '感谢小伙伴们对新人UP主的支持，关注我，持续更新更多优质内容', 1764402509, '0', '0', '1');
INSERT INTO `bilibili_video_comment` VALUES (659, '14048403', '不爱吃花椒的刺猬酱', '保密', '', 'https://i0.hdslb.com/bfs/face/fcb22a7d642c4d412290f97a9e3a94d39d72a8f5.jpg', 1764569634848, 1764569730205, 5536195341, 975879338, '1.title\n2.abstract\n3.introduction\n4.method\n5.experiments\n6.conclusion\n第一遍：标题、摘要、结论。可以看一看方法和实验部分重要的图和表。这样可以花费十几分钟时间了解到论文是否适合你的研究方向。\n第二遍：确定论文值得读之后，可以快速的把整个论文过一遍，不需要知道所有的细节，需要了解重要的图和表，知道每一个部分在干什么，圈出相关文献。觉得文章太难，可以读引用的文献。\n第三遍：提出什么问题，用什么方法来解决这个问题。实验是怎么做的。合上文章，回忆每一个部分在讲什么。', 1633513380, '3', '0', '1214');
INSERT INTO `bilibili_video_comment` VALUES (660, '15895536', '路路Routine', '保密', '爱好 Go，AI，羽毛球。学习中～', 'https://i0.hdslb.com/bfs/face/886c73fb54d98b0d92d0fa2569ffc8cf8b3a73f0.jpg', 1764569634854, 1764569730212, 5534081863, 975879338, '第一遍：关注标题、摘要、结论，看是否自己研究的相关。看完之后可以看部分实验和方法里的关键图和表，进而判断这篇论文是否适合自己\n\n第二遍：忽略部分细节，看懂重要图和表里的每个词，方法对比等。圈出部分重要文献。看懂文章针对的问题、解决方法、效果怎么样\n\n第三遍：最详细的一遍，知道每一段和每一句干什么，脑补过程、换位思考', 1633493168, '0', '0', '591');
INSERT INTO `bilibili_video_comment` VALUES (661, '107986124', 'Rabittoo', '男', '林下漏月光，疏疏如残雪。', 'https://i2.hdslb.com/bfs/face/c9e0f2c7976450ac27ac5c02431b56da6efcf15f.jpg', 1764569634860, 1764569730219, 5532911133, 975879338, '血书详细解读attention all you need 这篇[微笑]', 1633480590, '8', '0', '275');
INSERT INTO `bilibili_video_comment` VALUES (662, '87205031', '金黄梦里', '保密', '', 'http://i2.hdslb.com/bfs/face/d0240c76c46b5b867e6984b394175863c635c3d9.jpg', 1764569634868, 1764569730224, 5533611626, 975879338, '老师我想问问，如何将读论文和看懂代码相结合呢，我研究生入学一年了，论文看得也不少，但对于理解源代码，再加上融合自己的想法进行实现还是很困难，之后老师会结合代码讲论文吗', 1633488788, '24', '0', '190');
