INSERT INTO `bilibili_video_comment` VALUES (690, '1560689', '陈博衍_', '男', '因果推断只是叙述框架。', 'https://i2.hdslb.com/bfs/face/6e8ae4662f64271f79d45a2f79fc38bcf9120fb3.jpg', 1764569721277, 1764569721271, 273510147585, 115132352961954, '这都不复杂, Reduced Form 都是 Toy Model, 结构估计稍微上点强度, 也就是个高级点的 Toy Model\n真正复杂的是这OO的玩意 怎么搞到那么多搞不到的数据的 他怎么做数据调整的\n\nPPT这方面建议抄 刘西川 [偷笑]', 1756784062, '0', '0', '11');
