INSERT INTO `bilibili_video_comment` VALUES (791, '3493287113525517', '2次元dog', '男', '', 'https://i0.hdslb.com/bfs/face/6cfb8ac32b1f00767a2f23aab004fad19b138f5f.jpg', 1764570021467, 1764570021465, 283569611040, 115387551323501, '真是太难了，导师放养，小论文根本没人指导，我当时也是找了靠谱外援的普刊，确实要比自己瞎琢磨强多了，从写到录用才用了两个多月', 1764152631, '0', '0', '0');
