INSERT INTO `bilibili_video_comment` VALUES (846, '82474577', 'Wdszj', '男', '石页三共福', 'https://i2.hdslb.com/bfs/face/d7e0bb0dbcafc3da1dcf9f950585f327d90f8ba1.jpg', 1764570259740, 1764570849820, 5665848316, 506354287, '你好，我是聋人，对你这些视频很有感兴趣，可是没有字幕，听着听着挺费力的。。我不知道其他UP大主，怎么做到有字幕啊？都是后期处理的吗？这样工作量不止翻了几倍啊。。。。如果你觉得累，可以不用加字幕了，我用自己APP讯飞软件来翻译，有一些不准。。。。。如果你有条件的话，可以交给负责字幕组来添加字幕，可以分红。如果没条件的话，付出成本不成比例，千万别为我加字幕，先感谢你提供这些珍贵的经验！！', 1635494767, '87', '0', '3602');
