INSERT INTO `bilibili_video_comment` VALUES (861, '12916579', '拂小九', '女', '', 'http://i1.hdslb.com/bfs/face/70d53beec0e07a6d211dee3eba9fb0f98176f2b7.jpg', 1764570303753, 1764570303751, 5452252576, 250580455, '想当年，满心激动地打算学latex，最后在“请提交word版论文”面前低了头', 1632396983, '11', '0', '682');
INSERT INTO `bilibili_video_comment` VALUES (862, '66431435', '黑色是真爱的颜色', '保密', '', 'https://i2.hdslb.com/bfs/face/f9f29f07919beca1e6d4dee3d7c202f45f9e5775.jpg', 1764570303758, 1764570303757, 5443300318, 250580455, '第一次接触texstudio是在大三写某项目论文，我数学专业的，导师直接让我们复制了格式段于是不用自己扣排版了。出国以后写作业交报告也会用到各种markdown，真的好用，比word排版方便太多。\n有时候会觉得写一些公式麻烦，推荐一个小程序mathpix，这玩意可以识别公式换成代码，效率神器', 1632250060, '23', '0', '928');
