INSERT INTO `bilibili_video_comment` VALUES (888, '1450936478', '我爱吃超级棒棒糖-', '保密', '', 'https://i0.hdslb.com/bfs/face/member/noface.jpg', 1764570390538, 1764570390536, 281746863649, 115603591397719, '我是真没辙了，开题磨俩月越改越乱，对着文档能坐一下午，跟导师请教，给的全是笼统话，眼看 deadline 逼近，怕毕不了业咬咬牙就找了外援老师，带着补数据、查文献，对我们这种没人带的，顺利弄完论文拿到毕业证，就值了', 1764224341, '0', '0', '0');
