INSERT INTO `bilibili_video_comment` VALUES (906, '689268735', 'XiaoHu1052', '保密', '雷霆雨露，俱是天恩', 'https://i0.hdslb.com/bfs/face/a23b23c2c4c2671a4d21c704f84adc89fec874ba.jpg', 1764570403703, 1764570403702, 266364817520, 114696296336404, '水导，前两年看您视频的时候还是三十万粉左右，在老家录视频规划自救指南的撰写，现在我也快本科毕业了，偶然又刷到您，看你事业有成，粉丝大涨，真的是感慨万分，希望未来一切顺利[奋斗]', 1750579169, '1', '0', '9');
