INSERT INTO `bilibili_video_comment` VALUES (947, '31339705', '地窖外的幻人', '男', '青春作伴好还乡', 'https://i1.hdslb.com/bfs/face/890b8303351e4faeed22132736e49d4009eb5d6f.jpg', 1764570564659, 1764570564655, 270763384320, 114946612397210, '我只说引用这部分吧，我们学校坐标香港，要求按照哈佛引用，哈佛引用到最后就是没有序号只按照第一作者的姓名进行排序，合理怀疑她的论文是从外网学位论文进行了借鉴。', 1753947936, '42', '0', '6785');
