INSERT INTO `bilibili_video_comment` VALUES (955, '243849064', '十几万的答案', '保密', '世纪末彼岸花丛中的死之结界', 'https://i1.hdslb.com/bfs/face/e262e3127181ec40177c9927f3714490a4457fc9.jpg', 1764570578963, 1764572129864, 257915303985, 114114311491082, '你要先把抄作业的理论先搞懂，不是AI写完就交了，你还得看一眼，读了那么多年书，知识我都还给老师了，可是怎么抄作业我还是会的[doge][doge][doge][doge]', 1742966185, '1', '0', '146');
