INSERT INTO `bilibili_video_comment` VALUES (990, '3546912850447039', '玻璃窗故事书', '保密', '', 'https://i1.hdslb.com/bfs/face/be8866ef799f2facbfcb86027c228416b70ba350.jpg', 1764570688845, 1764570688843, 267669916624, 114781189054364, '现在投刊越来越难，小论文难的不是写出来，难的是投出去，现在就和被垄断了一样，普通人不走渠道根本投不出去，我被反复拒稿好几次，终于放弃自己了，找师兄要的人脉，大小论文全包怕，小论文sci三区顺利见刊，可以分享成功经验', 1751687345, '0', '0', '6');
