INSERT INTO `bilibili_video_comment` VALUES (1013, '3400520', '锕瀞瀞', '保密', '( •̀∀•́ )   ', 'https://i2.hdslb.com/bfs/face/7731f043db2b001d45ada65f51f57ea43d3b921f.jpg', 1764570720004, 1764570719999, 147884665552, 806123446, '您好会讲！！！！您是老师们的互联网嘴替！！\n我已经怀着激动的心用颤抖的手把您的视频推给了我的导师、同门、做老师的师兄了希望除了播放量增加没有给您带来困扰[热词系列_知识增加]', 1674094807, '1', '0', '63');
INSERT INTO `bilibili_video_comment` VALUES (1014, '107947591', '火树银花閤', '女', '', 'https://i1.hdslb.com/bfs/face/db8cddf2fd9f9642953479906f9f83ff44e2ea45.jpg', 1764570720026, 1764570720022, 5698151635, 806123446, '对我来说最难的就的是我知道自己在写学术垃圾，但是又不得不硬着头皮把垃圾包装的漂漂亮亮的给人家展示你的垃圾里都有什么[笑哭][笑哭]', 1635945829, '7', '0', '1154');
INSERT INTO `bilibili_video_comment` VALUES (1015, '22525684', '沙拉酱的Wi-Fi', '保密', '', 'http://i0.hdslb.com/bfs/face/member/noface.jpg', 1764570720041, 1764570720037, 5689559008, 806123446, '其实有的时候不太懂，明明几句话加几个分析例子就可以讲的很明白，为什么要用很多羞涩难懂的句子', 1635825723, '13', '0', '548');
