INSERT INTO `bilibili_video_comment` VALUES (1043, '3632304691874184', '空气像青苹果11', '女', '希望可以更上一层楼', 'https://i0.hdslb.com/bfs/face/38b7b0d81467b3d0c2f865bc44f41df2bf983674.jpg', 1764570812041, 1764571456745, 281745203105, 115614748316118, '多看看文献，找导要个方向最好能给你个题目，或者找辅导，看你怎么想[笑哭]我导师纯放养，索性找的辅导，从开题就一章章带着写，给我理大纲搭框架，凑了三章工作量，修改润色了三次才定稿，盲审还得了双A[笑哭]', 1764222611, '3', '0', '0');
