INSERT INTO `bilibili_video_comment` VALUES (1071, '291288327', '常山太守', '保密', '', 'http://i0.hdslb.com/bfs/face/93051b9fe3d978a7689dc2b8cfb9bd6fa418fd92.jpg', 1764570854223, 1764570854222, 283982256576, 115638420905315, '读研都会有这种经历。目前只能调结构，改题目。尝试按答辩组的要求梳理框架，适当增加内容。如果答辩组只否定选题，没有任何可操作性的建议的话，建议忽略。', 1764510118, '0', '0', '7');
