INSERT INTO `bilibili_video_comment` VALUES (1126, '544410173', 'HLyyy_', '保密', 'Be yourself。', 'https://i2.hdslb.com/bfs/face/f4ac4b39d0c561e6b8598b775dee3239c4918e58.jpg', 1764570966916, 1764570966915, 273918623761, 115155975278546, '盖。俺为了此高考把俺头发剪成了一个朵拉。', 1757166994, '1', '0', '10');
INSERT INTO `bilibili_video_comment` VALUES (1127, '58754653', '墨佩子', '女', '', 'https://i1.hdslb.com/bfs/face/7786014f0af7982f42682d1c96df2c273c47cf23.jpg', 1764570982575, 1764571347536, 218980048640, 1903544893, '事实证明就是这样。 自己花上个把星期 参考下思路与框架。 哪怕做成💩一样 你也要自己经手一遍。在找机构或者熟人跟你规范格式 数据排版还差不多。 在外面没有一个人会真心帮你的记住。 给钱也不会。 大家都有自己的事情要做，赚你一点智商钱何乐而不为', 1714317304, '1', '0', '249');
INSERT INTO `bilibili_video_comment` VALUES (1128, '110087660', '盖世无敌兔', '保密', '', 'https://i2.hdslb.com/bfs/face/871582985c6c487633b53fd59fe49ae7a8bc8d58.jpg', 1764570982592, 1764571347544, 219403416928, 1903544893, '还是不舍得花钱，真有钱直接以横向的形式找研究所外包就行了，协议成果归你就行，自己搞论文框架和绪论，后边外包。合理合法', 1714565145, '8', '0', '229');
INSERT INTO `bilibili_video_comment` VALUES (1129, '92331911', 'Dream丶铁哥', '男', '计算数学专业硕士在读(方向：偏微分方程理论与反问题)\n会更新一些自己喜欢的视频\n坚定的唯物主义者\n反问题交流群:678663583', 'https://i2.hdslb.com/bfs/face/a5cf14e0d6a61ad27e3efffa443f0528e8289e40.jpg', 1764570982601, 1764571347555, 218879784416, 1903544893, '数院的，我记得当时班上有个同学，本科毕业论文内容是“幂级数”，找代写，给写了个“幂函数”[doge]', 1714273415, '4', '0', '134');
