INSERT INTO `bilibili_video_comment` VALUES (1138, '41372351', '你的牌太多啦', '保密', '咪呀', 'https://i2.hdslb.com/bfs/face/62eedfd0f5b29773c5c8f7f6b3c641feb17f8930.jpg', 1764570991581, 1764570991579, 109724042944, 97029804, '感觉自己能犯的错都犯过了\nr199是命令输错了 要再检查一遍\nr109是数据code或者year列没有转化成数值型\nr608需要改一下xxx的名字', 1650273065, '91', '0', '792');
INSERT INTO `bilibili_video_comment` VALUES (1139, '298514344', '弥凉暮是叭', '保密', '博学而笃志，切问而近思', 'https://i1.hdslb.com/bfs/face/53ee6e30fe0492d7f7e0d4008fd5727138989e45.jpg', 1764570991585, 1764570991584, 95088928640, 97029804, '下载oureg2出现603的可以试试先输入下面这个命令\nsysdir set PLUS \".\\ado\\plus\"\nsysdir set PERSONAL \".\\ado\\personal\"', 1639386826, '84', '0', '395');
INSERT INTO `bilibili_video_comment` VALUES (1140, '12590442', '像素gene', '保密', '', 'https://i0.hdslb.com/bfs/face/27c610fd84776162cb75c70bec3d530c2438b19c.jpg', 1764570991590, 1764570991588, 2913816841, 97029804, 'outreg2无法打开word，出现了r(603)\n措施:\n自己先在ado文件下新建一个word，然后运用outreg2时，文件保存路径就按如下写，就好了！\n. outreg2 using  \"C:\\ado\\myfile\\results.doc\"\nc:\\ado\\plus/o/outreg2.ado\nC:\\ado\\myfile\\results.doc\ndir : seeout\n. seeout using \"C:\\ado\\myfile\\results.txt\"\nHit Enter to continue.', 1589808974, '12', '0', '274');
INSERT INTO `bilibili_video_comment` VALUES (1141, '135513836', 'luluciag', '女', '春风十里扬州路，卷上珠帘总不如', 'https://i2.hdslb.com/bfs/face/17ebbd78421dbed5ff0db4f4502a1c17dae4e54a.jpg', 1764570991593, 1764570991592, 2915733217, 97029804, '感谢UP小姐姐的帮助，不过我用的是16，那个Outreg2命令下载是在后面加一个逗号和replace就可以成功，不会出现r(2)的命令，感谢某条弹幕的提是', 1589857349, '11', '0', '162');
