INSERT INTO `bilibili_video_comment` VALUES (1189, '72530765', '麻烦的包子', '保密', '我觉得我还能抢救一下', 'https://i2.hdslb.com/bfs/face/08615491ccfd1d17b16dc82fa00ebcd30e34f3a2.jpg', 1764571199584, 1764572225484, 139073427504, 347983220, '作为图书排版的，我在这里跪谢up，要是所有人都按规范做word，我们书籍排版的也不会那苦，都是泪，id是可以映射word的样式的，但大多数word是幼儿园水平，全文混乱的跟混沌摆一样，我排一本2000页的企业管理，掉的头发能每页夹好几根[跪了]', 1669396863, '27', '0', '498');
INSERT INTO `bilibili_video_comment` VALUES (1190, '1376508', '小透明的路过', '保密', '', 'http://i0.hdslb.com/bfs/face/member/noface.jpg', 1764571199588, 1764572225490, 139055868704, 347983220, 'up主基本树立了从plain text到一个排版规范的文档的思路：\n1、直接改样式，修改样式中的字体和段落格式，图片、表标题、图标题，\n2、定义多级标题链接样式。\n3、批量应用格式，查找替换和格式刷\n以上可以实现标题自动编号，编辑后自动更新编号\n4、文献引用自动编号\n5、公式和公式的引用-制表位、对齐方式，题注，根据章节编号\n6、图片编号和引用\n7、对文章内容进行分节：目录，首页、\n8、插入目录（记得更新域），图标题、表标题\n9、设置页码（注意从正文开始计数）', 1669388411, '7', '0', '367');
INSERT INTO `bilibili_video_comment` VALUES (1191, '11981045', '沉思录renege', '保密', '', 'http://i2.hdslb.com/bfs/face/a6ecad5a4244430a057f8c3c7753a122ae4e7189.jpg', 1764571199591, 1764572225493, 140015246112, 347983220, '所以我现在真的觉得计算机二级Office应用真的很值得考，论文排版excel公式应用什么的分分钟整明白，我身边的朋友为word和Excel苦恼时都来找我解决问题[点赞][点赞][点赞]', 1669916190, '11', '0', '138');
