INSERT INTO `bilibili_video_comment` VALUES (1214, '1648458931', '同学聚会暴打初恋', '女', '我是皇帝', 'https://i1.hdslb.com/bfs/face/c8136ec745e4645711e8c7240cc46b5374331559.jpg', 1764571230865, 1764571230863, 282176101104, 115401576939590, '导师放养，小论文根本没人指导，我当时也是找了个辅导教我写发了一篇SCI，确实要比自己瞎琢磨强多了，从写到录用才用了五个多月，真的快，最主要价格也挺合适的', 1762865166, '0', '0', '1');
INSERT INTO `bilibili_video_comment` VALUES (1215, '3546916375759038', '柠檬醋精', '保密', '', 'https://i0.hdslb.com/bfs/face/9942155454b7460c570e90ee42b21546b1b2077c.jpg', 1764571230869, 1764571230868, 281707884352, 115401576939590, '论文直接花钱找老师带着写了  导不管真没招了', 1762484867, '1', '0', '1');
INSERT INTO `bilibili_video_comment` VALUES (1216, '3546570238724239', '小卡拉猫咪', '保密', '', 'https://i1.hdslb.com/bfs/face/9a70b8741096ebd8624fc10e9721fa971e6c1c02.jpg', 1764571230874, 1764571230873, 281548595456, 115401576939590, '我计算机，不过毕业后完全转行，是去银行工作，感觉毕业论文毫无意义，单纯浪费时间。去年我研三那会是搞深度学习，搞来搞去耽误找工作，也弄不明白，不过为了毕业，我找别人帮我写了模型和大论文，已毕业，很无奈。', 1762336635, '0', '0', '1');
