INSERT INTO `bilibili_video_comment` VALUES (1247, '298075666', 'AI云办公助手', '保密', 'AI云办公助手轻松撰写毕业论文、开题报告、任务书及答辩PPT，让毕业轻松快捷\n去体验：yikutian.com', 'https://i1.hdslb.com/bfs/face/4e4c5a9f8bc731bc09a7939818fa113f540d0d5f.jpg', 1764571356497, 1764571356491, 266164857937, 114221719224449, 'WX搜：AI云办公助手\n在线一键撰写毕业论文，开题报告（中/英），答辩ppt，文献综述及任务书，亮点[喜欢]\n1、快捷引用文献，知网可查，免费降重，并且正确标记引用文献，文献自动筛选并按顺序引用，基于deepseek大模型写作\n2、自带查重（结构查重，内容查重，纠错）\n3、排版标准样式规范，下载即用\n4、无偿智能选题，可引用内容写作\n5、可引用已有文案写作\n6、答辩ppt可自定义主色调，可选模板，海量模板免费下载', 1751344497, '0', '0', '4');
