INSERT INTO `bilibili_video_comment` VALUES (1265, '677052607', '玉米味樱花', '女', '', 'https://i1.hdslb.com/bfs/face/778099716b6a59cba257a528ba7a23e0cf8dcc0c.jpg', 1764571382799, 1764571382791, 245312851504, 113349102733893, '1.重要文献打印出来反复读，盘包浆\n2.PDF阅读器UPDF\n3.先写出初稿，不要有完美主义不要有拖延，后面再慢慢改\n4.论文框架去读核心期刊，模仿他们的语言框架，多看才有输入\n5.看师兄师姐投的什么期刊，减少信息差', 1729695574, '1', '0', '171');
INSERT INTO `bilibili_video_comment` VALUES (1266, '473018527', 'AI视频总结', '保密', '关注并在评论区@我可触发AI视频总结，关注公众H【AI工具汇】自取免费的AI工具和资料', 'https://i1.hdslb.com/bfs/face/46a4ef180059999e23ce417b769e07349fb3911b.jpg', 1764571382811, 1764571382806, 245216589760, 113349102733893, '课代表总结：\n发第一篇论文，研一必看！\n1. **导师交流**：多与导师沟通，了解论文发表规则，争取导师指导。\n2. **文献阅读**：反复精读重要文献，使用高效工具如UPDF阅读器辅助阅读。\n3. **论文写作**：确定题目和框架，避免拖延和完美主义，反复修改完善。\n4. **投稿策略**：了解不同期刊接受硕士生论文情况，选择合适期刊投稿。\n5. **心态调整**：多次被拒是常态，保持良好心态，坚持到底。\n\n记住，论文发表是个漫长过程，从研一开始准备，不要拖延。祝大家顺利发表第一篇论文！\n--由@空间里太卡 召唤发送，其他AI工具点头像自取', 1729591905, '0', '0', '77');
