INSERT INTO `bilibili_video_comment` VALUES (1268, '291549863', '2上班', '男', '我就是我', 'http://i1.hdslb.com/bfs/face/911bcb3ff989e384002729be06e04cf1a60364d8.jpg', 1764571382825, 1764571382823, 245022513953, 113349102733893, '普刊直接挑好发审稿快的，别拖，这种大概率对读博啥的没什么用，如果是顶刊这个就很难说了，能不能成为顶刊一作除了看课题组水平，最主要的是课题进展，刚好到你这边沉淀完了那就好了', 1729645082, '0', '0', '31');
