INSERT INTO `bilibili_video_comment` VALUES (1320, '1402135900', 'twott0', '保密', '', 'https://i1.hdslb.com/bfs/face/6d2f511ddec9dbf682a7dcaf220d27ae56590437.jpg', 1764571513362, 1764571513360, 281569296784, 115486218062953, '不太了解相关概念，想问点问题，期待并感谢大佬解答[脸红]\n这个工具是专门收集论文需要的调查数据的吗？不写论文也可以用吗？听up说信度有0.89，是搜集的调查数据可信度有89%的意思吗？', 1762349334, '1', '0', '5');
INSERT INTO `bilibili_video_comment` VALUES (1321, '347069061', '不知道叫什么97', '保密', '', 'https://i0.hdslb.com/bfs/face/e30b3383dbe7effd78085d90024a4cac6df5c502.jpg', 1764571513368, 1764571513367, 279740105009, 115486218062953, '确实好用，哈哈，一开始拿作业试水，发现没啥问题。现在论文也搞定了，还便宜的一批。。。良心，点赞', 1762309546, '0', '0', '4');
INSERT INTO `bilibili_video_comment` VALUES (1322, '435530921', '不知名数学家小P', '女', '历年比赛助攻汇总：  https://docs.qq.com/sheet/DYVdZaVBXYmRyRnp2?tab=BB08J2', 'https://i2.hdslb.com/bfs/face/58cbecad5c8dc8218e5356947bd1d5270aeec9be.jpg', 1764571513372, 1764571513371, 281513931168, 115486218062953, '非广告，纯自来水推荐~\n这个宝藏工具是我之前写论文时，为了收集问卷偶然发现的。实测下来，收集到的问卷质量非常高，没有机刷的情况。收集的问卷是全部通过wjx的 AI 清洗 功能，数据可靠性很不错。\n我之前一共收集了两千多份问卷，做了信效度检验，结果相当满意——信度达到 0.89，效度载荷基本都高于 0.6。整体问卷的结构效度也很稳，真心推荐给正在做论文、需要问卷数据的朋友们！', 1762309427, '0', '0', '3');
