INSERT INTO `bilibili_video_comment` VALUES (1366, '150058447', 'hehuiandtao', '保密', '', 'https://i0.hdslb.com/bfs/face/member/noface.jpg', 1764571627800, 1764571627797, 277660812256, 114959748963133, '开始觉得有可能是我要他写的太多了，就改为只写病理生理这一部分，结果发现11篇引用文章接近一半找不到原文，她的结论可能对的，实验号都一样，但是文章名字或者发表期刊就是对不上', 1759254630, '1', '0', '2');
