INSERT INTO `bilibili_video_comment` VALUES (1449, '290060563', '躺不平的Zoey', '保密', '我这潦草的人生', 'https://i1.hdslb.com/bfs/face/7e8389579d9b1609f3a50f2826c196ecd84ca4f0.jpg', 1764571855035, 1764571855032, 256808222545, 1052152704, 'deepseek都救不了我，真的没办法平衡省考和论文，我直接找辅导带着写完的，催着我上课，写了满满三章工作量，写完还给我修改了三次才定稿[笑哭]刚过审', 1741770799, '2', '0', '11');
