INSERT INTO `bilibili_video_comment` VALUES (1466, '3546639035795567', 'AI总结视频', '保密', '关注并在评论区@AI总结视频 可自动触发召唤技能', 'https://i2.hdslb.com/bfs/face/6a680897810f07713a0b20a3dd8782476a4a0b72.jpg', 1764571885550, 1764572078134, 232839455216, 1506476679, '课代表总结：\n- 视频作者对论文辅导机构的合作持谨慎态度，强调自己未曾与任何论文辅导机构合作。\n- 合作未成的原因是对方无法满足作者提出的无条件退款的要求。\n- 视频作者认为论文辅导机构存在违规行为，且可能涉及学术不端和学术造假，风险较高。\n- 作者提出自己的研究生自救指南，认为比辅导机构更可靠。\n- 作者强调论文辅导机构的价格可能不高，但风险大，建议不要轻信低价。\n- 最后，作者提醒读者，有些事情看似简单，实则复杂，建议谨慎行事。\n--内容由@AI视频总结 生成，仅供参考【总结工具关注自取】', 1721575979, '2', '0', '133');
