INSERT INTO `bilibili_video_comment` VALUES (1508, '37070730', 'AllenCamus', '保密', '伤逝', 'https://i0.hdslb.com/bfs/face/72f225ba935af151a6baae8b0db4a6c471a2a6a4.jpg', 1764571971084, 1764572116128, 267391861680, 114777229625082, '这个也不叫用AI写论文啊，类似手段，以前有百度翻译谷歌翻译的时候就有很多人用了。', 1751451803, '0', '0', '20');
