INSERT INTO `bilibili_video_comment` VALUES (1528, '18161609', '霹雳吧啦Wz', '男', '学习学习。。。', 'https://i2.hdslb.com/bfs/face/40bfd8914b55819ee621e67198d513c93007c0c5.jpg', 1764572001878, 1764572148336, 93779286720, 892100567, '老师讲的真好。[tv_点赞]，在讲多头注意力机制计算时可能讲漏了个点，在多头输出拼接后还要经过一个映射层(全连接层)，然后在接layer_norm等。', 1638261855, '23', '0', '540');
