INSERT INTO `bilibili_video_comment` VALUES (1596, '3546837606730616', 'やうた', '男', 'よく運動し、勉強し 遊び、食べ、休みなさい。', 'https://i2.hdslb.com/bfs/face/98a83e3dc80da95c9048e4ce1b93d8849277e0f0.jpg', 1764572221043, 1764572221042, 282829009216, 115449492736677, '真投降了，自投一直被拒，后面还是花钱找渠道才投出去的，发了篇核心，也见刊了', 1763459675, '0', '0', '0');
