INSERT INTO `douyin_aweme` VALUES (28, '93946107728', 'MS4wLjABAAAADpK820sBniez5e0RMl2LP_S88py1bjQnM0YdBpLVGA8', NULL, NULL, '幺怪读博日记', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_57e3e7c225aed5e40085f0a75bbbf5e8.jpeg?card_type=153&column_n=0&from=327834062', NULL, '', 1764555181744, 1764555192681, 7494534088125058361, '0', '毕业论文怎么写？别怪师姐没教你#论文 #毕业论文 #毕业#论文查重 #量子喵', '毕业论文怎么写？别怪师姐没教你#论文 #毕业论文 #毕业#论文查重 #量子喵', 1744965000, '7723', '3135', '1534', '4172', 'https://www.douyin.com/video/7494534088125058361', 'https://p3-pc-sign.douyinpic.com/obj/tos-cn-i-0813c000-ce/oUf1BbWAJAEEAQgJfVDA8QIxAEA8o77teFZBAK?lk3s=138a59ce&x-expires=2079914400&x-signature=sBwdvY9BcvM9%2F1JUNhTwabhnoJE%3D&from=327834062&s=PackSourceEnum_SEARCH&se=false&sc=cover&biz_tag=pcweb_cover&l=2025120110131192DDE9CBD7594FC58EE7', 'https://www.douyin.com/aweme/v1/play/?video_id=v1e00fgi0000d00usqfog65pul2ovo40&line=0&file_id=971470d6e8cf4d259a5fa22ae054cb3e&sign=a4c0eed1bb20c3ebdb8a685aa84715aa&is_play_url=1&source=PackSourceEnum_SEARCH', 'https://lf26-music-east.douyinstatic.com/obj/ies-music-hj/7494534205427452729.mp3', '', '论文');
INSERT INTO `douyin_aweme` VALUES (29, '2773388864260205', 'MS4wLjABAAAA2E48IjDjs1dX5SsaGgqbfJ4F5iIu7o_KUJ7HfG6jRh5321uqoWm8X0lwQkVhIjQQ', NULL, NULL, '不甘平庸', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o8NjIQIiyiCQ1cIlBDAd6BoJEwiAMLpAAaAvP.jpeg?card_type=303&column_n=0&from=327834062', NULL, '', 1764555181813, 1764557293977, 7547934759604849966, '68', '不会写初稿的都来看看！👏🏻初稿一遍过，那感觉简直飞起! (懂的自然懂)🤔\n1⃣️先把论文拆成小块，分成摘要、引言、理论、现状、问题、对策、参考文献这八大金刚。动笔前，我会在纸上列个清单，特别是摘要和引言，它们可是独行侠。\n2⃣️对于论文新手，可能连论文的框架和内容都摸不着头脑。所以，第二步就是找参考文献。老师们常说要看20-30篇，那是针对深度研究的。毕业论文嘛，看太多反而容易懵圈。我建议挑3到5篇精品文献，足矣。\n3⃣️根据你精选的参考文献，搭建自己的框架。框架要清晰、精确，一目了然能看出你的研究方向。就按我之前说的八大金刚来，别整那些花里胡哨的。\n4⃣️大纲搞定了，接下来就是把你参考的论文,按照自己列的大纲填充进去。填充完毕，基本上初稿就成型了。\n5⃣️最后，建议大家检查一下论文的语句，看看有没有不通顺或者病句的地方，然后调整一下格式，按照学校的标准来。#论文初稿 #文献综述模版  #写论文 #论文开题攻略  #开题报告模板', '不会写初稿的都来看看！👏🏻初稿一遍过，那感觉简直飞起! (懂的自然懂)🤔\n1⃣️先把论文拆成小块，分成摘要、引言、理论、现状、问题、对策、参考文献这八大金刚。动笔前，我会在纸上列个清单，特别是摘要和引言，它们可是独行侠。\n2⃣️对于论文新手，可能连论文的框架和内容都摸不着头脑。所以，第二步就是找参考文献。老师们常说要看20-30篇，那是针对深度研究的。毕业论文嘛，看太多反而容易懵圈。我建议挑3到5篇精品文献，足矣。\n3⃣️根据你精选的参考文献，搭建自己的框架。框架要清晰、精确，一目了然能看出你的研究方向。就按我之前说的八大金刚来，别整那些花里胡哨的。\n4⃣️大纲搞定了，接下来就是把你参考的论文,按照自己列的大纲填充进去。填充完毕，基本上初稿就成型了。\n5⃣️最后，建议大家检查一下论文的语句，看看有没有不通顺或者病句的地方，然后调整一下格式，按照学校的标准来。#论文初稿 #文献综述模版  #写论文 #论文开题攻略  #开题报告模板', 1757390518, '4600', '2371', '883', '5528', 'https://www.douyin.com/video/7547934759604849966', 'https://p9-pc-sign.douyinpic.com/tos-cn-i-0813c001/oAAKAf0YDAFoFAbAifEp6MIivCNQXOigsL9QYA~noop.jpeg?biz_tag=pcweb_cover&card_type=303&column_n=0&from=327834062&l=202512011048128D7BFFE3491CD5D3F84F&lk3s=138a59ce&s=PackSourceEnum_SEARCH&se=false&x-expires=1765764000&x-signature=DvPTBVR%2BGhfKJkw4p4xi5PmPgJ4%3D', 'https://sf5-hl-cdn-tos.douyinstatic.com/obj/ies-music/7349555265001491239.mp3', 'https://sf5-hl-ali-cdn-tos.douyinstatic.com/obj/ies-music/7349555265001491239.mp3', 'https://p3-pc-sign.douyinpic.com/tos-cn-i-0813c001/oAAKAf0YDAFoFAbAifEp6MIivCNQXOigsL9QYA~tplv-dy-aweme-images:q75.jpeg?lk3s=138a59ce&x-expires=1767146400&x-signature=XjxQucPRuq54swU0Wlq