INSERT INTO `douyin_aweme` VALUES (96, '1267102460684350', 'MS4wLjABAAAAL94di55x3DNJ758N-ZNSn-IJMlpzmNG3wEvTFsGf6YUBxmc4MhJDhvQt0p-gzEOf', NULL, NULL, '清栀.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_ef03a26809930c6c3b6fbcb1dc2bd5aa.jpeg?card_type=303&column_n=0&from=327834062', NULL, '', 1764555217027, 1764557325083, 7576841410923121765, '68', '计算机毕设1300贵吗，你们做的是多少钱啊#毕业论文 #毕业设计', '计算机毕设1300贵吗，你们做的是多少钱啊#毕业论文 #毕业设计', 1764120868, '246', '674', '66', '77', 'https://www.douyin.com/video/7576841410923121765', 'https://p9-pc-sign.douyinpic.com/tos-cn-i-0813c000-ce/ogAEASymPtpIfEgAzADleEjSeJW9EkFwAg7Aq7~noop.jpeg?biz_tag=pcweb_cover&card_type=303&column_n=0&from=327834062&l=20251201104843B207841EB0A285D68358&lk3s=138a59ce&s=PackSourceEnum_SEARCH&se=false&x-expires=1765764000&x-signature=Z8D7Wc5lnUDVDjjSyYi95Vu73VI%3D', 'https://sf5-hl-cdn-tos.douyinstatic.com/obj/tos-cn-ve-2774/oUMzvGRFDvQeVQq4DBIhYeFjMCQCnAfhEOaZQ9', 'https://sf5-hl-ali-cdn-tos.douyinstatic.com/obj/tos-cn-ve-2774/oUMzvGRFDvQeVQq4DBIhYeFjMCQCnAfhEOaZQ9', 'https://p9-pc-sign.douyinpic.com/tos-cn-i-0813c000-ce/ogAEASymPtpIfEgAzADleEjSeJW9EkFwAg7Aq7~tplv-dy-aweme-images:q75.jpeg?lk3s=138a59ce&x-expires=1767146400&x-signature=S6x8O8J6QG%2FyUmvqhK7kq3opDhg%3D&from=327834062&s=PackSourceEnum_SEARCH&se=false&sc=image&biz_tag=aweme_images&l=20251201104843B207841EB0A285D68358', '毕业论文');
INSERT INTO `douyin_aweme` VALUES (97, '7572603995027506225', 'MS4wLjABAAAAPXcjcR4UTmSRTZ2KtBvs8xsKBC55fxs4MU_XpVqS8tXVHoMoRKhVzVEIO4oLNL2L', NULL, NULL, '写作的亦菲', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/douyin-user-image-file_8817ebab2455129237ed1c75c8c6d36a.jpeg?card_type=303&column_n=0&from=327834062', NULL, '', 1764555217038, 1764557332620, 7577754020950946954, '68', '开题报告摆烂版通关指南📚。导师看了都夸会谁懂啊！写开题报告像挤牙膏，改到第8版还被导师打回？\n别慌！按导师亲授的「6步公式」写，逻辑+深度直接拉满，小白也能一次过～\n1️⃣ 研究背景：把“选它的理由”说透\n别干巴巴凑字数！核心是「时代趋势+现实痛点」组合拳\n比如写新媒体课题：“短视频流量见顶（趋势），中小商家却没找到精准获客法（痛点）”\n一句话让课题“非做不可”的必要性立住！\n2️⃣ 研究目的：拒绝“我想研究XX”的废话\n按「对象+方法+需求」公式写：\n❌错误：研究直播带货的影响\n✅正确：以XX地区美妆商家为对象（对象），用案例分析法（方法），解决直播转化低的问题（需求）\n目标感拉满，导师一眼看懂你要做啥！\n3️⃣ 选题意义：从“理论+实践”双押\n别只说“有意义”！要拆成两句干货：\n▪️理论：能补啥空白？比如“完善中小商家直播运营的理论框架”\n▪️实践：能帮谁解决啥？比如“给美妆商家提供可落地的转化策略”\n价值感直接拉到满分💯\n4️⃣ 国内外研究现状：别当“搬运工”！\n先分别梳理：国外研究到了哪步（比如欧美侧重用户行为）、国内有啥进展（比如侧重平台规则）\n关键是最后要「评+述」：\n“现有研究多聚焦头部品牌（评），但没覆盖中小商家的实操痛点（述）——这正是我要补的缺口！”\n一句话凸显你的创新点✨\n5️⃣ 研究内容：搭好“论文骨架”\n别写“第一章写XX”！要带逻辑：\n“先分析中小商家直播现状（章1）→ 再找出转化低的3大原因（章2）→ 最后提出针对性策略（章3）”\n像搭积木一样讲清章节关联，导师一看就觉得“你思路超清晰”！\n6️⃣ 研究方法：别瞎选！要“对症”\n根据课题匹配方法，比如：\n▪️做案例：选3家典型美妆店深度分析\n▪️做数据：爬取某平台3个月直播数据\n▪️做文献：梳理近5年相关研究\n选对方法，才能支撑研究落地～\n按这6步写，开题报告直接从“及格线”冲到“优秀档”！\n亲测改完后导师只回了3个字：“可推进”👏\n宝子们快码住，写完记得来报喜呀～\n#开题报告 #开题报告模版 #开题报告怎么写 #开题报告写作 #开题', '开题报告摆烂版通关指南📚。导师看了都夸会谁懂啊！写开题报告像挤牙膏，改到第8版还被导师打回？\n别慌！按导师亲授的「6步公式」写，逻辑+深度直接拉满，小白也能一次过～\n1️⃣ 研究背景：把“选它的理由”说透\n别干巴巴凑字数！核心是「时代趋势+现实痛点」组合拳\n比如写新媒体课题：“短视频流量见顶（趋势），中小商家却没找到精准获客法（痛点）”\n一句话让课题“非做不可”的必要性立住！\n2️⃣ 研究目的：拒绝“我想研究XX”的废话\n按「对象+方法+需求」公式写：\n❌错误：研究直播带货的影响\n✅正确：以XX地区美妆商家为对象（对象），用案例分析法（方法），解决直播转化低的问题（需求）\n目标感拉满，导师一眼看懂你要做啥！\n3️⃣ 选题意义：从“理论+实践”双押\n别只说“有意义”！要拆成两句干货：\n▪️理论：能补啥空白？比如“完善中小商家直播运营的理论框架”\n▪️实践：能帮谁解决啥？比如“给美妆商家提供可落地的转化策略”\n价值感直接拉到满分💯\n4️⃣ 国内外研究现状：别当“搬运工”！\n先分别梳理：国外研究到了哪步（比如欧美侧重用户行为）、国内有啥进展（比如侧重平台规则）\n关键是最后要「评+述」：\n“现有研究多聚焦头部品牌（评），但没覆盖中小商家的实操痛点（述）——这正是我要补的缺口！”\n一句话凸显你的创新点✨\n5️⃣ 研究内容：搭好“论文骨架”\n别写“第一章写XX”！要带逻辑：\n“先分析中小商家直播现状（章1）→ 再找出转化低的3大原因（章2）→ 最后提出针对性策略（章3）”\n像搭积木一样讲清章节关联，导师一看就觉得“你思路超清晰”！\n6️⃣ 研究方法：别瞎选！要“对症”\n根据课题匹配方法，比如：\n▪️做案例：选3家典型美妆店深度分析\n▪️做数据：爬取某平台3个月直播数据\n▪️做文献：梳理近5年相关研究\n选对方法，才能支撑研究落地～\n按这6步写，开题报告直接从“及格线”冲到“优秀档”！\n亲测改完后导师只回了3个字：“可推进”👏\n宝子们快码住，写完记得来报喜呀～\n#开题报告 #开题报告模版 #开题报告怎么写 #开题报告写作 #开题', 1764333352, '133', '36', '16', '106', 'https://www.douyin.com/video/7577754020950946954', 'https://p9-pc-sign.douyinpic.com/tos-cn-i-0813c001/oUjGzBASxP3PwlIaWAmkPAQ2iiTRpIAAsEApA~noop.jpeg?biz_tag=pcweb_cover&card_type=303&column_n=0&from=327834062&l=2025120110485183FC6BE3EF29E2CC33E7&lk3s=138a59ce&s=PackSourceEnum_SEARCH&se=false&x-expires=1765764000&x-signature=nnQ2jUwVZk%2BWWjYjbjLk1wUUcyw%3D', 'https://sf5-hl-cdn-tos.douyinstatic.com/obj/ies-music/7577090591364860718.mp3', 'https://sf3-cdn-tos.douyinstatic.com/obj/ies-music/7577090591364860718.mp3', 'https://p3-pc-sign.douyinpic.com/tos-cn-i-0813c001/oUjGzBASxP3PwlIaWAmkPAQ2iiTRpIAAsEApA~tplv-dy-aweme-images:q75.jpeg?lk3s=138a59ce&x-expires=1767146400&x-signature=h%2FKoanFgeIylRGbxYO3HOhdh79Q%3D&from=327834062&s=PackSourceEnum_SEARCH&se=false&sc=image&biz_tag=aweme_images&l=2025120110485183FC6BE3EF29E2CC33E7,https://p3-pc-sign.douyinpic.com/tos-cn-i-0813/oowkRasIPmQSiAsibABxWQIz2AjApAluPTAAE~tplv-dy-aweme-images:q75.jpeg?lk3s=138a59ce&x-expires=1767146400&x-signature=hm18fh9VtUZeWkyNOYvrqGup0Qg%3D&from=327834062&s=PackSourceEnum_SEARCH&se=false&sc=image&biz_tag=aweme_images&l=2025120110485183FC6BE3EF29E2CC33E7,https://p3-pc-sign.douyinpic.com/tos-cn-i-0813c001/ogEapSlAiPmimzBIAxTRQPAAWIAkAzZ2GsRAj~tplv-dy-aweme-images:q75.jpeg?lk3s=138a59ce&x-expires=1767146400&x-signature=nYRSdM3c25l7bTTcPb8lTsvklfc%3D&from=327834062&s=PackSourceEnum_SEARCH&se=false&sc=image&biz_tag=aweme_images&l=2025120110485183FC6BE3EF29E2CC33E7', '毕业论文');
