INSERT INTO `douyin_aweme_comment` VALUES (21, '2425983762700795', 'MS4wLjABAAAAOS-RT2ynQTOVOzO8QQYQCfqK6jdMAMIgOVnUzc7gH59n3PiJ7JqhrFOF7d_Mb9p6', '43550104644', '43550104644', '111', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '新疆', 1764555314145, 1764559259450, 7489790553480069914, 7466443948370758946, '1.阅读文献-大量-摘要+正文-逻辑和用词(20-50篇)\n摘抄，结构思路\n注意:文献年份-近五年，出产地，英文刊\n得到文章框架\n2.读别人的表达方式，缝缝合合合成自己的\n3.转换数据格式表现\n4.不要全胡编乱造比较离谱的\n确定结构和小标题后再写', 1743852757, '0', '0', '22', '');
