INSERT INTO `douyin_aweme_comment` VALUES (77, '355874213213884', 'MS4wLjABAAAAhzL6RQt0eK01On8-jgdS6GwqDAudPesuGpOdmtWartg', '3550443904', 'Ultra_0000000000', '巅峰玩家', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ocvFgYanicwwPIgAqWDcpdmAJiAAMBHiIEzAU.jpeg?from=2064092626', NULL, '山东', 1764555368558, 1764559386986, 7569547094962619172, 7569477544518216805, '豆包，可以，先让它给毕业论文按照大题目做提纲，然后把每一个提纲小标题自己按照字数大概分配好后单独让他写，要求严格按照科学论文格式，注明出处，文献真是存在并且能够按照注释找得到原文，然后写文一个标题后做成pdf，标注好第二个小标题后再次输入原先的严格指令，并且加上用第二个下标题承接上文续写的指令，以此反复，最后自己慢慢改瑕疵，想法降低查重率，比如说英文文献自己重新翻译一边之类，反正有半个多学期的时间，慢慢完善，记得多刷新几遍格式就行，不然复制粘贴的美容会护眼模式下一目了然的', 1762422525, '5', '0', '205', '');
