INSERT INTO `douyin_aweme_comment` VALUES (98, '1028786632273464', 'MS4wLjABAAAALdWWS9Kv_m2yFbD5hFj-G09ZaESpjzjwkJRvO6pEZHgTn0JgxWySvBNYjK-Rab2e', '3940501955', 'Cda60933', 'C陈大d', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oEP0e5ALEilDnwAAKroAQB2CUI2AD8AfgAyiB9.jpeg?from=2064092626', NULL, '山西', 1764555388461, 1764557610488, 7578092988884304674, 7577333829677927718, '开题找文献花了三天没头绪，paperxie 直接整合好相关资料，还给研究思路，一下就理清方向了。[比心][比心]', 1764412274, '0', '0', '0', '');
