INSERT INTO `douyin_aweme_comment` VALUES (169, '98478097542', 'MS4wLjABAAAAn9nkqGm8pxsFd6iptGC7abFzSYlMg1kxBtLY_jE5F4U', '939488146', 'Vicelive', '和我说句话', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_4b8d61b6fd164958ad431597b8e1e0f7.jpeg?from=2064092626', NULL, '广东', 1764555585152, 1764559279777, 7575487390031790897, 7574008323521120379, '水的学校毕业设计也是水的没边，有的老师简直就差帮你做了，我宿舍有一个做那种强电的，他们老师基本上每周都单独再给他们开一节课，带他们计算那些潮流，短路，还说实在不行他那里还有现成的[憨笑]@@cc @改一个有趣的🆔', 1763805607, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (170, '7568372296025982009', 'MS4wLjABAAAAUtIFJsOXyUm3DGMhsJaYApa1dl1zT4UT5uaWxFrDgYMUcb1Qe2HKk9PYRxl1c3ii', '97349207515', '97349207515', 'xiaoxing', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_dcbd15d6f7fcf12c206f5cc616c34f39.jpeg?from=2064092626', NULL, '河北', 1764555585161, 1764559279773, 7578436302661845819, 7574008323521120379, '谁需要帮忙', 1764492207, '1', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (171, '1410034931087584', 'MS4wLjABAAAAi83G9NhuwHQQC4UWqzpXhViabE0lHg8MU8J7kL8UFGAnDqOpnaCfQQesioJAB-0L', '24285762275', '24285762275', '曲昌迪', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_owJqDfCeCzyD5OAZzgAPAIOtEN33l5AhCxIAOA.jpeg?from=2064092626', NULL, '吉林', 1764555585167, 1764559279781, 7574207049245508411, 7574008323521120379, '大学以前本身就是给精英，学者搞学术准备的地方。你现在大部分大学都是为了找工作，而且学生的学问素养也就那么回事儿，这论文就属于旧时代的遗留了。', 1763507506, '1', '0', '76', '');
INSERT INTO `douyin_aweme_comment` VALUES (172, '83780380003', 'MS4wLjABAAAA9jkLKCIR996dxtm_mbe60vbxjJZp0xs81YIHqhQRWHg', '366288108', '', '研博辅导', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_820a503275597ebd6d56db015e236f8b.jpeg?from=2064092626', NULL, '河北', 1764555585172, 1764555585170, 7577925099584619323, 7574008323521120379, '那你知道现在的老师根本就不会给你提供太多的材料 我接了将近50份的计算机专业的 每个老师的奇葩要求都不一样 去年的今年根本就行不通了 别想着老师会给你提供资料 这都不可能 他们给的任务书都是ai 出来的 根本不会去考虑学生的水平', 1764373180, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (173, '95323135174', 'MS4wLjABAAAAH9EkaNBA--IbJ8FT_CDhqwxiIpeacyzmnua-s1iUcG8', '896436741', 'XZ._DCX.', '🦊', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_0b888ee5105f7c8c19ea53de99a6b6ce.jpeg?from=2064092626', NULL, '江苏', 1764555593408, 1764559078114, 7552802957017350969, 7488823047965723931, '以过来人的身份真心劝一句：千万别随便找代写，水太深了，被骗的人一抓一大把，一定要好好甄别！我其实比谁都清楚，自己写出来的东西最扎实，也最省心，但当时是真的卡到死胡同里了，对着空白文档坐了一天，一个字都写不出来，眼看时间越来越近，硬扛肯定要耽误事，实在没办法才出此下策。现在想想都后怕，好在这次运气不错，遇到个靠谱的，没糊弄事儿，答辩前不管有什么新要求，喊他修改都很及时，前前后后改了好几版，一直跟进到我答辩结束。最后总算过了，但这真的是没办法的办法，要是能自己写，真的别学我走这条路。', 1758523977, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (174, '109547426802', 'MS4wLjABAAAALZOzw53TU_uscUtEK53sU6fFFCNu2AJPQTZATtfkRA8', '1879674217', '', '以舟', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oQ3HESgofAIlepFaAD9mqICYtEACFAAoh9AQ6u.jpeg?from=2064092626', NULL, '陕西', 1764555593412, 1764559078127, 7490514484386235186, 7488823047965723931, '当时写论文我和同专业一个同学我俩是一个老师带，他引用了1983年苏霍姆林斯基的观点，老师说1970年苏霍姆林斯基就去世了[泪奔]他当时发给我我都要笑疯了', 1744021313, '106', '0', '10602', 'https://p11-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/0ac11cbde175473bb54a001382380369~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1764579600&x-signature=MrL9FiptnjQrn%2FkcmryJQKZKqr8%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=20251201111757D0D6049CE4BD71BD8537');
INSERT INTO `douyin_aweme_comment` VALUES (175, '63903168470', 'MS4wLjABAAAAUHbGqZ7wx_3qlZIm9i7HlZan1xfyOyO78IZS7_Emync', '364273822', 'miaomiaomiao.mua', '小花蕊呀_（强大版）', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1ddb7a597d5e9ffd44348dab3e099e5d.jpeg?from=2064092626', NULL, '内蒙古', 1764555593418, 1764559078142, 7490761906396955428, 7488823047965723931, '真服了 当年全系就我导全程不管我们论文 从初稿到终稿查重都是自己弄 每次刷到导师改论文类的视频 就想到自己那段无头苍蝇般撞的头破血流的日子 要不是因为当年线上答辩比较宽泛估计会答辩变大便 真是快哉快哉[憨笑]', 1744078923, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (176, '104236249030', 'MS4wLjABAAAAYAZns7RuuI6NpDVzpUIJ07LUXd0qMZVhKs14h4HWtks', '1543195753', '', '原谅小绿人儿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_c7f5000e691267cc1687.jpeg?from=2064092626', NULL, '江苏', 1764555593429, 1764559078145, 7490875596122882825, 7488823047965723931, '宝子们别觉得好玩了，作为大学老师，我们改学生的论文有时候比程序员改“屎山”代码都更无从下手。关键屎山还是死的，学生是活的，他们会到处跑，到处说是你教的，他们的爹妈还会质疑你[泪奔][泪奔][泪奔]', 1744105392, '43', '0', '4418', '');
INSERT INTO `douyin_aweme_comment` VALUES (177, '66736987864', 'MS4wLjABAAAACi13xQqo1niI1HnPsPqZOVkebPs_WZTRkKuAga4HXbA', '596596011', '42023211L', '沉戟', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_b0c6a65c7f95517d11be07c73184c410.jpeg?from=2064092626', NULL, '陕西', 1764555593438, 1764559078156, 7489466850184823578, 7488823047965723931, '本科论文导师当时怀孕了根本不敢做错事怕给老师气得不合适了，后面还是被骂得狗血淋头给老师气得把我微信都删了[鼓掌]我也没加回来就一直发邮件', 1743777398, '49', '0', '8886', '');
