INSERT INTO `douyin_aweme_comment` VALUES (299, '2656858939072839', 'MS4wLjABAAAA46PBDFTdgzRoM8LUO11UddBudaRKCQ45G-MVyZMOFn2K0VOh_kI6gXuR1oCV3gT1', '4173211467', 'wfp9203', '孔', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c5a0771b20f747586d8283533e77dbe5.jpeg?from=2064092626', NULL, '江苏', 1764555804776, 1764557759031, 7547654009777308474, 7546740508753546522, '1. 找好近几年的真实文献，直接传进文优小助就能出来了。 \n2. 读摘要总结摘要，又快又准。 \n3. 实在不行直接用引文的参考文献，每篇扣点拼在一起。\n4. 用excel整理 基本上30篇1小时，从完全不懂到可以放进文章里并成文，每天两三小时就可以了。\n5. 把内容写好，再去找相应的参考文献，再根据参考文献调整内容。\n6. 外文整理好，翻译过来直接参考着用。', 1757325144, '4', '0', '39', '');
