INSERT INTO `douyin_aweme_comment` VALUES (737, '65433258371', 'MS4wLjABAAAAmSETHET3vHFqXKNFosz9w4fe0oFumtlHoXRwuQGQp3M', '55722499', 'Chengx0000', '7.🌪️', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_bf4f5911d399bdddf59ed5a6b3578b50.jpeg?from=2064092626', NULL, '河南', 1764556544448, 1764556544442, 7560969267601867577, 7535885785243094326, '我都是从选题就开始找辅导的，我导师是真不管，还一直毙我选题，我真的没办法了，后面我直接摆烂找辅导，选题一次就过了，后面论文也是一直辅导推着我写，一直辅导我答辩结束，不然我包延毕[懵][懵][懵]', 1760425345, '8', '0', '7', '');
