INSERT INTO `douyin_aweme_comment` VALUES (939, '2559318500328819', 'MS4wLjABAAAAjC8xdl-EI8qHe4NWZKYv8irv6XQ1WJzQE-BIoQj6D5b8Q8xBM2ZvMMmWGnd8R2-y', '89844583812', '89844583812', '巧克力饼干', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_4b3648834a2c167012bc1b37ca95da47.jpeg?from=2064092626', NULL, '浙江', 1764556864215, 1764556884734, 7577685446190629669, 7535034131978243391, '用 paperxie 出的开题初稿，导师说研究方法可行，文献也选得好，比自己瞎琢磨少走了很多弯路。', 1764317384, '0', '0', '1', '');
