INSERT INTO `douyin_aweme_comment` VALUES (943, '14949995055', 'MS4wLjABAAAAmnHspbFh8YXh4F_7YJRKGNcGHH7kJ8i7P4g8LGSgyy8', '75499922', '_xiko', '金熙媛', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oQf6gPnAAQmAeBE7zCbC9yLJsWmuj4AIADAynI.jpeg?from=2064092626', NULL, '陕西', 1764556869316, 1764559202169, 7578501847515398966, 7572026991081742202, '百考通ai降重后的文字反而更好读了，有些冗长的句子被精简了，表达更简洁。', 1764507465, '0', '0', '0', '');
