INSERT INTO `douyin_aweme_comment` VALUES (947, '71882424196436', 'MS4wLjABAAAA9lUGXsBhIYoicHg5_cp6RJjNlvkEkV7WS4xxacRngnM', '46687664766', '46687664766', '点点hug1', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_94b6405cb1e5095ef0cd4e28d610abde.jpeg?from=2064092626', NULL, '江苏', 1764556869368, 1764559202256, 7576220822965207857, 7572026991081742202, '1. 找好真实文献，投喂进文优小助就能出来初稿。 \n2. 把英文文献进行翻译，有效降低查重率。避免使用双引号，因为这个内容会被重点检查。 \n3. 综述别人综述的摘要。\n4.先选题→deepseek给提纲→按提纲找文献→用豆包打包文献→找一篇范例综述，让deepseek把豆包的内容换个语言风格生成→再加点牛逼点的图片。', 1763976373, '0', '0', '1', '');
