INSERT INTO `douyin_aweme_comment` VALUES (1149, '2933930410642477', 'MS4wLjABAAAAl-RjKbtBWIIGdj0fvvJUi6IsHf4pvegBW2I3EIACnqgGsMPfs46Ktg4kTUlssbFz', '25414410905', '25414410905', '断裂的指骨', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oQBQDAfIgtAeVXAAg27Y4rE9BjEAPZkcsTf4Jf.jpeg?from=2064092626', NULL, '湖南', 1764557182670, 1764559207229, 7546132021610267451, 7546079239553994043, '那个我想问一下主播我是一个大专生，下半年准备实习了，我看到国家大学生就业服务平台上有一些比较适合我的实习，但是专业不合适，我的专业比较冷门是船舶工程技术，请问我可以去投那种实习要求专业和自身专业相悖的工作吗[流泪]', 1756970778, '1', '0', '4', '');
