INSERT INTO `douyin_aweme_comment` VALUES (1542, '198367921060190', 'MS4wLjABAAAAzK_3oLlgym17rDNFYQLWc2a48xhWPbtNA1zlI2scSUU', '34503293646', '34503293646', '用户1000042501666', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '天津', 1764558543545, 1764558579727, 7556158067139740435, 7147656680120143118, '个人认为，deepseek写论文太过于笼统，不精细，而.且格式，方向，都太过于偏差，也不能完整完成一篇，术业有专攻，还是得找到一些专门写论文的ai工具，checkjie在这方面做得就还可以，deep seek太过于笼统了[笑哭]', 1759305974, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (1543, '4396272354338971', 'MS4wLjABAAAA--GLbeA5GnBgEGBUzrx7nB-r5MXdHr993SrCaYG-g50paPMCL18nTSGAyOvMJcGb', '63638513996', '63638513996', '风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_owxyZZDIPc74iAoiOAB24QIP5AjAHCOyPKApE.jpeg?from=2064092626', NULL, '江苏', 1764558543557, 1764558579732, 7542788140203066112, 7147656680120143118, '个人认.为，deepseek写论文太过于笼统，不精细，而且格式，方向，都太过于偏差，也不能完整完成一篇，术业有专攻，还是得找到一些专门写论文的ai工具，checkjie在这方面做得就还可以，deep seek太过于笼统了[给力]', 1756192701, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (1544, '2777823499271497', 'MS4wLjABAAAAOL1TSfO2ByHK_OMgIUugXMS0200W31J4PhYcO8df-xFJB6NMlZi_YtGSanhw2mSI', '27064713674', '27064713674', '小颜emo', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ogAxPRBGBIDonq0eAxiACWegJCPmzAAEi3gpA9.jpeg?from=2064092626', NULL, '江苏', 1764558543572, 1764558579736, 7549423479872324392, 7147656680120143118, 'deeps确实语言写的很优美，但是ai率真的太高了，最近写初稿的时候ds 和 万象写作都用,提示词不专业的建议还是别用ds了，万象写作生成的快而且质量高，这个网站的功查重和隆重.的都有了，一定啥啥都搞定了[V5]', 1757737720, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (1545, '1876195788995300', 'MS4wLjABAAAAlVfzCxAomfv9RLApqnYW8ibciVJwv1U0swsXxKnVwvwfWSsQJDXZV0pZ-XU3Ta3B', '70404388180', '70404388180', '温柔学姐', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oQ2QGLGe7BByBQA9RHIIKLEAYA0AveALxQeiyD.jpeg?from=2064092626', NULL, '江苏', 1764558543583, 1764558579739, 7563554766950859563, 7147656680120143118, '主要就是框架思路。参考别人的框架，用万象写作生成自己的框架（画重点），然后代入自己的具体情.境和数据。最好细化到三级标题，每一个三级标题写什么，ai可以自己编辑提纲，生成提纲后一建成文～后面就是用语言，把内容填充起来，重复率不用管，很低的，ai现在很牛[憨笑]', 1761028147, '0', '0', '0', '');
