INSERT INTO `douyin_aweme_comment` VALUES (1707, '101303044005', 'MS4wLjABAAAAifhqYRDwxUwhKnVmaAe0Tc_FheBMA7wk9oERusbdJE4', '3602844890', 'weixiao4734780', '宝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oMAAxREIEEwpUdYf7YFojlBLutLvKAAyDC29Ae.jpeg?from=2064092626', NULL, '河北', 1764559151862, 1769050587587, 7577324214187131698, 7549516224137334074, '应该是aibiye，然后我去的他们官方 ，结构，知网文献，甚至标引都没问题，但如果你对自己有要求，其实.还需要自己加创新（如果你有追求的话），加数据（真实的），加图表（ai以你的思考生成漂亮的彩色图表）。反正这样弄了交了，难题给导师，我先休息一下[舔屏][舔屏][舔屏][捂脸]', 1764233276, '10', '0', '52', '');
INSERT INTO `douyin_aweme_comment` VALUES (1708, '2711872210998440', 'MS4wLjABAAAAVtICoy3OKFizba8jZ56fp516IMf-il7WoY8UA3Vi2xwqcs5g14hfIBFaOmqmRbXr', '88299232349', 'TwToii3', '合 欢', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_8d9f214482fd38c61ec34a7b8eeae536.jpeg?from=2064092626', NULL, '澳大利亚', 1764559151867, 1769050587478, 7549545717690843954, 7549516224137334074, '还有7天才交，等我5天后再来看，先收藏了[赞]', 1757765590, '119', '0', '7037', '');
INSERT INTO `douyin_aweme_comment` VALUES (1709, '102742456754', 'MS4wLjABAAAAiGNKcu1gZiue6Flv0RNoJZEOjuOsc7cVY6Bm_py5djU', '1447180300', 'T11an28', 'T！AN', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1a9bdf9c19424ee3db6d2485ba271d9e.jpeg?from=2064092626', NULL, '澳大利亚', 1764559151871, 1764559151869, 7550221803067753274, 7549516224137334074, '说点现实体验，以前是一年的pro用户但是现在完全不用gpt生成正文了，都是申博期间被编辑反稿多次血与泪的教训。 首先一个最大的问题就是引用文献方面，大多数文献gpt是没有直接访问的权限的，它只能通过引言部分的一个大致介绍与你的研究方向做匹配。同时它会给你提供一些不那么具有代表性的期刊作为文献来源（水刊）。这导致的最大问题就是，你向gpt提出一个想法，它给你匹配文章时抓取文章里的一些关键词去支撑你的观点，但实际上文章里可能只是提到一嘴，并没有往你所想要表述的方向做延伸，以致于最后你的观点是站不住脚的。另外其实就算是5pro，ai写作还是有它固定的范式，经常使用ai输出文字的很容易就能看出来', 1757923004, '4', '0', '304', '');
