INSERT INTO `douyin_aweme_comment` VALUES (2115, '62067180230', 'MS4wLjABAAAAuy4EegmcNnBXINwnpydE0aExENII5audrrI5UnkK0u0', '291116271', '', '&', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_bbdbd1fd53b169362cd865ec742e93fe.jpeg?from=2064092626', NULL, '广东', 1769048870295, 1769050723029, 7319562819321250599, 7309060013887081728, '谁说专硕能学到工作的技能？一堆学校专硕按学硕培养，毕业要求sci论文，根本没时间自学工作技能。高校的培养计划本科不行，硕士也不行[尬笑]', 1704218543, '2', '0', '16', '');
