INSERT INTO `douyin_aweme_comment` VALUES (2118, '82193076258', 'MS4wLjABAAAA3djXqCxLNXjOrrBFKFjhpWzD5VMqDVEHFJa5uxXLfJ4', '169454083', '', '丼', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_b57bd7940910b95af4bc69b0c7b98c6b.jpeg?from=2064092626', NULL, '江苏', 1769048875401, 1769050707609, 7531939277174833972, 7357734366744808744, '我强烈怀疑就是你们这样的博主太多了，导致现在新进组的师弟师妹让人非常讨厌，一点都不踏实，满脸都写着自己的小聪明', 1753666278, '2', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (2119, '110557793560', 'MS4wLjABAAAAtLbpXstBwyxOjnjtnqNU60uI2fUyAx3xi0Wuq9Yggv0', '2219437417', '', '无名氏', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMAAXimi9F2sB3OA9fsCeXA2gNiVAAAIxnG1Em.jpeg?from=2064092626', NULL, '湖南', 1769048875412, 1769050707627, 7357877169693295370, 7357734366744808744, '其实说的这些道理大家都懂，但是缺少具体指导的方法论[呲牙]比如说一个只想混毕业基本条件的，被老师抓着科研，你怎么躲？亦或者想读博的同学，被外派实习或者做横向课题，又应该怎么躲？', 1713139283, '16', '0', '833', '');
INSERT INTO `douyin_aweme_comment` VALUES (2120, '69445608743', 'MS4wLjABAAAAzgOARvw7S8sSM39M1RG6DJCkSo33L-mhkIN8iaXnlu4', '785492708', '346477T9266T66', '记得填写名字', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ocfznSeBAKBq6XziPGiyBEAQAdAIIgC84BADzA.jpeg?from=2064092626', NULL, '黑龙江', 1769048875423, 1769050707641, 7357752244420838155, 7357734366744808744, 'In conclusion：合理范围内 有道德有原则的精致利己就行了', 1713110197, '1', '0', '42', '');
INSERT INTO `douyin_aweme_comment` VALUES (2121, '23884121269', 'MS4wLjABAAAAh4co09KVEw-RO5lLeLW5Kv4sDS_Ap7iAV_bwHCOfmVc', '102296002', '', '柒安丶', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oMG2wIBQGYdefgfQAIe8ABAAhLfxAeIPvGSZc2.jpeg?from=2064092626', NULL, '北京', 1769048875437, 1769050707654, 7381884477386048310, 7357734366744808744, '怎么说呢，本科毕业，在郑州月薪4000，读了研究生在郑州年薪30[黑脸]', 1718728928, '1', '0', '19', '');
INSERT INTO `douyin_aweme_comment` VALUES (2122, '82823477501', 'MS4wLjABAAAAJ0ik5ujF1BzOMC2h2dg3gvSl7uus1mD3X5AarL8fWT8', '188102633', '', 'Rob Shi', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_f2de256b6bff9616b156c6a6f2f9e042.jpeg?from=2064092626', NULL, '北京', 1769048875452, 1769050707669, 7357945156396761867, 7357734366744808744, '理工科一般都去不了实习的，别因为去不了跟导师闹，吃亏的是自己，大部分都不去了，企业也清楚这些，反正我师兄师姐一点实习没有也去了华为，去大国企的也有，主要看个人', 1713155112, '24', '0', '642', '');
INSERT INTO `douyin_aweme_comment` VALUES (2123, '72205254344', 'MS4wLjABAAAA8ZafbzFQ3eE1Qi5Koj_rWf6REwsD_aL03Byk-yULxaI', '1093874633', '', '五碗桃', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o8IgvdSIw6ViBvixPryr2AZUiAuyoiA6BELAA.jpeg?from=2064092626', NULL, '北京', 1769048875466, 1769050707679, 7358294471764722468, 7357734366744808744, '毕业要求和就业要求其实相差很大，我觉得有时间多去实习，去大企业小企业都实习一下，提高认知才是最重要的，因为你挣不到你认知以外的钱，只局限在学校的眼界甚至工作以后只局限在一个公司里面的眼界，其实都是不够的，当你恍然大悟原来钱是这么挣来的时候，你真的会觉得以往的很多努力与坚持的方向都是错的，甚至占用了你大部分精力却让你离看透社会规则越来越远……', 1713236442, '2', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (2124, '99993328041', 'MS4wLjABAAAA0bu5oDXWMj6grViclipXiFxUS5ueqK_D5ChWahkAOxM', '1039447552', '', '福猪猪的胡萝卜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oUI9WCmAYL7E8Pt9nAEyiPeACAACugbbDhAAfY.jpeg?from=2064092626', NULL, '湖南', 1769048875480, 1769050707702, 7357888732068348726, 7357734366744808744, '我论文都发了，我也想去实习[流泪][流泪]但是我导师不会同意的[尬笑][尬笑]他还计划让我发3篇🆘可是我根本就不打算读博', 1713141976, '18', '0', '263', '');
INSERT INTO `douyin_aweme_comment` VALUES (2125, '2991100814966621', 'MS4wLjABAAAAQjVOeEvS31G6CEbGl188U0YbLceQiUBZ-s6ulgMlArg3BgEFor1O-8WaxgnOkDlk', '4148115135', 'adu47053', '奶油泡泡', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oALAi6HCge4eAEni0AIAi6inAiAUDkvnC9AaBA.jpeg?from=2064092626', NULL, '广东', 1769048875491, 1769050707693, 7575015191378936613, 7357734366744808744, '研究方法那一章最头疼，百考通ai给出了定性和定量的分析方法，还有具体步骤。', 1763695666, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (2126, '23781862388', 'MS4wLjABAAAAPF0u-Wh4wLG2B8RxOPiG-UcT_bSmkZstm3rSJ_wcWYQ', '375577109', '', '柚子菠萝冰', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_okIA2mZAsC3Alg9J7IQAFFEAjeD97uAO4fYDMC.jpeg?from=2064092626', NULL, '河南', 1769048880525, 1769050728012, 7303404358358631205, 7303155894265711913, '天啊，我和你的状态一模一样，真的不适合读研，就连导师都一样，push＋让自己选方向，我本来就对这个专业知识的了解就很片面，所以就导致现在我也很迷茫，也有想过到底退不退学[流泪]', 1700456341, '114', '0', '4527', '');
INSERT INTO `douyin_aweme_comment` VALUES (2127, '4284133020533127', 'MS4wLjABAAAA9mUTrNl2LBSzrfKrk-hUYHXZy1SGz4sBvRrWcpWSgTFe3W3ZlgKEYPIUSpq6kWxG', '50838636692', '50838636692', '啾咪~', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/douyin-user-image-file_c9465ed21c35ce0eab10b4b17778c63e.jpeg?from=2064092626', NULL, '山东', 1769048880538, 1769050728025, 7303417551505326886, 7303155894265711913, '确实，人的认知总是有局限性的，我们没有上帝视角，看不到每条路后面可能会发生的事情，但选择了那条路就一定会有选择的意义，不要去埋怨当初的自己为什么，因为当时的她也很无助[泣不成声]', 1700459415, '3', '0', '438', '');
INSERT INTO `douyin_aweme_comment` VALUES (2128, '2150297114510291', 'MS4wLjABAAAAcvD2YK0mVf7LddI-kJMKJPDZkxPKknQOS9cqI1MHqAvD1-34ObWdz1uIQGB_SV8z', '2369737086', 'ganfanxiaore79', '吃饭不洗碗', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o0CEAA98iiAKv3AgIeIBNtaoVgsAiyz6oAhfCV.jpeg?from=2064092626', NULL, '海南', 1769048880551, 1769050728033, 7303404154390971172, 7303155894265711913, '想明白就行，整理好思绪再出发。我本来打算考研的，后来想明白了，不考研不考公死不了，与其拼死拼活考上研，不如想清楚自己要什么，如果为了考研而考研，那这个书读的没有意义，所以转换了思路，毕业先出去看两年 发现真的需要充实自己的时候再去考研，那个时候的人生阅历足够，对自己的未来会有更好的看法和规划', 1700456296, '66', '0', '2393', '');
INSERT INTO `douyin_aweme_comment` VALUES (2129, '68583205497', 'MS4wLjABAAAA4VX_Uyf54ZrPLMY75ysUl7rZ34HTrYHkwzjkDnkWVq4', '1171924227', '', '上课的饿不饿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_a66100167aecede9143d.jpeg?from=2064092626', NULL, '山西', 1769048880564, 1769050728041, 7303412621561774900, 7303155894265711913, '首先，只有读过研究生，才知道自己适不适合搞研究。\n其次，研究生在科研研究过程中暴露的问题，不仅仅是是科研中的问题，更多的是自己思维中的问题。如果把这些自己习以为常，无法自知而又根深蒂固的问题带到以后的工作中，将会免不了走弯路。\n好好珍惜自己的研究生生活，感谢那些为你指出问题的导师。', 1700458268, '9', '0', '1540', '');
INSERT INTO `douyin_aweme_comment` VALUES (2130, '3747569407362599', 'MS4wLjABAAAADZe-bxVyIaRI1xUsuTHQQc5pruPckOOusBNIn72gmhZ-3Zr4WzcC1c0UVTd7oKaW', '4159654017', 'yigeyukuai13', '一个鱼块', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o8dykAz2EAChAANoNAAgIRAfm7n6WlJgH7SeNc.jpeg?from=2064092626', NULL, '四川', 1769048880574, 1769050728049, 7303420155513291559, 7303155894265711913, '咋说呢，我觉得我最大的幸运就是我选择决定去学习的都是我热爱的，并在后续的学习中确定了我热爱它，但是很直接的结果是在备考的过程中，专业课的学习让我坚信这个研究生我不考上谁也上不去，但是公共课的学习让我坚信这个研我下辈子也考不上。我的专业课老师不止一次的感叹，对于我们这群人来说面试读研比考试读研合适的多，从他的专业水平来看很多研究生毕业的小孩当下的能力完全比不上在备考的我们，但是他们适合考试，而我们只喜欢我们的专业[流泪]', 1700460022, '2', '0', '93', '');
INSERT INTO `douyin_aweme_comment` VALUES (2131, '71308128289', 'MS4wLjABAAAA1vPdqehItEJRInXpOl73jG-V53ZpWQSKy4QAJNBJ8Pc', '87699349', '', '快乐魔法师', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o8ixSIoIZiWWKBjlAApAQAnTPUsKivAEBA0iI.jpeg?from=2064092626', NULL, '山西', 1769048880587, 1769050728056, 7303448678554043190, 7303155894265711913, '人生，必然会遇到许多自己不想经历但却必须经历的事情，只看眼前就太短浅，要是这么多人读不下去的话，研究生早就没有了意义，人生与机遇都是自己把握的，考研应该是普通人最简单最有可能提高能力上限的事情了，上限越高机遇越大，不光是工作上的事', 1700466661, '1', '0', '33', '');
INSERT INTO `douyin_aweme_comment` VALUES (2132, '813256526009928', 'MS4wLjABAAAAatcsR1o1W5hEhwsehhPQxBgkZxUZ44iZ1Kj8FXL0-zg', '2144466736', 'qingmeng7538', '清梦🔴🔵', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oQ2B2DWkfEMZReAAX6Ag8eQ2RJIj7sQJ8AurWE.jpeg?from=2064092626', NULL, '陕西', 1769048880605, 1769050728064, 7303402809817891594, 7303155894265711913, '加油吧姐妹，我今年研三啦，还有一大半实验没做，每天都很焦虑，之所以会这样是因为我们实验室在研一研二都在干杂活，帮老师做实验，整理材料，写文章，订试剂耗材，报账…… 我也不知道读研的意义是什么，但还好有一群很好的同门师妹，能坚持就坚持下去吧，你看，不喜欢的事情你都能做好，以后做自己喜欢的事肯定会做得更好呀[抱抱你]', 1700455981, '13', '0', '158', '');
INSERT INTO `douyin_aweme_comment` VALUES (2133, '94875561490', 'MS4wLjABAAAAwlS0vOZYWL7AM8PI0wXGmr8GbCicpV22TKD9v0idfvA', '580229524', 'baekmoon211', '🍇', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_osJJPeGbLAWNP4erA7CgAENB7xXQg8AegPuIJI.jpeg?from=2064092626', NULL, '辽宁', 1769048880616, 1769050728073, 7303404448310002472, 7303155894265711913, '读研也好，工作也好，都有很多事与愿违的地方，无法改变现况，就改变自己，提升自己离开自己不喜欢的地方，姐妹你有能力考研，证明你的学习能力是没问题的，唯一迷茫的是研究方向，我读研的时候也是，但是总会找到的，我觉得读研难的不是科研，是意志力，当你跨过这个坎，以后的工作里遇到类似的，就再也不会打到自己，那个时候你会为自己骄傲', 1700456363, '4', '0', '157', '');
INSERT INTO `douyin_aweme_comment` VALUES (2134, '65901942296', 'MS4wLjABAAAAl79-pLgabHKrJrlivTx8o18VS0auWZXjKjN7cyaADYA', '57890584', '', '歌歌歌歌大宝贝', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_8d026c7a67dc4be7b2ea5ae48afa5dd8.jpeg?from=2064092626', NULL, '河南', 1769048880631, 1769050728082, 7303419781410816819, 7303155894265711913, '姐姐，感觉你说的很对，深深感受到自己并不是一个勇敢的人的时候不管再听多少鼓励都很无力', 1700459934, '1', '0', '152', '');
INSERT INTO `douyin_aweme_comment` VALUES (2135, '17054981639', 'MS4wLjABAAAAEF6AtTIyv5RR6_tGeYUCX3cuDllhdAyE_AezJ6kkGkw', '76747061', '', '🌈iukoi77', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_5b7ed72d94fb74d4b3738b89662fb607.jpeg?from=2064092626', NULL, '河南', 1769048880652, 1769050728090, 7303418111813370659, 7303155894265711913, '你说的每一句话我都很有共鸣 既来之则安之吧 过好当下', 1700459545, '1', '0', '345', '');
INSERT INTO `douyin_aweme_comment` VALUES (2136, '18008024812158', 'MS4wLjABAAAAKn6PaA_plKnyn6f2OsT67mmzKZNuJzvpexdACR1iwCI', '4031400782', 'xilong46856', 'xilong', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_0a831524b6544a0ea1c0891630af4390.jpeg?from=2064092626', NULL, '马来西亚', 1769048885656, 1769050792520, 7597888546905342770, 7590773997856378122, '我在马来西亚读研，课题是和工程物理有关的，本科是读生物的，可以说是不同的领域。我导师也是生物的，这方面完全不懂，所以给不了建议也没法评价我做的东西。因为领域转型，我花了近一年半从基础知识开始自学起，通过AI和读文章。然后昨天刚结束proposal defend, 被审核人批评我是本科水平，要求我重新做过presentation，给我搞自闭了[微笑]', 1769021291, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (2137, '1156339636899147', 'MS4wLjABAAAArChbuRmhi4SOyM-88qzo3e2LWY6kb35QBtbbYn8yep1QyP-WeJQTbhlL0FF4Sf0s', '3008082559', 'Tchayn', 'Tchayn Chan', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_7c078061ee7033f28ff96608e27f2ea7.jpeg?from=2064092626', NULL, '山东', 1769048885678, 1769050792540, 7590964270160413449, 7590773997856378122, '啥也不教，只给一个大方向，上课的内容也跟方向没半毛钱关系，平时也基本见不到人，全靠自学和ai', 1767409099, '111', '0', '4612', '');
