INSERT INTO `douyin_aweme_comment` VALUES (2143, '2199490437320231', 'MS4wLjABAAAAv1rGvy_82Lk8a6Fc6lrdG64GHsc6_1OyD_qAXYXimsenNRLY4Dxgr3gpug10XL33', '93200668433', '93200668433', 'tutu', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_195ecd63e871257275e3beaa389225f7.jpeg?from=2064092626', NULL, '广东', 1769048885770, 1769050792619, 7591122409278653210, 7590773997856378122, '太真实了，真的只有在坑里的人才会明白这种感受，主包说到我心坎上了，刚开始带着饱满热情来读研，现在觉得能毕业就行。', 1767445919, '7', '0', '86', '');
INSERT INTO `douyin_aweme_comment` VALUES (2144, '95194996767', 'MS4wLjABAAAApbrCF8tG3ZGj9XQHrIgwsEMwjtxdpiS8sVqXUci2N3M', '1037162272', 'w1037162272', '伤痕幽夜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oUAuefh6GQGvG9VXAFLAQTsxaQeO2AEIICAfHe.jpeg?from=2064092626', NULL, '广西', 1769048885783, 1769050792633, 7591813296794403621, 7590773997856378122, '研二了，已经中了一篇文章，还有一篇正在投，压根没有学到真才实学，就学会了怎么写四区水刊文章[杀马特][杀马特][杀马特]', 1767606778, '3', '0', '48', '');
