INSERT INTO `douyin_aweme_comment` VALUES (2203, '99464534378', 'MS4wLjABAAAAguEMODTQIVFgUlgBmP7WbmCCjkER6FuNu8wGym7aC8c', '2354227387', 'qing5598542', '天空岛屿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_owvrKAAxoDEPy0NHCzFEwyDhAxA9qFAIEef7n6.jpeg?from=2064092626', NULL, '江西', 1769048916324, 1769050834191, 7594349736997208891, 7588497363108522682, '我不知道，主要是读研真的太贵太贵太贵了[躺平]，我还是学软工的啊，真的好贵[躺平]，我家也就普通家庭[躺平]', 1768197340, '2', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (2204, '3478464262316547', 'MS4wLjABAAAAJrIajP3dVyn3O03C9C8NmAuoLufWoc2UaOKhacA_HlxJ8w0dC8NiT11njYkNReYs', '2372808668', 'lhy2027kysa', '雪見', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_9b552e445a71c9b9f52ac61a15e4ab2b.jpeg?from=2064092626', NULL, '云南', 1769048916340, 1769050834170, 7591924385637925669, 7588497363108522682, '1.本科阶段的期末考试就搞的我焦头烂额，就算认真学也学不明白，研究生的课程比本科课程难了很多，而且还是70分及格\n2.备战高考就已经耗费了我一大半的精力，再花个一两年时间每天起早贪黑去备战考研我真的吃不消了。\n3.读研期间不光课程多，还要开那该死的组会，写一堆论文，我承认我真的不是搞学术的料\n4.读研选导是门玄学，选到抽象的导师不仅读研读得很累还不一定有什么收获\n5.研究生毕业照样得找工作，而且就业前景不一定比本科好，性价比没有本科毕业就直接工作高', 1767632647, '8', '0', '333', '');
