INSERT INTO `douyin_aweme_comment` VALUES (2887, '96310841917', 'MS4wLjABAAAAJNIxxCA7_nWiA4fghMDZc0Jnn1fZjzWSeDhmwHBdWeE', '664370948', 'shufulei12138', '枼', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogZPaaBAAEQInIiVVhPipNABU4DAAA9HBAMCc.jpeg?from=2064092626', NULL, '江苏', 1769050120704, 1769050137435, 7439759482441384719, 7439645541958552844, '我教你怎么买电瓶车，你就混进大学生的二手群，那种大学生的二手电动车，他们毕业肯定急出就会比店里便宜，品相也不会烂[看][右边]', 1732203995, '230', '0', '19626', '');
INSERT INTO `douyin_aweme_comment` VALUES (2888, '82356352526', 'MS4wLjABAAAAPyWw01d0bZWMcUc-vxCBW7a7ZXWvRlo2JjpEqC-yVm0', '932558828', '', '桃子姑娘', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_beeef7ac09e941989f08f41299698487.jpeg?from=2064092626', NULL, '江苏', 1769050120715, 1769050137449, 7439957035833918217, 7439645541958552844, '小朋友们不要急，刚开始不管干什么都是工资不高的，找个行业干喜欢就一直干一个行业工资慢慢的就会涨起来的。不一定要在一家企业干到死，但最好是一个行业里干的顺心就不要换行业，可以换公司不能换行业，混个10来年到35岁左右的时候你在这个行业里的优势就会慢慢的提现出来了。', 1732249990, '85', '0', '2581', '');
INSERT INTO `douyin_aweme_comment` VALUES (2889, '67480019392', 'MS4wLjABAAAAJkWRxR1dAZQ95vZijhaNIJNBeI4YqhlSxyLTx2zpc6U', '65659186', '', '踏浪', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_2eb180000e091468eede8.jpeg?from=2064092626', NULL, '广东', 1769050120729, 1769050137469, 7439932268598903611, 7439645541958552844, '人们都在听他的故事，而我在欣赏他那不打草稿的演讲表演，能看出来他是个人材，至少在不久的将来', 1732244226, '161', '0', '20921', '');
INSERT INTO `douyin_aweme_comment` VALUES (2890, '1450948116359646', 'MS4wLjABAAAA7vvy4e_n1aImGVxwdgoP6Ti0lXC7FCP9Pa4Rhh52649Wga9B_yTdBDeuD27PN6aw', '3835001392', 'feng2161359', '锋', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '辽宁', 1769050120739, 1769050137477, 7440039506956501799, 7439645541958552844, '你大学时存的是父母的钱，\n你工作后存的自己挣的钱。\n这就是区别', 1732269191, '62', '0', '5259', '');
INSERT INTO `douyin_aweme_comment` VALUES (2891, '101389609382', 'MS4wLjABAAAAMHt9cpfnAunV7RuMVUFqZSrpH-rdOpdgShiElDP-yzM', '1130245475', '', '安吉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_4a4e9368ea474e9d88275876c702edfb.jpeg?from=2064092626', NULL, '吉林', 1769050120749, 1769050137487, 7439763321707217723, 7439645541958552844, '哪些还买车买房存彩礼，现在没有家里人扶持很难。这才是年轻人大部分现状，那种一出来就很好的大部分都是家里人扶持的', 1732204896, '4', '0', '231', '');
INSERT INTO `douyin_aweme_comment` VALUES (2892, '96625201436', 'MS4wLjABAAAA__9VKuv7v2fKhBZxrxJcR-C6ZJ6Ws0ZjBprbKMTDhwc', '719332617', '', '小羊咩咩', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ad2a0831f9eb49919c67eca09c4108d3.jpeg?from=2064092626', NULL, '浙江', 1769050120758, 1769050137502, 7439917184987611964, 7439645541958552844, '比她小的让，在看笑话。和她同龄的人，在笑无奈。比她年长的人，礼貌微笑，笑自己的过往。', 1732240713, '78', '0', '5903', '');
INSERT INTO `douyin_aweme_comment` VALUES (2893, '95123174440', 'MS4wLjABAAAA8fCB-6nDFT0XKEVtTKh-N-2A472sbDsrPv1792vHyQk', '587783783', '2015711125x.', '🌈✨小猫态·', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_a3b9e4130c11e71883eb10f03536da54.jpeg?from=2064092626', NULL, '湖南', 1769050120767, 1769050137512, 7440020384176833320, 7439645541958552844, '有人从初中开始就存零花钱嘛，暑假工的工资交学费，就因为不被爱，没有安全感[流泪]身上有钱才安心，工作4年买了一套26万的房子全款，第五年买了一台13万的车，今年是第六年身上只有十万存款，这期间家里所有开销大头都是我[九转大肠]我觉得我很厉害了，虽然不比大多数人多的好，但是也不算太差[流泪]', 1732264740, '113', '0', '1344', '');
INSERT INTO `douyin_aweme_comment` VALUES (2894, '2115935480327812', 'MS4wLjABAAAA8w1N7pKzKOjp9VcdppFvH55Z3yZnZGC2mi1M_DBZjPguqUnpifWMUhqYFzzEsrdu', '80407687560', '80407687560', '念桥边红药、', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '河南', 1769050120777, 1769050137521, 7439993464341496613, 7439645541958552844, '多少人看了视频，笑着笑着就哭了，哭着哭着又笑了，从学生到社会，从年轻人到中年老年，其中多少的心酸，只有自己知道[流泪]', 1732258473, '3', '0', '274', '');
INSERT INTO `douyin_aweme_comment` VALUES (2895, '100393000879', 'MS4wLjABAAAAvChrvtEw268dgd_7nJkgTGyghIXGVzgLVC_IsPhFAsA', '2360377637', 'dongpoxian123', '放屁带出黄', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oUbAAgBGEigWDBAbkjTi6AqIPAa0IAPBPZCFz.jpeg?from=2064092626', NULL, '广东', 1769050120787, 1769050137531, 7439869600458736434, 7439645541958552844, '5-6年，靠自己的话，多数大学生要熬这么久才能有点钱。而且要，很不舍得花', 1732229638, '6', '0', '511', '');
INSERT INTO `douyin_aweme_comment` VALUES (2896, '3421270073672759', 'MS4wLjABAAAAXFCSbCYwU9cbqFLxmBtQXimjbKJGTVexs1zQcowJEn-W4BXjKyGdG2c4suMzALTR', '3127937756', 'dych6u67t6i4', '知否知否知否', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oU4QHANnlC6HG31eDAAveAIiAAzdb7mgB9QBHM.jpeg?from=2064092626', NULL, '浙江', 1769050120795, 1769050137540, 7439869528852775714, 7439645541958552844, '有些东西省不下来。吃饭要吃。房子要租，水电费，人情来往，几千块一下子就没了[看]除非真的很能省[看]当然这是普通人', 1732229621, '7', '0', '336', '');
