INSERT INTO `douyin_aweme_comment` VALUES (2898, '3394921469057159', 'MS4wLjABAAAAzm7J0RgMP0V9IOHzGMIzb4D_XCgOuNpqtesTJOQ5Erw6wkxGTquQxxkN2QIVnatT', '3925015017', 'YONG6996', '陌路人', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_8a584cf7f73648b78977f4999b4e436c.jpeg?from=2064092626', NULL, '四川', 1769050120820, 1769050137567, 7439915957957477177, 7439645541958552844, '没工作之前你以为爹妈的钱挣得很容易，少喝一杯10块钱的奶茶，都觉得对不起自己短暂的岁月。', 1732240429, '5', '0', '168', '');
INSERT INTO `douyin_aweme_comment` VALUES (2899, '91614168549', 'MS4wLjABAAAAyWWTm1Wat2rdQsgU4BmyOFQpvnmxPTaNbHrCAZKqrW0', '840323929', '', 'L.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oEGRLBIUrAnwAgAhEFDBE8f5baeu7eQD0ALZbA.jpeg?from=2064092626', NULL, '北京', 1769050120836, 1769050137577, 7439916885855175481, 7439645541958552844, '《比大学时候存钱还少》因为大学不用上班拿的是父母的钱，毕业了是自己的实力赚钱', 1732240647, '13', '0', '740', '');
INSERT INTO `douyin_aweme_comment` VALUES (2900, '95990593580', 'MS4wLjABAAAAoNGTf4utr-naSKaXGDbx4dv-eNyJSUM3wYoXhgLji6E', '623111499', '', '饭醉份子', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_bd495612e578729a2ad03596d3e93aed.jpeg?from=2064092626', NULL, '广东', 1769050120846, 1769050137587, 7439917764863591187, 7439645541958552844, '2015年的确2000多，18年后就5000多了，如果还是3000多要多多想想自己这个单位行不行', 1732240849, '59', '0', '651', '');
INSERT INTO `douyin_aweme_comment` VALUES (2901, '1684890230729262', 'MS4wLjABAAAA1bcWZI9HNWw3gQxcbE-X49w1LfNdMxM3MLQi_lrnI2IInlJwqvvuOp2HmDW-FoGZ', '90614931193', '90614931193', '真的睡不着', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_3ba1f243e0405a9e409e23090baab1f5.jpeg?from=2064092626', NULL, '安徽', 1769050120854, 1769050137604, 7439947963973305129, 7439645541958552844, '当你某一天笑着说出来曾经难以启齿且不愿提起的伤心往事的时候！你就已经成长为一个强大且成熟得人了！', 1732247878, '0', '0', '136', '');
INSERT INTO `douyin_aweme_comment` VALUES (2902, '91660825778', 'MS4wLjABAAAABny8ef-HP91LyNVzCdYD6rhJ7y1_8YnP-U5UmWrCG58', '289348847', '', '恪守本分', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_290c1f361b4a4e029792db681e71c734.jpeg?from=2064092626', NULL, '广东', 1769050120868, 1769050137621, 7440040457243525947, 7439645541958552844, '小姐姐，可以的，虽然生活很苦，但是是你精神状态真的是好[看]，希望你一直保持而且影响多一点人吧，加油', 1732269413, '2', '0', '161', '');
INSERT INTO `douyin_aweme_comment` VALUES (2903, '2239069731422984', 'MS4wLjABAAAAiUmDiNeIEbyt4fGHPhXRyK_yNI3prw83HozPNtGGnJqqo94oVLoBAbX9SKvxjfj4', '33396157012', '33396157012', '阡陌@红尘', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '新疆', 1769050120877, 1769050137640, 7439886491542012724, 7439645541958552844, '如果赚的少，少在外边吃，自己做，省钱健康，不然哪怕赚100万，花掉200万，还欠钱呢', 1732233571, '11', '0', '214', '');
INSERT INTO `douyin_aweme_comment` VALUES (2904, '104721017092', 'MS4wLjABAAAAbsaJZMASB9Qucem4ytCs6nvsyODNlGHH4v9dlvtqIKk', '1530147858', '', '陈越之', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_340aade06d2749d3a55d8e4633990ef6.jpeg?from=2064092626', NULL, '河北', 1769050120888, 1769050137654, 7439791878628983609, 7439645541958552844, '好，我们就是要乐观的面对生活！[赞]', 1732211554, '16', '0', '919', '');
INSERT INTO `douyin_aweme_comment` VALUES (2905, '3843494347805533', 'MS4wLjABAAAABDI2MqfmH3AjSSe4NVhEXiMtZ7XMKQPhpFtO_TxCOjxzY2HvBIz1FnSymwf-Q7U4', '3675475346', 'haohaohuo88', '吃饱了§撑的', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ooWBUeKkug17G3AQAgeIAtE8pJ5LIfboQDVvAD.jpeg?from=2064092626', NULL, '福建', 1769050120897, 1769050137668, 7439869565716726579, 7439645541958552844, '一五年后的十年以后再翻出来看的时候想起第一次的工资，你会觉得人生也挺有味道的', 1732229628, '2', '0', '74', '');
INSERT INTO `douyin_aweme_comment` VALUES (2906, '96647645245', 'MS4wLjABAAAAFVUK7O5liD1sbD4HPrtiZwlZuyN323YORTHo32HMxGA', '726239210', 'zxxzaaxx', '一零三', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_ccdce1c9238222bec4fdc9b177be26e7.jpeg?from=2064092626', NULL, '浙江', 1769050145460, 1769050145454, 7543929416289977146, 7543927863856778555, '你总是急着赚大钱，急着功成名就，急着在十九、二十岁的年纪就要实现财富自由。你刷着别人所谓的成功故事，看着同龄人晒出的光鲜亮丽，心里一阵阵发慌，觉得自己落后了，觉得再不拼命就要被时代抛弃。于是你拼命学习各种技能，熬夜写计划，焦虑到凌晨还睡不着。\n可你有没有想过，你才刚刚起步啊，人生才刚刚展开。财富自由不是一场百米冲刺，而是一场马拉松。每个人都有自己的节奏，别人的时间线不该成为你的枷锁。你之所以累，是因为你背上了过早的欲望;你之所以焦虑，是因为你不停地和别人比较。真正的成长，不是19岁就赚到第一个百万，而是学会稳住内心，找到方向，哪怕走得慢，也一步步坚定。别把人生逼得太紧，该来的都会来，只要你还在坚持。', 1756457945, '504', '0', '7646', '');
INSERT INTO `douyin_aweme_comment` VALUES (2907, '7503427965255353403', 'MS4wLjABAAAAKWbd0qSA0Y0nq8qKew5x9W_TYY8aFu29e_kBW5zoWG4bDQQbYWivBjqFKCAZHWTG', '86728771973', '86728771973', '月光便利店', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_324438326f7a0ada5add346172cdb076.jpeg?from=2064092626', NULL, '江苏', 1769050145470, 1769050145468, 7544554530018870066, 7543927863856778555, '我喜欢这个对话，原来还是有清醒的人', 1756603490, '419', '0', '6195', 'https://p26-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/25a778ffffec4ddb95f1697d29f29b3c~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1769068800&x-signature=%2BRGNd7mXsn9IHMuOWdzxuStrKNc%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=2026012210490446BF8775D742FA318748');
