INSERT INTO `douyin_aweme_comment` VALUES (2954, '61585386390', 'MS4wLjABAAAAMqa0CepNTMjyj863aDiw_KE33O10ikcU81PYn2ddBJU', '21010461', '', '黎名的明', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_10ce5134acf5c8fd8ff7d733bbba389a.jpeg?from=2064092626', NULL, '上海', 1769050169053, 1769050169048, 7560563021900170003, 7551760238895271227, '点开主页发现博主果然是infp！我之前好多身边的infp都拥有很好的资历，但是放下了世俗的框架，去追求自由的灵魂，但是很多前期的infp不知道如何平衡理想和现实，经历社会了社会之后会发现可以用自己的技能太平衡，比如我们热爱拍照，画画，唱歌，跳舞，做手工通过这些变现，我们在某种程度是可以来平衡现实与理想，我们甚至还可以学更多的技能，比如咖啡师，调酒师，播音主持，自媒体博主等，其实这就是才我们的方向！但是世俗观念会传来不稳定不务正业的声音，可是有何妨呢？把不稳定的职业变稳定何尝不是一种能力呢？况且我们学会这些变现技能可以每个时段都换一次职业，那人生是多么的丰富多彩啊！我们只是明白人生的本质本身就是体验啊，选择自己观念的生活没什么不对，他人的声音一点都不重要！[抱抱你]', 1760330757, '0', '0', '24', '');
