INSERT INTO `douyin_aweme_comment` VALUES (3382, '109009772920', 'MS4wLjABAAAAmCLYRsBNHpH8qG_GKusqrhVJRMxHlWa43XQIyqHyjoA', '2167229103', 'Chen_ext_5271120', '一只独立特行的猪', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_31da8b49a123bb3c8e22ac7415dcc46e.jpeg?from=2064092626', NULL, '广东', 1769050349603, 1769050403505, 7592274567642940209, 7591750994753539379, '当下社会，跟大专谈学历，跟本科谈经验，跟硕士谈年龄[微笑]', 1767714179, '56', '0', '4207', '');
