INSERT INTO `douyin_aweme_comment` VALUES (3384, '95840661285', 'MS4wLjABAAAAaCaoIQaqTrWVPDae0wnGl6msKnAur3YxpAiHTKAUNo8', '854526013', '', '子 非 鱼', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ooRA7jAUihmBEk7VBM6MaGJiEA7AoRnAvnIAP.jpeg?from=2064092626', NULL, '重庆', 1769050349621, 1769050403528, 7597998717534323505, 7591750994753539379, '为什么会有一种情况，求职的找不到好工作？用人单位也在一直找个靠谱的人，我身边这些单位一直都找不到很好的人就一直听他们说流动太大，不靠谱，不脚踏实地，那到底靠谱的人去哪儿了靠谱的单位又去哪儿了', 1769046934, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3385, '3258571596239864', 'MS4wLjABAAAAjytcUUQWAXlRtNdIoL1XQWg7Vh6E7EEKztI6IcH4uE-THsjCLSgEV9-ngtGgr7lJ', '2157357641', '', '吞鬼.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_11f2ae88e5d145c5902c7e007e6f3376.jpeg?from=2064092626', NULL, '广东', 1769050349629, 1769050403523, 7597818468851417862, 7591750994753539379, '我也是大专 学的计算机 现在做的销售 一个月固定一万以上 高的话3W 害 不做这个也不知道做啥了', 1769004968, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (3386, '86497876097', 'MS4wLjABAAAARg7m1I7R4erK1CgwyptJAz8gARqLeP-F6ARQgM_p7AA', '584498376', '', '向日葵大王', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ookJAASIuZeDyEsUge8BKfE7FBA7AAXw4nlZAE.jpeg?from=2064092626', NULL, '贵州', 1769050349644, 1769050403543, 7598003286151365433, 7591750994753539379, '根据自己的情况和周围的环境而定吧，我护理大专毕业，焦虑工作的时候去投了私立医院和内容机构，其中有个HR给我发信息说，你才毕业因该去努力考一个公立医院而不是来一个高中毕业都能上的岗位。这句话非常的激励我，没到一个月我就考上了县医院，几年过去我又考上了syb。任何时候都要相信自己，要努力，不要放弃[爱心手]', 1769047999, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3387, '85889191452', 'MS4wLjABAAAADZnpL6550rG3vVKVifQqjH_SVb-ON1_Aip38SSmIv2I', '199495059', 'zv_031226', 'Star服饰', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_90ba4f3f11772cc381c2c4e7f0941464.jpeg?from=2064092626', NULL, '江苏', 1769050349654, 1769050403576, 7597832980681851698, 7591750994753539379, '我大专，炒股一开始赚了十万，现在欠了1万', 1769008935, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3388, '8427742174072', 'MS4wLjABAAAAvOiMIVksnBuCS5wzALBOxcxpQVMlfOWI3ojd4AAEXnk', '3653652728', 'ambaipang733', 'am白胖', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_fbfefd3be76d4ef691bd7e14ddcbbe79.jpeg?from=2064092626', NULL, '浙江', 1769050349664, 1769050403553, 7592395857380754225, 7591750994753539379, '我学cnc，25年5月份毕业，月薪交完五险一金到手一万五左右，每天8小时从不加班，基本上每周双休一个月也就上22天21天左右，活干完就休息，今天也是没活休息，就是累点，一个人管两台大机床（编程操机都是自己），八十多斤的工件要搬来搬去，搬上搬下', 1767742419, '8', '0', '10', '');
