INSERT INTO `douyin_aweme_comment` VALUES (3595, '3285774804192575', 'MS4wLjABAAAAur9RucJnFcvJ67PD0QYh7u6ow4gztWNJkRpgsijo8q6JjEocI97JOgQkjp5WtoOR', '92548347168', '92548347168', '白无无无', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_cd946d9a55efb98d4c1f9c89afa442d1.jpeg?from=2064092626', NULL, '安徽', 1769050460335, 1769050460330, 7571934282974544689, 7570383445151452466, '骗你的，大于1000粉丝的抖音号要和学校报备[憨笑]', 1762978343, '3', '0', '20', '');
INSERT INTO `douyin_aweme_comment` VALUES (3596, '1315448476409196', 'MS4wLjABAAAA66rwoOb6i-t-1Th7EnjhQaWoL-FRs5d05SJuSH298fmaLHdtdebSM0S9WOHkvvR9', '34723792613', '34723792613', 'Hinon沐光', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_owEArStBjF1AMg7f5dIABFEJdqDBb1A9Dfyf7O.jpeg?from=2064092626', NULL, '河南', 1769050460356, 1769050460350, 7570666167242130203, 7570383445151452466, '走影视传媒类工作，当下对学历门槛确实要求不高，加上越来越多自媒体博主，如影视飓风这类头部博主，做教程类的内容，使得很多科班接触的专业内容面向社会，大众化，普及化，导致普通人、野路子，都纷纷转向这个行业，使得门槛也不断降低，但做出“成就”依然有难度，正因如此，这个行业会涌进来各类打工人，越来越鱼龙混杂，项目的变动、市场价的起伏、以及工作评判标准\n虽然影视行业对学生，特别是男生这块，有独特的吸引力，你可以做有意思的内容，做拍摄、做后期，本身是艺术生产的环节，相比其他大学工科文科纯理论化的内容，他并不枯燥，现在甚至素人小白进专业影制公司实习一段时间，他都可以对行业和工作流有一个基本的了解\n但是，我不认为你以后从事影视传媒类工作和拿文凭冲突，可能你是大一，大一课程都很满，但不妨碍你以后抽时间加深对影视行业的深入学习，我双非数字媒体技术，本科是偏虚拟程序开发方向，我也喜欢做影视，这不妨碍我两手抓，一个当工作，一个当生活，何乐而不为\n\n只能说，可能我们这批年龄还不大，有时间可以多“折腾”多思考多体验，更好的去规划我们的人生[玫瑰]', 1762683078, '14', '0', '540', '');
