INSERT INTO `douyin_aweme_comment` VALUES (3611, '7457032857732219961', 'MS4wLjABAAAAZdyoVXu-t37fGpFbk4xxlGiXs5ZfN_JPx5jWx8z1UlaR_raGDWfUUJDQ5w2e4P4b', '96300746251', '96300746251', '番茄炒蛋🍅', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oYsfDf9BBEuEQwWhdAQAFE7fIk71AARkDBGA5a.jpeg?from=2064092626', NULL, '北京', 1769050468244, 1769050468243, 7526585047492821803, 7513138371674852649, '前一天晚上我们打地铺，一起在宿舍里聚餐，喝啤酒，然后说了很多很多话，第二天早上我们陆陆续续都走了，每个人走的时候都静悄悄的，我第一个走的，看着还在睡觉的她们真的有点舍不得[流泪]', 1752419649, '0', '0', '0', '');
