INSERT INTO `douyin_aweme_comment` VALUES (3891, '4418301794732595', 'MS4wLjABAAAACF5Z7CUSCft6-tRIro0XKlSFzeU8nWLBvjY_9yHC6_q6wZbqjai7WrWQ2b_yDdNQ', '62583861097', '62583861097', '有才的脏脏包', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_owtItEAAvAVw9M5cAamAuPhgnAbUiiBqI9BLF.jpeg?from=2064092626', NULL, '北京', 1769050723102, 1769050723100, 7309130925404898074, 7309060013887081728, '混个学历，多点经验，换个城市体验一下，是我的唯一动力[宕机][宕机][宕机]', 1701789664, '2', '0', '46', '');
INSERT INTO `douyin_aweme_comment` VALUES (3892, '66067179828', 'MS4wLjABAAAAHMDNrPX9CoeOcBq2l2SNPWbB1wVQ1jSIbcZgEEJzw2c', '1658443162', 'gly5954', '玉er', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_04ffd0816a3e81571f96846629e48096.jpeg?from=2064092626', NULL, '四川', 1769050723112, 1769050723107, 7325345121930167080, 7309060013887081728, '研三马上毕业了，其实我觉得这种言论挺有道理的，刚经历秋招完的我也从有过这样的想法[微笑]', 1705564824, '16', '0', '49', '');
INSERT INTO `douyin_aweme_comment` VALUES (3893, '98799421448', 'MS4wLjABAAAA7Ce-vChQNRysOdSliVQJgRM4YbtDcZEyVj-XGQZ-oJw', '959779193', 'A_Shie_Yu', '阿西野先生', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_bb89d842dddb9dfe857b19ebbada1794.jpeg?from=2064092626', NULL, '黑龙江', 1769050723123, 1769050723119, 7319591236863558434, 7309060013887081728, '本科毕业那年，我放弃了15w年薪的offer，选择读了个研究生。2021年硕士毕业，面试了一圈，最高月薪7.5k[尬笑][尬笑][尬笑]', 1704225169, '52', '0', '1734', '');
INSERT INTO `douyin_aweme_comment` VALUES (3894, '20761886841', 'MS4wLjABAAAAB7cYO2D_5fyXpUy5mQEBzKcp7Cwa7aujb3qv1l94WVQ', '385492441', '', '一口奶油泡芙', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1307c1f563c84da1593380d7034c53f6.jpeg?from=2064092626', NULL, '江西', 1769050728100, 1769050728096, 7303412992615138059, 7303155894265711913, '现在大四 在前期大家都准备备考研究生的时候 我就知道我根本就不适合 没办法往上去学习本专业 在大学四年我也一直在抵抗本专业  就像是现在要做毕设了 这几天刚开题 也像姐姐说的一样 根本就没有什么想法 根本定不了一点主题 所以我很明确的不选择考研 可是在这个分岔口 她们都有自己的想法的时候 也挺迷茫的 可能人生就是这样吧[流泪][流泪]', 1700458353, '9', '0', '51', '');
INSERT INTO `douyin_aweme_comment` VALUES (3895, '61936330895', 'MS4wLjABAAAA_diRgUxK7tmDrQolEk1hegEw12u4LvyOGWwqVaMAshE', '382011369', '2025and77', '瘤涟（见过单依纯&JJ版）', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c17d8c1f38fc3a0fb8665a577926a209.jpeg?from=2064092626', NULL, '江苏', 1769050728109, 1769050728105, 7303418304974226211, 7303155894265711913, '我的想法就是顺利毕业，遇到了个奇葩导师的情况下，在我们组想发论文很难，能发但是一作二作是自己也不一定，所以不管他们怎么卷，我就做自己想做的事，既然没有科研成就，那我也不后悔，因为结果都是一样的。。不再因为别人影响自己，不随波逐流，不看着别人生活是我对我本科毕业后最值得骄傲的改变[嘿哈][嘿哈]', 1700459591, '1', '0', '127', '');
INSERT INTO `douyin_aweme_comment` VALUES (3896, '2444936907078814', 'MS4wLjABAAAAiJFcpJ3b8LAUHHpdhsNof7P_uFFfrAMs3BmCXe37aXzerMnVWkN-HUU03OXofmQc', '3880751970', 'L_fei_', '小梁_🌰', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_3e7a16aa84894c518a4dca8ac28a7254.jpeg?from=2064092626', NULL, '浙江', 1769050728118, 1769050728114, 7303414026859840308, 7303155894265711913, '我本科的时候专业第一 身边的朋友觉得我肯定能考上一志愿 没有并没有 考试发烧了但其实我也不知道考试发烧对我的影响到底有几成  调剂到了另一所学校 每天都在哭 不想当混子 每节课都尽量坐在前排 也在每天都在认真看文献 但是就是没有能力读懂找到自己的方向', 1700458595, '5', '0', '42', '');
INSERT INTO `douyin_aweme_comment` VALUES (3897, '98127135283', 'MS4wLjABAAAAu1CvuObjHELH559GPuqdF9OAvOAuxEtKTNzD5RdcEhE', '1065268553', '', '🌻花花花', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oMK7vAAqzAAxjTCICPfhgdz6ABAeLQAIENN3DH.jpeg?from=2064092626', NULL, '广西', 1769050728126, 1769050728122, 7303405692773204787, 7303155894265711913, '当我选择这个学校和这个专业的时候，我就想，我一定要考到更好的学校[流泪]但是真的接触到大学之后，我发现我可能要烂在这儿了，我觉得学习很痛苦，也并不是很热爱这个专业，如果我真的考上研究生了，那我也会和现在一样痛苦[流泪]', 1700456653, '4', '0', '103', '');
INSERT INTO `douyin_aweme_comment` VALUES (3898, '3465263736684590', 'MS4wLjABAAAAwe9XjwXVcXrbjgAJHyvILqHg6Z6I7kjICcY1kESh20N5yyXXpE0FhZP3XHCijoyW', '21101857845', '21101857845', '豆角焖面.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_fd2b4ab85c914884ab24008035320ae6.jpeg?from=2064092626', NULL, '贵州', 1769050728135, 1769050728131, 7303417941638333224, 7303155894265711913, '就真的只想快点毕业，本科的时候害怕毕业，害怕就业的选择和困难。可是现在也知道工作可能也没有多好，但是真的好痛苦啊。读研，其实文科好像就没有理科那种忙碌的不可开交，可是心态真的很痛苦，我每天都是在想现在会不会是一场梦，或者某天醒来我就毕业了，跳过这中间时间。因为现下痛苦，所以把希望寄托于未来。即使知道这样不对，不过好当下是没有未来的，可是真的好累，好身心俱疲。我时常想如果我生活在一个有很多选择的世界会是什么样？', 1700459507, '10', '0', '578', '');
INSERT INTO `douyin_aweme_comment` VALUES (3899, '111532366964', 'MS4wLjABAAAAGgPxQhhMuu4uw7MeWVdshR-qksawmTMQElpOUvzhUGE', '2118973883', '200610283799oo', '青青草原最聪明的小羊（好运爆棚版', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_4d0fc2086b0c21ee479764c84151c228.jpeg?from=2064092626', NULL, '天津', 1769050728142, 1769050728140, 7303441798805324556, 7303155894265711913, '那就愿我们都能勇敢的走下去，健健康康，顺利毕业[调皮]', 1700465060, '3', '0', '956', '');
INSERT INTO `douyin_aweme_comment` VALUES (3900, '66870629999', 'MS4wLjABAAAAsXWlnzB8BT8zzb0UyKJsDuoWOBmCzuCnnR4SAbYNmO8', '318033', '', '🫡🫡🫡', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oslw0AfE85QAOy7DBfg8IoFE0fA1AQmXDSJsEI.jpeg?from=2064092626', NULL, '湖南', 1769050728149, 1769050728146, 7303413540847780645, 7303155894265711913, '做好职业规划，研究生期间就不会变成混子了，如果对科研没有很强兴趣，不考虑读博，则在达到毕业条件后可以考虑就业，毕竟以后步入社会，看的不是成绩，而且内在和外在的各种影响因素以及自己的工作能力。', 1700458479, '3', '0', '84', '');
INSERT INTO `douyin_aweme_comment` VALUES (3901, '107781585047', 'MS4wLjABAAAAWRjnqUfLDr9tYUdZdplD5ULESq0_Il760U28vaK5QeY', '2065967386', '', '王师傅的人生浪费指南', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_ccf8def2e4bce80b0e1c8cd2cd6ea75d.jpeg?from=2064092626', NULL, '浙江', 1769050728158, 1769050728154, 7303413014631465765, 7303155894265711913, '[暗中观察]其实没有什么阶段应该学什么，这都是别人总结的，世俗规定的。 能发现自己缺什么，那就学啥呗，顺序啥的一个是不太重要，另一个是无法控制', 1700458359, '2', '0', '748', '');
INSERT INTO `douyin_aweme_comment` VALUES (3902, '4305279570685532', 'MS4wLjABAAAA1iF9RHcg5iG60sqjvlBblBNsUQUyR6F6-AGoS0lRy0ZBi1afT5K8JI7uz8Xe3w7x', '2320295801', 'ZXR20010529', '椰椰小屁', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_973b2d83e59018026c70be54ea15589f.jpeg?from=2064092626', NULL, '内蒙古', 1769050728165, 1769050728163, 7303414769863754511, 7303155894265711913, '是的 我只是想有个学历 但现在看着周围的人好卷 我就会压力很大很不开心[流泪]', 1700458767, '14', '0', '597', '');
