INSERT INTO `douyin_aweme_comment` VALUES (3923, '102353424388', 'MS4wLjABAAAAukfpbDoj1fnNtQ41kM___0uoYVwU0SEB67cSwwjuuTM', '3665683978', 'hmz1012.', '布支到', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oMWCoAI61ABrgGApEPDACzm4vCit9fWivACofA.jpeg?from=2064092626', NULL, '山东', 1769050741508, 1769050792755, 7591161437315105555, 7590773997856378122, '[偷笑][偷笑][偷笑]不得不说，90后的年轻985博士毕业的导师是真强，手把手教我写论文', 1767455007, '3', '0', '25', '');
INSERT INTO `douyin_aweme_comment` VALUES (3924, '95950085291', 'MS4wLjABAAAAz1IuMeEWS-Tck9LGSn_HgU-vFXOJYMog7FpX5ayW6U8', '619567973', 'keepdoingsth', 'Lucky ONE', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ow60laiPxvh7ECAjhwUIAHgAAALGIL0ziBkkP.jpeg?from=2064092626', NULL, '黑龙江', 1769050746393, 1769050746386, 7593748765695083270, 7593682916598156709, '研究生相当于上班了，只是没有工资，自己还搭钱，相当于学徒，最后给你个毕业证而已，所以导师想怎么使唤你就可以怎么使唤你，全看人品，你想德云社有寒暑假么[黄脸干杯]', 1768057417, '36', '0', '1279', '');
INSERT INTO `douyin_aweme_comment` VALUES (3925, '1337427641243959', 'MS4wLjABAAAALeOTOWtY4fOD8SVkIcKsFTtLFaTWA5cnL_F6--48UVJRJVtqadSLw5LN7NWdBcVc', '4147514408', 'yuxiaohu0', '入云青竹', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ocAmAfp3DAAnFAFAXwE0NsExMCNIEjDged9zMA.jpeg?from=2064092626', NULL, '河北', 1769050746412, 1769050746407, 7594044952817287962, 7593682916598156709, '我姐说她硕士期间因为疫情一直在家读得。组内有个大牛博士师兄，随便甩给她几篇文章就毕业了。她整个硕士期间记忆就是隔离核酸，隔离核酸。[尬笑]', 1768126375, '1', '0', '31', '');
INSERT INTO `douyin_aweme_comment` VALUES (3926, '111322937582', 'MS4wLjABAAAAzsz2XT0hPU5Uq8L1g4gbvHViK4mR4radAt3oJXX0Cc0', '2084094515', '', '荡漾的饼干', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_1b59c000101efb2318b54.jpeg?from=2064092626', NULL, '北京', 1769050746436, 1769050746429, 7593911786921067313, 7593682916598156709, '这么刁蛮的老师大部分对本科生都挺好的，要骗人来读他的研[黑脸]换句话说，你如果遇到一个对本科生特别好的导师 我建议你要读研的时候打听打听他带的学生', 1768095373, '135', '0', '9367', '');
INSERT INTO `douyin_aweme_comment` VALUES (3927, '97441026874', 'MS4wLjABAAAA6aARJenkS0OGjW6-SD5aBd0NEt_i4Cu7aHwEwnpWNhE', '1218165652', '', '小日子过得不错', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_197ffe893e5140eaa304303322842710.jpeg?from=2064092626', NULL, '吉林', 1769050746454, 1769050746445, 7593747295389401893, 7593682916598156709, '我们学校为了防止老师捞学生，平时成绩是提前上的，然后系统锁死，不能再改动。我教的班级有一个总成绩59，而且80+人只挂了他一个，我实在是觉得59挂了这个年都过不好，卷面翻来覆去找了好几遍，勉强给找到1.5分，终于及格了[裂开][裂开]', 1768057072, '1', '0', '21', '');
INSERT INTO `douyin_aweme_comment` VALUES (3928, '11964027847', 'MS4wLjABAAAA1f_oiMcwUXCOAFaiLJHz18Q7I-lBpzpElFrxDXDxbCw', '130202632', '', 'Dva', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_77685f4f2aaa47b3b6591007d82bea00.jpeg?from=2064092626', NULL, '日本', 1769050746469, 1769050746464, 7593778536205468465, 7593682916598156709, '我故意把胡子留长，头发不洗，破衣烂衫，我老师终于察觉到我精神可能有问题，她才对我说了几句软话，现在还不知道能不能回家[流泪]', 1768064348, '17', '0', '1287', '');
INSERT INTO `douyin_aweme_comment` VALUES (3929, '106725024888', 'MS4wLjABAAAAXyyb4f7CWwS1i4dQC7ykeLswW22objPVS-Sj2htm3tg', '2305394440', 'QQ2927359884', '真的不是晨', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ooAqlVBwsAE8Ri8DUcMDFMAIHP5abBABPiAPa.jpeg?from=2064092626', NULL, '辽宁', 1769050746479, 1769050818627, 7593991759269970746, 7593682916598156709, '我没记错的话，这应该是59吧[捂脸]又一个本科生要哭了[捂脸]', 1768113991, '4', '0', '305', 'https://p3-sign.douyinpic.com/tos-cn-i-p14lwwcsbr/92e166301ab04c4b99b6155365d63531~tplv-p14lwwcsbr-7.image?lk3s=7b078dd2&x-expires=1769072400&x-signature=%2FYnVwtJx7CLT3k3Td4NeFripPkg%3D&from=2064092626&se=false&sc=image&biz_tag=aweme_comment&l=20260122110017DCF1ABC7F95A1438F245');
INSERT INTO `douyin_aweme_comment` VALUES (3930, '1012028420138671', 'MS4wLjABAAAAhbA3tcoKjes2Pb7O27DWHrer4PfYjJn5vv3yasYnmPm4CcW3mWv1LXsXvEo6v2vy', '66970259679', '66970259679', '一定要上岸啊', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o8s1GF9AEQCIgVUqtlfn4A4A9AjgoDN7AAofCS.jpeg?from=2064092626', NULL, '湖北', 1769050746499, 1769050818635, 7593932542500258611, 7593682916598156709, '但是我的院长父亲跟教授母亲说，过年想多跟我待几天[流泪]', 1768100205, '4', '0', '134', '');
INSERT INTO `douyin_aweme_comment` VALUES (3931, '389659715970084', 'MS4wLjABAAAAV63Mf-WFp49UfyZxDaIt0LlK1M5gQuPBYj-GUAFvP3M', '79491742326', '79491742326', '雷子不想打多拍', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_5a0e535a3a7e4f13fe4080002a4c452d.jpeg?from=2064092626', NULL, '上海', 1769050746519, 1769050746512, 7594738028549292810, 7593682916598156709, '听我一句劝，选导师选老教授，尤其是快退了的那种，我们导院长退下来的，还有几年退休，完全不管你去不去工位，只要你能把论文发出来毕业就行，你愿意帮着干活就给钱，小到六百大到2k，我们几乎每天都是寒暑假[看]', 1768287748, '0', '0', '13', '');
INSERT INTO `douyin_aweme_comment` VALUES (3932, '2462498316369231', 'MS4wLjABAAAAy65PLy0uQA4bjNE8kCqd52EpS602uA_lCFzz87eFgdc6FJWFRbJHtKamlhlF6XP1', '3767764568', 'sax0429', 'Saxxxx', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_ooGDef4TItEAC0yCBV3nbAc909A8AAvgAallQH.jpeg?from=2064092626', NULL, '广东', 1769050746531, 1769050746526, 7593935287710745393, 7593682916598156709, '工作有劳动法，读研没有[耶]', 1768100843, '105', '0', '7456', '');
INSERT INTO `douyin_aweme_comment` VALUES (3933, '413058299074951', 'MS4wLjABAAAAZ4bbWWiKm9fSUe79cXuA5epvmSR4bJwfLofSFhgASi0', '3691037317', 'dyseazjdozc1', 'Carousel', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oc2AmCELrVDA9OgtKWADFGYAfeNADoIAswExyD.jpeg?from=2064092626', NULL, '河南', 1769050746540, 1769050746538, 7593776184593285945, 7593682916598156709, '文科生玩的都忘记导师是谁了[钱][钱]', 1768063800, '24', '0', '1513', '');
INSERT INTO `douyin_aweme_comment` VALUES (3934, '558205924291720', 'MS4wLjABAAAAfFnKKu3IneFM_dksiBOKDSeSMgAaU-OmT8GgmD9-uBo', '3011739856', 'Yx5201314..dy', '周宇', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_93fba4d4b7301d418ec1ee5ec1144626.jpeg?from=2064092626', NULL, '江苏', 1769050746554, 1769050818619, 7593960626138940212, 7593682916598156709, '学生：“老师，您是没家吗？”[摊手]', 1768106743, '42', '0', '3275', '');
INSERT INTO `douyin_aweme_comment` VALUES (3935, '99820052657', 'MS4wLjABAAAAmTfMy7ST5olTz8TzQ-xiPH6sj4Ov-MgkcugOdBJFieQ', '1027082817', 'Y207781125', '莞盈', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_346863656f834dc1a852930bbe380158.jpeg?from=2064092626', NULL, '浙江', 1769050746563, 1769050746559, 7595439182039188262, 7593682916598156709, '研究生不算学生算打工人了[流泪]是有薪资的 假期按照法定节假日来', 1768450995, '1', '0', '17', '');
INSERT INTO `douyin_aweme_comment` VALUES (3936, '2273437068043396', 'MS4wLjABAAAAtNKlqLmM4n283MR8Ep32B2TzDBy_GUHj1dvJSKiQcMgiM6Nqq3P5FcyOmMxMMq6q', '2990011493', 'dy8z1hrdybe1', '您的昵称已被占用', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_4e0bfe3fdbe5ba91ad855b389db323c4.jpeg?from=2064092626', NULL, '比利时', 1769050746575, 1769050746569, 7593732990728897337, 7593682916598156709, '当时我一本科的舍友就是这样被导师压榨的，不仅帮导师整理论文整理到两点，甚至自己的作品被导师抢过去参赛拿奖，最狠一次本来大家约的晚上六点半一起走去聚餐，结果硬被导师在宿舍里网课到八点半，期间那个导师还讲一半说突然有事让他在原地等，他说老师我接下来有事那个老师直接在电脑里大骂你有啥事？你什么事比你现在这事重要？然后老师不在的期间他直接崩溃了，疯狂敲自己头，边哭边疯狂骂学校，给我们吓一跳，后来导师让他考本校研究生，他一边好的好的报名，然后研究生考试故意旷考一门把分数拉低，一边直接润去德国了，然后圣诞节来找我玩说德国研究生真轻松啊[泪奔][泪奔][泪奔]', 1768053742, '18', '0', '212', '');
INSERT INTO `douyin_aweme_comment` VALUES (3937, '3193399057850477', 'MS4wLjABAAAA0FQulkVNB4fpn3U9sryaoud9GBAVPdJhl_CNC_H6NDRg5MLtK0UQmtmsf5J2gEqY', '23786626523', '23786626523', '唯梦闲人', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o4Kg6Ac6jeAYoEIpAOFfEEwZeNrAY5EH9ADjAG.jpeg?from=2064092626', NULL, '湖南', 1769050746584, 1769050746579, 7594011322171687737, 7593682916598156709, '其实，我对你是有一些失望的。当初把你招进来，是基于你本科时的水平的。我是希望进来后，你能够拼一把快速成长起来的。我们这个组，不是把事情做好就可以的。你需要有体系化思考的能力。你做的事情，他的价值点在哪里?你是否作出了壁垒形成了核心竞争力?你做的事情，和其他人的差异化在哪里?你的事情，是否沉淀了一套可复用资料和方法论?为什么是你来做，其他人不能做吗?你需要有自己的判断力，而不是我说什么你就做什么。我不需要中规中矩的答卷，它是有一些差异化在里面的。后续，把你的思考沉淀到组会里，我希望看到你的思考，而不仅仅是进度。另外，提醒一下，你的产出在我们组是有些单薄的。如果再这样下去，我不能保证你按时毕业。', 1768118547, '61', '0', '2608', '');
INSERT INTO `douyin_aweme_comment` VALUES (3938, '96482707977', 'MS4wLjABAAAAvoLVsELAMF1kMHkOI8mc2tr3uHxnxtJMvQsh_WsEHgQ', '912480064', 'fvnkifgnkoibmk56', '芒果', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_a7a6286c84ee4bd306b54869b874c3ef.jpeg?from=2064092626', NULL, '广东', 1769050746593, 1769050818653, 7593773435118797605, 7593682916598156709, '我听到了59，骂研究生就骂研究生呗，怎么还搭上个本科生挂科', 1768063161, '2', '0', '44', '');
INSERT INTO `douyin_aweme_comment` VALUES (3939, '874859011512024', 'MS4wLjABAAAAV-JIRIppoA0Kf5s61A1JwgGoyjshEzfGjXXisaa655o', '2967794173', 'dy7t8kigxsyd', '绘事后素', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_0b95f6b4b5e4f199cd2813fb580e8144.jpeg?from=2064092626', NULL, '四川', 1769050746602, 1769050746600, 7594045218119598885, 7593682916598156709, '我老师只会让我早点走 还要开车送我去机场 过年再多发点补贴[戳手手]', 1768126437, '3', '0', '48', '');
INSERT INTO `douyin_aweme_comment` VALUES (3940, '100382132050', 'MS4wLjABAAAAXcrqZqN1cw7E7zcIhUqomU5TJElVfFc4FkKGz897xyY', '1143133313', '760244.', '唉😔', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_fc9534d0301b43879a6fa68cd80e8354.jpeg?from=2064092626', NULL, '河南', 1769050746612, 1769050746607, 7593721392526197545, 7593682916598156709, '告诉老师，她想不想让校长，看晴天娃娃。过年不假就在学校做晴天娃娃。', 1768051042, '4', '0', '160', '');
INSERT INTO `douyin_aweme_comment` VALUES (3941, '2295376535891421', 'MS4wLjABAAAAoI6lMB-5vgC00oHYGz804idUYRfomR9Q0P5F7fIiFUv4DphDgjRlG6kf5k6EOs2P', '3436459805', 'lamian88755', '拉面', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o0kwDEUPIAj3C5nAExACuAAiA9e3HNbe9gCn9D.jpeg?from=2064092626', NULL, '广东', 1769050751498, 1769050958835, 7453096202985358080, 7453023464690060578, '建议还是先考公考编吧，本科毕业的时候我们班分成了考公考研两派，上岸的同学里面考研的今年出来都找不到工作，考公考编的都领证结婚了买车了[暗中观察]', 1735309189, '15', '0', '68', '');
INSERT INTO `douyin_aweme_comment` VALUES (3942, '3237407196973948', 'MS4wLjABAAAA9cx2k8CB_trSbdMR8jMX-2RCN96fRIdXucuIdKef5tpJCCLs4DROWcxo-FNnbFtA', '4188226987', 'hjl990921', '年年', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ow5JvAAe9FEP8dGfRzLIAvGfHfAs68AQIre0oJ.jpeg?from=2064092626', NULL, '四川', 1769050751514, 1769050958850, 7453106188743361314, 7453023464690060578, '说研究生找不到工作的，那是人家找不到3万+的工作，不是找不到五六千的工作[微笑]', 1735311517, '7', '0', '50', '');
INSERT INTO `douyin_aweme_comment` VALUES (3943, '997974506735143', 'MS4wLjABAAAABtxm6lYa02y5rPVnIZaY5skUsqGsfkVD62mvNWV8K0c', '2808061147', 'jixiangyuer5', '🎀繁华🎀', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oQCIDQevgAoHAayV9FfsXmDC4ATGQEA7iAluAa.jpeg?from=2064092626', NULL, '山东', 1769050751525, 1769050958863, 7453257410162459401, 7453023464690060578, '儿子说今年不一定考上研，要二战不去考编，作为妈妈心里慌得一批，听了您说的，那就顺其自然吧，谢谢', 1735346728, '1', '0', '10', '');
INSERT INTO `douyin_aweme_comment` VALUES (3944, '65611951116', 'MS4wLjABAAAAWUFY8ibPeCsDKAtF_fEQOc8EMm4NwBbA3fBtU2bvWCg', '80359560', '', '狂想曲.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_df084ab77dba043651a51ce1796ee727.jpeg?from=2064092626', NULL, '河南', 1769050751537, 1769050958875, 7453094126814200603, 7453023464690060578, '我是本科生 我考虑很久了 如果学校教的有用的话 那么我们不会和社会脱轨这么严重 如果学的有用的话 我们不会出了校门就没有工作', 1735308710, '13', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (3945, '93657048874', 'MS4wLjABAAAAzSPB9JNbMf0rzdVEQhiNSv_1sqokYTRw4_43aKvFx3Y', '1176884343', '', '方源', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oEEeAfhQw66IHVLs7xQAHfAQaDAeAfnDAHhI1G.jpeg?from=2064092626', NULL, '江苏', 1769050751557, 1769050958888, 7453077830815351562, 7453023464690060578, '如果能去985 211 双一流的好专业，可以考研。如果为了考公转专业考研，也可以。但是如果只是想混个研究生学历，去个双非，甚至双非二三本，那真的是浪费3年时间。现在这个时代要么你卷的很牛逼，要么拓宽技能面，所以对大多数人来说，拓宽技能面才是正确的。', 1735304914, '7', '0', '40', '');
INSERT INTO `douyin_aweme_comment` VALUES (3946, '59374059922', 'MS4wLjABAAAA0C0HlHgRNpzjUDbyMfjNNPmfrZ2YcQjWMWsHgzAWnF4', '163821143', 'feisier', '肥四儿', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_c84e42e29e0889856045d850a3180a68.jpeg?from=2064092626', NULL, '山东', 1769050751576, 1769050958899, 7453125255067288372, 7453023464690060578, '想读就读，不想读就不读，最怕的就是跟风，对自己没有规划，虽然我当年没考上研究生感觉很遗憾，甚至觉得自己完了，但是走向社会之后发现本科学历也还行，只要别高不成低不就，幻想一劳永逸就不会太差，是工作就会累，有多大能力就吃多少饭，足矣[笑哭] 希望能给学弟学妹们一点力量，都有光明的未来。', 1735315957, '2', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (3947, '791238831780733', 'MS4wLjABAAAA__m0U_g4fpZQuf_yFbbXz88h8szD4Q_yAM6NeeS-86c', '56106453993', '56106453993', 'euo', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o01tfeAKIIGhZxACd7gDoGfI0QWKIpAeAA1LB2.jpeg?from=2064092626', NULL, '浙江', 1769050751597, 1769050958914, 7453092870574080803, 7453023464690060578, '研究生真没那么好找工作了，现在各行业不景气，都不会养闲人，基本工资高的关键岗位都要求三到五年的经验，学历大专就行[捂脸]', 1735308415, '2', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (3948, '111242536162', 'MS4wLjABAAAAkEBQzD7zT2i6ZDlvZmMZoP9Iwg6BH9fBmXSjoPIH1D0', '2067691521', '', '花开富贵（昵称已被占用）', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_17ff5a38cab54f35b3a28079146f8cbf.jpeg?from=2064092626', NULL, '黑龙江', 1769050751613, 1769050958927, 7453251174839518012, 7453023464690060578, '一件事物是否有价值不要听卖家的，而是看自己是否有需求跟其他买家的真实体验，与本科一样，研究生也分专业，学校，369等，每年上岸985211的依旧是少数中的少数。', 1735345274, '1', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (3949, '105541360682', 'MS4wLjABAAAAUJDxhyBnrBSwy4kFM2ZgZEv3YH-JxwuO-VYdp_smksg', '1666810214', 'L_0103_J', '阿乐同学📷', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oUbAnEwDg3ACu0SFfAo9AAA0EdXfRFId2SLAID.jpeg?from=2064092626', NULL, '北京', 1769050751625, 1769050958939, 7453261146030097191, 7453023464690060578, '最不后悔的事就是考研[看]，收获了更多更好的就业选择[捂脸]', 1735347599, '0', '0', '8', '');
INSERT INTO `douyin_aweme_comment` VALUES (3950, '1915762326647449', 'MS4wLjABAAAAiJosiuT2s2jbLR6Y0p22O3dKZtu_H7Bh3hjkq1YJsml2sUtBFicaApU1zdUiVN4P', '76805773992', '76805773992', 'Ethan', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_os6Pu0kfAAAfA7ZoAEL94DaGXemmFIBIBBEDwI.jpeg?from=2064092626', NULL, '黑龙江', 1769050751637, 1769050958954, 7453100304470377225, 7453023464690060578, '读书这条赛道是给那些相对比较内向且家庭不好的孩子来选，没背景没学历还内向的孩子走进社会 那你的人生将会开启困难模式', 1735310145, '2', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (3951, '65607135790', 'MS4wLjABAAAA_iklDYlsftSEWA_nVrlqwWUqKi8urYEX6_Lk_56vDUI', '930988795', '', 'Kiran', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_7f60936a1bb39fccc3c182fe1bdc8165.jpeg?from=2064092626', NULL, '北京', 1769050751648, 1769050958966, 7453099625110438710, 7453023464690060578, '近几年研究生找工作确实也困难起来了，毕竟疫情期间研究生扩招，越好的城市越明显，北京的的确确不夸张的讲城六区研究生烂大街，但是烂大街也是因为都有追求，面试的都是央国企或者外企，再说回来某些单位还是卡学历的，包括职称多多少少都会被卡学历', 1735309987, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (3952, '62008364843', 'MS4wLjABAAAAoH8kudyeugYqScLNUu7Lpk0TySaSxJmgbQaIuA5ZhZI', '46470204', '', '小朋友', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oEpiwLbAIhPAbBwaBASTXIi2gZimYblAEUwAP.jpeg?from=2064092626', NULL, '浙江', 1769050751659, 1769050958976, 7453092557373276938, 7453023464690060578, '老师的意思大概就是，考研是为了成为一个普通人，有资格更好地去参与竞争。感觉我们过度神化研究生了，好像考上研，一辈子什么都不用愁了[捂脸]', 1735308344, '0', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (3953, '1116753291382168', 'MS4wLjABAAAAci5EElikil6tZRZcijUhOFfIKSOQqPxHbXCU7vbP0Jx1X4uihZMAhf2rh1qUyWaU', '87768271314', '87768271314', 'mky', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_6c709d9bb63041eabbd9b4922a4bd6b1.jpeg?from=2064092626', NULL, '新疆', 1769050751670, 1769050958994, 7453101087949128487, 7453023464690060578, '研究生一定不会烂大街，但后面的就业研究生就业不一定有优势[微笑]', 1735310327, '0', '0', '7', '');
INSERT INTO `douyin_aweme_comment` VALUES (3954, '347041103351300', 'MS4wLjABAAAA4z_NI3BCuZyLwZcGA51zZGRDgBoM9XBjV3u3cNMyYX4', '3482279794', 'tangxinluobo49', '风吹稻花香', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_4425d9194c224caba4905cfe4ccfec9f.jpeg?from=2064092626', NULL, '广东', 1769050751679, 1769050959007, 7453248832119292682, 7453023464690060578, '老师说的没错，靠着研究生学历备考2个月上岸珠三角市直top4体制单位，没有这个学历不知道要多辛苦才能来到这[比心]', 1735344734, '0', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (3955, '840463502541260', 'MS4wLjABAAAAH3FCeIS6KaTFB7JY0TS5OqIsYDl67CpPH1FtuKOJ3bk', '87234512069', '87234512069', '奕宝贝baby', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_9414a47889a1080cb29e96334544b5c8.jpeg?from=2064092626', NULL, '湖南', 1769050751686, 1769050959017, 7453179144005845799, 7453023464690060578, '名校研究生还是很吃香的！以前还分ABC分区。A区北上广就是难，含金量高。', 1735328539, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (3956, '100672560159', 'MS4wLjABAAAAMY1NGMqTZGLmsC-FVrboF95iWmhFG1Q1SFiVYP5gZrY', '1104590759', '', '文', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_31e3f9dd26373c1295eeaf65d95a8445.jpeg?from=2064092626', NULL, '河北', 1769050751694, 1769050959030, 7453098067672351500, 7453023464690060578, '如果是疫情前 确实是这样 疫情后就算了吧，我电气的，你个普通一二本就算考上了个电气类211，大概率也得回县里，要考试你也得考得上。', 1735309623, '0', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (3957, '937240274141200', 'MS4wLjABAAAAlA_kDauuWYAQ0oHWFpRGmqW0Cv_dInbSfrt7AKpEFJk', '56167663847', 'times674', '芯er', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_69259bb64be3991aba70812af572e68c.jpeg?from=2064092626', NULL, '山东', 1769050751702, 1769050959043, 7453125814978085672, 7453023464690060578, '现在小学老师都必须要本科了[泪奔]好多人都说学历没用，大学生都找不到工作，可我想说的是很多基层的工作入门资格都要卡学历，我上家公司的销售岗位卡在本科[泪奔]', 1735316090, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (3958, '100612349760', 'MS4wLjABAAAAsgl5QQY6f-pUs6enIPJoSKLOf3tHLBwVKoA0VGsd_fc', '1142206964', '', '啦啦啦', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ooSpTAbAeI7AyNctDDEA7uzyAwZfhATWCgE226.jpeg?from=2064092626', NULL, '山东', 1769050751714, 1769050959057, 7453098217858302771, 7453023464690060578, '没有人会为你的抉择买单，那些本科你能进的岗位，研究生有可能进不了。985研究生能进的国企，985的本科生也可以进。', 1735309659, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3959, '2795382138224020', 'MS4wLjABAAAAlu82kL3zNPInz_Sw6Q0alTWjaI56YdItqTCZkdplDbS-Ix9kV545E92lNbsSGu12', '56062446383', '56062446383', '6', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oMeg7RAYEIYIBwPLBAgASnHev7eAzLQGAkEEYG.jpeg?from=2064092626', NULL, '北京', 1769050751719, 1769050959070, 7453127188898349835, 7453023464690060578, '硕士研究生有优势是事实。\n\n不过，真正走上社会的就明白，确实有一点优势，但不大，还得是看能力', 1735316412, '0', '0', '2', '');
INSERT INTO `douyin_aweme_comment` VALUES (3960, '59201883506', 'MS4wLjABAAAAlIdn0fDe_ff439RzJR9qTv8ZIfbsIa6vUt4LHc6kk54', '902341266', '', '缘浴春风', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_dcaeb9c48c5c4938be0c38fde5650c2b.jpeg?from=2064092626', NULL, '江苏', 1769050751731, 1769050959082, 7453097403122565923, 7453023464690060578, '不是学历贬值，关键是没有人才啊。经管类来说，你能提高分公司在当地的效益，营利双增。拿研发来说，你能短期内帮助公司突破瓶颈，节省大量时间与研发支出。拿生产来说，你能帮助公司质检突破欧盟与美国标准帮助出口，或者把新研发的产品快速商业化。马老师说得对，你要有真本事吧哥们，不是拿张纸找工作，而是在学校里就有所成就，让公司听说过你的名气，愿意高薪聘请你[一起加油]', 1735309469, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3961, '98467866380', 'MS4wLjABAAAAmV1FEe3Z0R0Deewa5XdSVZiv6HME2zaA0pBJv_ceX8Q', '3410548853', 'hui3805335', '辉', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '湖北', 1769050759719, 1769050808454, 7595552002621408051, 7493022689636961573, '现代社会就大学生遍地都是，素质和能力最重要。《大学毕业证》不代表能力和素质好！，能能给公司和社会带来多高的价值利润才是真的。', 1768477263, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3962, '94348576673', 'MS4wLjABAAAAhUJ7r0YhIViK4B_HXv7TXXwU_V9VgBYMNQ0yWUvtn8w', '392701555', '', 'Ccd', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_1736f00042920ca1fa526.jpeg?from=2064092626', NULL, '云南', 1769050759728, 1769050808465, 7595798095893431055, 7493022689636961573, '你在说啥？承认事实吧，我们科室来了个研究生👩🏻‍🎓，我是万万没有想到啊，三四千的工资，我想几天硬是没有想明白[微笑][微笑]', 1768534563, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3963, '99636279408', 'MS4wLjABAAAAQzco-mGFLp1c4xrWcMeeOKP06RIfF4lhnnltfqtgpXc', '1013971453', 'yuan47dong', '旺仔李白', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oshIoAIoWAD4gmAsEwCACH6EfDFa9h4ExAHcfA.jpeg?from=2064092626', NULL, '山西', 1769050759735, 1769050808468, 7500917596419457828, 7493022689636961573, '大学生找工作几个月，去武汉找了个非专业月薪三千[憨笑]@我也不太了解她 @落花拂绿. @語彙が足りない. @ONNI-L @临 @勿穿 @216° @西红柿 @188 @w²x @@ta @SHO(•‿•) @几碎小慧🌾 @小纸条^ @奕', 1746443479, '1', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (3964, '78176131459', 'MS4wLjABAAAAXam0nyAgV3BHEsCtgadtfnD8sMiStFQ1ioV6zacEM3Q', '141420627', 'll583934', '小傅', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oUXAsCEm0EDA9JgbNmATFjeAfrNACoQAYnIIlH.jpeg?from=2064092626', NULL, '湖南', 1769050759744, 1769050808478, 7594767391835095834, 7493022689636961573, '物以稀为贵，现在遍地大学生所以就不值钱了', 1768294583, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (3965, '86655340312', 'MS4wLjABAAAAI1_avB52MihWe81XysnzlKliphZFJn19musnqIpnU-g', '206329648', '1515368937a', '小风🍁（地铁逃生）', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_ogAHAPl5BEB0iAgAmni2f9EZsCoIGxuw9jeSZA.jpeg?from=2064092626', NULL, '贵州', 1769050759754, 1769050808487, 7493766636845335356, 7493022689636961573, '学历贬值不是事实吗？', 1744778513, '1', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (3966, '1341859221482559', 'MS4wLjABAAAAqolSxWs8MP2x75oZp-Vf5vIlht_AIksv21lHiZwcbrVTiXwb-_a07lxOOXHj31HO', '72044688418', '72044688418', 'kll', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oAC3AsRApiAAZAdAE0iB2TfIIANQgiwtANDZCe.jpeg?from=2064092626', NULL, '江苏', 1769050759762, 1769050808494, 7524197163464442651, 7493022689636961573, '如果家里没有资源人脉，是提升学历还是打工啊[流泪]', 1751863673, '9', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (3967, '2779178378996904', 'MS4wLjABAAAAetxAc9ccSGOQhMFzQBs7TikdDL99_gDdLZiwmkSXpeOoZqlDBoYOFIAK3sGdfvrp', '3846570765', 'liikxbii', '发福奥利奥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_5a6cf596c5427ddbcf6f9f76b03dc6ff.jpeg?from=2064092626', NULL, '浙江', 1769050759772, 1769050808501, 7494116611344450361, 7493022689636961573, '大家太卷了想走歪路了，那歪路都挤满了人', 1744859998, '7', '0', '173', '');
INSERT INTO `douyin_aweme_comment` VALUES (3968, '564512271638298', 'MS4wLjABAAAA4jCii9JyZ0G7AgYeu232uUwzxAw_MwleN175oquhd30', '30446951585', '30446951585', 'zzzz', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_o81bErfDeEgL9epASGHxBURBQENAPEjAFAAdIw.jpeg?from=2064092626', NULL, '广东', 1769050759781, 1769050808511, 7594397338609959690, 7493022689636961573, '别什么贬不贬值的找不找得到工作，再不好研究生，就是比本科大专好[憨笑][钱]', 1768208423, '0', '0', '0', '');
