INSERT INTO `douyin_aweme_comment` VALUES (4065, '101456958228', 'MS4wLjABAAAAwv1DyGrXkolh5Kl2kvrzMkIdam0KHnIv7KYpWfvqNXw', '1136730024', 'xy8kun01', 'DMD', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_d604672e7f5a9744bf5b93d79f56fd49.jpeg?from=2064092626', NULL, '北京', 1769050828911, 1769050828906, 7475344327465108282, 7473882439853575482, '学习是为了自己，不是为了别人。往一个方向努力钻研，3年后你就能吊打同期所有研究生。你这种躺平只会害了自己', 1740489234, '3', '0', '1', '');
