INSERT INTO `douyin_aweme_comment` VALUES (4132, '85845407170', 'MS4wLjABAAAAMtlS1eFRCgj9J3vnTQkAHWbwA4Qkzej701JoDHh8-G0', '1266231245', '', 'hail  Stony', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/b9f058053be2726b43af0a7080727831.jpeg?from=2064092626', NULL, '内蒙古', 1769050849563, 1769050849558, 7588459626363519793, 7582971138093042993, '陈嘉映教授[贴贴]之前有幸参加过他的讲座，真的是非常谦逊有智慧的先生，我觉得他想说的是不要有那种唯学术唯论文的心态，而要找到自己真正想要做的事情，没有说硕士博士没有用的意思，不过很不幸的是，大多数人如果没有硕博这种学校里搞学术的环境，就更做不到这些事了[泪奔]', 1766825941, '0', '0', '4', '');
