INSERT INTO `douyin_aweme_comment` VALUES (4134, '103491317967', 'MS4wLjABAAAAPyUlLUTHITRkjJifgxPhIJ2jku_As2L6CseDRlMNE9s', '1336613676', '', '叮当啷咚咚当啷', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_30e8e000657e950e8e37f.jpeg?from=2064092626', NULL, '北京', 1769050849588, 1769050849584, 7583330263695115042, 7582971138093042993, '我真的会去读硕士论文，当你对一个领域不了解的时候去找硕士论文，当入门读物用最合适了[看]。', 1765631668, '17', '0', '306', '');
INSERT INTO `douyin_aweme_comment` VALUES (4135, '93525824323', 'MS4wLjABAAAAWFSZaO4iFpOfFiZWvXiO34tRUBVNJO97wx6EQNISIhg', '1951714965', '', '一瓶鸡腿🍗', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oA3BEbi9Amef1ghbEABAI9m19OowXECAA1ikfk.jpeg?from=2064092626', NULL, '江西', 1769050849599, 1769050849594, 7591009465643057969, 7582971138093042993, '第一、谁逼你读研了吗？读上研了如果不愿意从事科学研究，只想混个学历，读研确实可以水过去。第二、做科研写论文跟你的生活关系大吗？谁说写论文就不能谈恋爱不能旅行了？把不恋爱没旅行...归咎于写论文？第三、你陈嘉映硕士论文怎么写的？是像你说的这样吗？你怎么不这样读你的硕呢？你怎么不教你子女这么读硕呢？这种老而贼的人真的可怕，装模作样一副痛心疾首的样子，其实他明明知道年轻人想听什么话。[杀马特]', 1767419622, '1', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (4136, '870407388532045', 'MS4wLjABAAAAj72j0dC5xr3Quo-h4lUZPu7SjjP-SlRTmbxV2Srn_iw', '3437120323', 'dy85zj4uisnd', '小宋会顺利毕业', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_o0dfDzX6QAegIyVDIkAfmCAiA2FuQIfBPAmDrE.jpeg?from=2064092626', NULL, '江苏', 1769050849617, 1769050849610, 7597775431902708490, 7582971138093042993, '发给我导师看呀[流泪]', 1768994945, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (4137, '64294379761', 'MS4wLjABAAAA8yNNBVwpNIndOO9666hyWuvZC9WKgJUEymC004_FinE', '116061769', 'ZZZzzzww.', '蒙娜丽雕🏸', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_85358a614888c565fd495d11f86e6387.jpeg?from=2064092626', NULL, '陕西', 1769050849630, 1769050849625, 7587956435444138789, 7582971138093042993, '我研一就开始搞课题了，研二发了篇一区和北核，拿了国奖入了党。现在研三上学期了，签了老家（连云港）的一个饿不死的工作[捂脸]', 1766708784, '69', '0', '1031', '');
