INSERT INTO `douyin_aweme_comment` VALUES (4157, '74872212873', 'MS4wLjABAAAAbhl7T2uCsNrmlsDVOLesiTzjxQ6r6lxL9teBzA_KNK0', '117978256', '', '财从四面八方来', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_osg5daHQAe7CAQ0ILEXQAEAMAya5ABfd8ROBpe.jpeg?from=2064092626', NULL, '山东', 1769050863439, 1769050863433, 7594483825460724486, 7594422861030447985, '那我导师把我们养的很好了，脾气好不发火，不压榨，发的钱还多[流泪]，研一每月800，研二1200，研三1500，出差的话另有钱拿，读研期间出海采样我一共发了一万多，写项目的话每个月多发个六七百，还有一次干组里接的活，发了八千六，挺爽的，我们老师从来不去学生办公室，组会三四个月开一次，就是我躺平躺的写起论文就愁死了，不过我们导师也没催我们，我们老师比起其他老师简直是太好了[流泪]', 1768228559, '9', '0', '140', '');
