INSERT INTO `douyin_aweme_comment` VALUES (4211, '3894946553158784', 'MS4wLjABAAAAuDo3t7dPi9DE_-USM9PDqJb59jvAQcYbuHqbsD_JqPZ6ogPMkM9_3DOHPvLz3P47', '69783750922', '69783750922', '美夜读书笔记', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_89182df083d316b280358d3a450c6e5a.jpeg?from=2064092626', NULL, '陕西', 1769050881566, 1769050881564, 7587445279550391075, 7581142946089071099, '找不到截图了，当年着急给老师，用pdf转文字，好多标点莫名转成了感叹号，我急急忙忙没注意，也没改，就打印了交给他了，我导师看到后…问我，“写个论文为什么这么兴奋？能有这么多感叹号？是咋了写的这么兴奋吗？全是感叹号？”我当时…………脚能抠出一座城堡[暗中观察]@玓玑', 1766589770, '1', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (4212, '836055968532221', 'MS4wLjABAAAAwBruCCnYgh4dS96ctU_4_SkTthnWWZK7ImlQBMnRt_4', '22629634065', '22629634065', '蹲蹲吨吨吨', 'https://p3-pc.douyinpic.com/aweme/100x100/c16000003f97583dac4.jpeg?from=2064092626', NULL, '江苏', 1769050881577, 1769050881572, 7586927243273552640, 7581142946089071099, '当年得罪了变态老师，论文只看不改，只说这不行那不行，工作量不够，毕业很难。老子没理他，原文拿去答辩，答辩的时候别的老师说我画蛇添足，工作量已经很多了，为什么多加一章没完成的实验。毕业之后再也没理过他。', 1766469156, '0', '0', '3', '');
INSERT INTO `douyin_aweme_comment` VALUES (4213, '52486341371', 'MS4wLjABAAAAP_mbhtQFMZ3Rtng9Zkt6L7YELWviqVggy4gThXff4OY', '177168674', '', '重启人生（逆风翻盘版）', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_90ecae0e45f63775c25063b2410bcd42.jpeg?from=2064092626', NULL, '青海', 1769050881589, 1769050881585, 7587296684028461873, 7581142946089071099, '这就不得不讲讲我当时因为毕业论文进度缓慢，没办法给我导师发的一条信息了\n我：实在不好意思啊，老师，拖您狗腿了\n隔了五分钟，我导师一句话都没回，我还搁那儿跟我舍友吐槽他不理我，后来打开聊天框，天塌了啊[裂开][裂开]，后腿变狗腿，消息撤又撤不回，着急忙慌一通解释，我导师回句好好精进论文[泪奔]', 1766555173, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (4214, '2814356542197928', 'MS4wLjABAAAAW_3-YyehIfIgZru6QT1rDB7fozk23SP_-903KSeSLEQGXemqLhQSQNAFdDjuxbpD', '79502939411', 'S1nceNov', 'AKI', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oAe4CcAQQRMAuEDWAVEeCQCkxAfB7BAAI2Rc8Z.jpeg?from=2064092626', NULL, '重庆', 1769050881599, 1769050881595, 7587095464097710888, 7581142946089071099, '离一辫还有一个月导师叫我打印下来去找她一趟 我问同组其他人需不需要打印 他们都说没有 我以为我写挺好 因为当时和导师聊的挺开心 最后嘴贱问导师为什么我需要打印下来 是不是写挺好 导师说剩下两人都挺省心没什么问题就我问题最大需要打印下来一一指出哪里要改[捂脸][捂脸]', 1766508324, '0', '0', '3', '');
