INSERT INTO `douyin_aweme_comment` VALUES (4261, '3565035410693028', 'MS4wLjABAAAAOzDngawONAqMnkGcl8yEwsg23jwTJgosRx0SAeps7h-k9cIqDGhBR2pcPGTwNrax', '63330548152', '63330548152', '食豆饮水斋', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oEJlCwoAhezf5CmAcggEsQcA9soozAAPANxIOC.jpeg?from=2064092626', NULL, '天津', 1769050910827, 1769050910822, 7579539896295080731, 7574659607563759098, '去西方的研究院吧[笑哭][笑哭]。我大学同学，两口子都在荷兰的研究院，才二十多岁，日子过得跟退休了似的巨舒服，我们都在劝他们别回国，回来适应不了[捂脸][捂脸][捂脸]', 1764749155, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (4262, '75228297175', 'MS4wLjABAAAAynZiWGtEH_RpSJIoQK9WfY_wVNCqzvt4DxnAN7pfv00', '135208597', '', 'Ricardo M Lu', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_da5ae8ccd03b91486564ceac5c36c6c7.jpeg?from=2064092626', NULL, '安徽', 1769050910844, 1769050910839, 7588817381821023013, 7574659607563759098, '其实，我对你是有一些失望的。当初把你招进来，是基于你本科时的水平的。我是希望进来后，你能够拼一把快速成长起来的。我们这个组，不是把事情做好就可以的。你需要有体系化思考的能力。你做的事情，他的价值点在哪里？你是否作出了壁垒形成了核心竞争力？你做的事情，和其他人的差异化在哪里？你的事情，是否沉淀了一套可复用资料和方法论？为什么是你来做，其他人不能做吗？你需要有自己的判断力， 而不是我说什么你就做什么。我不需要中规中矩的答卷，它是有一些差异化在里面的。后续，把你的思考沉淀到组会里，我希望看到你的思考，而不仅仅是进度。另外，提醒一下，你的产出在我们组是有些单薄的。如果再这样下去，我不能保证你按时毕业。[躺平][躺平][躺平]', 1766909238, '1', '0', '10', '');
