INSERT INTO `douyin_aweme_comment` VALUES (4302, '74278681465', 'MS4wLjABAAAAa7ibhdU_cIPMUUvC9XZb-u-fq3xOE2kFplDvzXEEB0U', '1047246723', '', '梗王爱喝水', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_616afce63bafa54386dfee37a9156f42.jpeg?from=2064092626', NULL, '', 1769050938526, 1769050938523, 6682355424697942024, 6677819629466914055, '没有什么在职了，只有全日制和非全日制，前者基本免费，后者学费一年两三万，证书上会标写全日制或非全。来自一个硕导的解释。', 1555857119, '125', '0', '943', '');
INSERT INTO `douyin_aweme_comment` VALUES (4303, '108833016521', 'MS4wLjABAAAAGA1zDpjs_oHrJJQp6u6b5b8IATOAv1pAoi-RaTVz-ls', '2174625703', '', 'GJB', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '', 1769050938537, 1769050938533, 6677883074564898830, 6677819629466914055, '准确说那叫非全日制研究生，学位证和全日制一样，毕业证注明“非全日制”。非全毕业是硕士学历，而以前的在职是没有硕士学历的。', 1554815817, '1', '0', '4', '');
