INSERT INTO `douyin_aweme_comment` VALUES (4360, '1508157179298135', 'MS4wLjABAAAAFLG20zg5GTjjvEmVXObESstLX8oWOdnYnJWdvYR9v6-mNN8EFiyVxeGIgHTe-u7X', '2834011838', 'dy9jwtt6eezy', '笑一个吧😜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_27d8d756c450815fe49cc8cfd2384ab4.jpeg?from=2064092626', NULL, '河南', 1769050953935, 1769050953930, 7181299030176105216, 7181065182989274406, '考试当天发烧了，考点好多人在咳嗽，考场也又好多人在咳嗽。我一直在发烧，好不容易撑到考完，也算是对这段时间都努力有了一个交代，加油，我们终将上岸。', 1672026482, '1', '0', '4', '');
