INSERT INTO `douyin_aweme_comment` VALUES (4364, '97248124180', 'MS4wLjABAAAADJiFfZqjFG8zHEWbzg3H_3k-pMd_jNS9PAt_BJcrjiM', '886829580', '', 'Fan', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_866a68073fb847e09a972378c48f70a1.jpeg?from=2064092626', NULL, '山东', 1769050963879, 1769050963876, 7573662860955124529, 7573411198570417423, '那这样的话，我看你对嵌入式的激情也就那样，我的研究生阶段也和你描述的那样，不要指望从导师那里学到什么东西，能毕业就行了。除此之外，你可以随意研究自己喜欢的东西，我一个同学从自学，到接校外的项目，赚了很多钱，也没耽误他毕业', 1763380801, '6', '0', '28', '');
INSERT INTO `douyin_aweme_comment` VALUES (4365, '93462813935', 'MS4wLjABAAAA-pNYq47bDZO4mOl2HTxG58Ox01zbcb1pZuvKDjBb67o', '1475623600', 'W780173223', 'f>A<n', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ogAEDIsvgAOVAOyf9FfjLpDCWAPDOEAV4AFFA8.jpeg?from=2064092626', NULL, '河南', 1769050963893, 1769050963888, 7590453154786607910, 7573411198570417423, '我考研就是感觉自己高考进了个二本土木，学的还不是很好，简历上没有拿得出手的东西，所以跨专业考了个211的机械类专业。', 1767290102, '0', '0', '6', '');
INSERT INTO `douyin_aweme_comment` VALUES (4366, '482004790417308', 'MS4wLjABAAAAolMW0aZWlMPwVBkO737vLZmLdc2ATg4A3S7HFO37i64', '38619220260', '38619220260', '用户5241602303859', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '广东', 1769050963909, 1769050963905, 7573639915268277001, 7573411198570417423, '没激情，那如果直接做自己感兴趣的项目呢?', 1763375457, '3', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (4367, '2101864930214871', 'MS4wLjABAAAAOr7vSB0dTJSR1_Caz3Ipebev1qce_qy7ClRvwO6S5tbuuOJBWdw4deozLeGpd6YT', '3467614471', 'hxxzzc90145', 'M.稳', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_92c83bec047143b3ae90c91c76603f73.jpeg?from=2064092626', NULL, '黑龙江', 1769050963921, 1769050963917, 7595415610160972581, 7573411198570417423, '同研二，我想你现在还来得及，可以单独找导师聊一聊，请导师吃个饭啥的，把你的真实诉求说出来，卖卖惨多夸夸导师，天天内耗没有用，机会还是要争取的。我就是这么做的，之前天天内耗，找导师说开了就好了。', 1768445507, '0', '0', '4', '');
INSERT INTO `douyin_aweme_comment` VALUES (4368, '457869204920960', 'MS4wLjABAAAAFcT2xFR_ZsQSd00mGiguWJtTiSqDL8zTO6JwpAFXmkw', '65512162034', '65512162034', '🤗', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oobAlEfEXwOipkGeCIEo90AsAOETFeAADtA4i7.jpeg?from=2064092626', NULL, '安徽', 1769050963932, 1769050963927, 7588918197978448677, 7573411198570417423, '哥我也比较喜欢嵌入式，将来也想从事一个单片机嵌入式的方向，我是一个双非一本大三的学生，您比较推荐我考研究生吗？本科从事嵌入式的工作机会多不多呢？我有必要为了将来的工作而选择考研吗', 1766932710, '1', '0', '5', '');
