INSERT INTO `douyin_aweme_comment` VALUES (4371, '97895323328', 'MS4wLjABAAAAK74JEA2S8mQYjk7BXu6s2wz21ECkDwSXuNuuBsr1xAg', '1084884536', '', 'yxxtt', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oAQDpXA1Mw38ACsOJcaAbUAAECNrfOAIkgfF9x.jpeg?from=2064092626', NULL, '广东', 1769050963962, 1769050963958, 7573929776517022516, 7573411198570417423, '一摸一样的心态，研二开学到现在快三个月，我已经很久没有带着思考去看论文学习了，导师放养，只筛选不培养，一切要靠自己，这次组会拍拍脑袋就让做一个方向，结果下一次组会又说没意义，研一一直焦虑如何毕业，但态度还是认真，保持学习，从研一结尾暑假左右，心态开始爆炸，不止一次有退学的念头，还赶上分手，彻底崩了，开始厌恶实验室，厌恶看文献做实验，心态转变到现在无所谓，混就混吧，退学延毕我好像也能接受了', 1763443548, '2', '0', '43', '');
