INSERT INTO `douyin_aweme_comment` VALUES (4397, '3503480126842284', 'MS4wLjABAAAAu_xRzggO1DIFpotyF_dWfjNVNctLTwNI3C-gRx9Vu72sTnVOgc_VAv_Pnw6UNSwH', '98678010268', '98678010268', '大可', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_oceEKAP9KIzqABxEEnAwWNDwFZfAAErABQfQAx.jpeg?from=2064092626', NULL, '安徽', 1769050969563, 1769050969556, 7361213748046070566, 7361020367969750298, '看了评论区才发现我们国家想要进入发达国家路还很长，好多人是没受过教育的  整体素质偏低[捂脸]', 1713916140, '3', '0', '37', '');
INSERT INTO `douyin_aweme_comment` VALUES (4398, '102054266853', 'MS4wLjABAAAA_m7sGQG2eXJJlfCnKRrIFoGjb0vhXGdGqU24a9kjKIM', '1218962325', 'm92301002', '@H.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_90de2a8b326b47da870672847b97008d.jpeg?from=2064092626', NULL, '天津', 1769050969575, 1769050969570, 7366199473972970278, 7361020367969750298, '本科大三已经能找到央企工作了，虽然累了点但是待遇也还可以，我要不要考研啊', 1715076969, '3', '0', '2', '');
