INSERT INTO `douyin_aweme_comment` VALUES (4401, '82833257808', 'MS4wLjABAAAA6UNHbKxMTNryYr2Z3F-ZNcyaDxWFN2EsYDgsK6n0-Fg', '1065213500', '', '北纬26°', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_30e2d00041a3f246aeaa9.jpeg?from=2064092626', NULL, '福建', 1769050969617, 1769050969611, 7361307652401447731, 7361020367969750298, '读书很重要，它可以让你跨越阶层，但是并不是赢了所有的人生，工作后用人单位更希望你有能力，很多高学历的人才眼高手低，部分情商也低，完全不胜任，还一直等着年薪百万待遇如何才觉得配得上他，相反有的人不是读书的料却八面玲珑左右逢源一样过得风生水起，所以很多人都是说，读到最后都是为了生活为了工作，学历是锦上添花，综合能力强更重要[灵机一动][灵机一动]', 1713938002, '1', '0', '4', '');
