INSERT INTO `douyin_aweme_comment` VALUES (4454, '453447799277979', 'MS4wLjABAAAAp8zMwQTV6ljRbcVCWGbkBYnAiDknAdQfTXy-BhO-BMo', '65997997925', '65997997925', '诶就是玩', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/douyin-user-image-file_a48bb610077347feff777a6e072446e3.jpeg?from=2064092626', NULL, '湖南', 1769050984751, 1769050984744, 7585368455038419769, 7584291397659528502, '我很能理解，考研备考一年可以花费自己两三年甚至更久的心力，我就是这样研一和你一样怀疑到底是不是正确的选择，但是上岸了就好好读完，如果不想考博就顺利毕业，好好享受人生最后的三年学生生涯，好好感受生活，享受当下，做好每一天该做的事，想想毕业后工作规划，提前准备，焦虑没有用，在步入社会之前甚至到后半辈子很难有这样的“清闲”时光，不浪费的过', 1766106223, '1', '0', '59', '');
