INSERT INTO `douyin_aweme_comment` VALUES (4473, '72933785986', 'MS4wLjABAAAAPzw6Yq57LsUGLx3ZCCBDWVfn66OORccc8mrSp4GeGOI', '287033109', 'Mr_Cheng_Shuai', '风一样的男人', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oQfBBAACODBdeoyqEULIAQGbB6A7mvAQI2e0Eg.jpeg?from=2064092626', NULL, '浙江', 1769050999133, 1769050999125, 7216691605260256033, 7121301336242523427, '我也想考研啊  但是家庭条件不允许   每年的收入，就是靠着卖掉那几亩水稻换来的钱  爸妈年纪大了，不想他们这么辛苦。  打工虽然不好，但是能够减轻家里的负担。 很羡慕你们能够考研，但是我并不后悔当年的决定。至少爸妈身体健康，老婆贤惠，小孩可爱，我觉得这大概就是每个人的道吧', 1680266958, '3', '0', '33', '');
