INSERT INTO `douyin_aweme_comment` VALUES (4625, '69051065248', 'MS4wLjABAAAAKuMaA576hf8ZNq5Vyq5P4u9XILH-UkGi44BHu4uPpSU', '213045044', '', 'kihon', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_1548309a3b974b498ac772e981d9914c.jpeg?from=2064092626', NULL, '广东', 1769051048414, 1769051131028, 7466095519245321018, 7465972993181682984, '研究生可不是为了读书，如果本科毕业没有目标没有想法可以尝试去读研。研一一般都是上课，这一年时间里必须要自己想明白自己以后想干什么。如果还是抱着学生思维渡过研二研三，那么即使毕业面临的困境还是一样。所以根本是要摆脱学生思维，要有自己的想法，这个想法可以在学术上，兴趣上，工业领域等等，而不是随大流大家干什么我也干什么[泣不成声]', 1738335828, '8', '0', '674', '');
