INSERT INTO `douyin_aweme_comment` VALUES (4632, '1330861447847161', 'MS4wLjABAAAAaijUXkZ7MZWYuHm7trHCZW_UspRMt1A6DcvDmLv4Qz877ullYERv264-PHpF308H', '50037402363', '50037402363', '不7宵夜', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oAEAVzkAICtALgeb8kIABiiAJpBrjKAhsP4ePD.jpeg?from=2064092626', NULL, '山东', 1769051048499, 1769051131098, 7469687083024532235, 7465972993181682984, '刚考完研一定珍惜应届生的机会，做个两手准备考央国企，这种单位基本都要应届毕业生，掌握好方式方法一点都不难，多投简历，这样的话几率会大点，自己考也比较难信息差太大，也可以考虑报机构学习', 1739172056, '2', '0', '50', '');
