INSERT INTO `douyin_aweme_comment` VALUES (4697, '105027718549', 'MS4wLjABAAAAVMc2PBDrZU5UHZNlKr739wOvJVOxsvKf8MKIidKo_2w', '3418663568', 'dybrphdga7ao', '！', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_owSnWWwQEnDA0ecF4bEgGoG3jAwE9AAAImeGfZ.jpeg?from=2064092626', NULL, '河南', 1769051072497, 1769051136280, 7450997686386508553, 7450850053809343802, '不管值不值钱？我是拼了命的一定要支持我家孩子读研提升学历，所以我家姑娘读研己毕业，高中老师，儿子正在读研，我为他们骄傲[呲牙][感谢]', 1734820601, '23', '0', '340', '');
INSERT INTO `douyin_aweme_comment` VALUES (4698, '3905104706293357', 'MS4wLjABAAAAErFXPemorH1nkvjDRn7ymMiL75kK3-79R5Ra8-82vRk24f7iwpUf1zXOnF1TgqYx', '4013038381', 'dyz532bw3av7', '夕月', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/aweme_default_avatar.png.jpeg?from=2064092626', NULL, '江苏', 1769051072515, 1769051136314, 7454918071397729051, 7450850053809343802, '今年考研人数无论是下降还是弃考是大家认识到了自己的能力，如果能考上的话还是积极去考的，并不是你说的所谓性价比什么的，更不是什么不值钱的问题，楼主的思想局限性小了', 1735733375, '3', '0', '23', '');
INSERT INTO `douyin_aweme_comment` VALUES (4699, '4296541045004852', 'MS4wLjABAAAA-z_MGuH0AUBq3zNgsL-XmPf9_-PHaaxff_VWwR7YrRoU0pEze4L3Cc06eJubLC9V', '2821211741', '123shitou806', '快乐的圆珠笔', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_557cbe8222274e09b7f63582c86de812.jpeg?from=2064092626', NULL, '河北', 1769051072537, 1769051136340, 7456026393026462515, 7450850053809343802, '关键是一个人的目标是什么，\n如果是爱好，决心在行业内出成绩，读研是方向\n如果只是工作，那就大学毕业，高中毕业，就可！', 1735991428, '1', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (4700, '97684656898', 'MS4wLjABAAAAramwPI1gKSCBvDTi48z_u7xjEz0ebRhw2wTS0n3rVCA', '3413858625', 'haige98812', '海哥', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_af53b1180d2443e380e6aa6fa1326066.jpeg?from=2064092626', NULL, '山东', 1769051072547, 1769051136362, 7450925167138997002, 7450850053809343802, '考研不是唯一的出路，但读研一定是最好的出路！', 1734803734, '40', '0', '574', '');
INSERT INTO `douyin_aweme_comment` VALUES (4701, '102745514149', 'MS4wLjABAAAAcHuaaHObxKOvfHSPnbovNiXO9H-p-w9XqjVu-ljvR7w', '1727800250', '', '是玉如华<先森>', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oA8vAfCALOh8IAQes0fXyB8MEhAKFQ7UAXEAAB.jpeg?from=2064092626', NULL, '江苏', 1769051072547, 1769051136380, 7453598082355200805, 7450850053809343802, '考研很难，知难而退罢了，如果我的孩子想读研，就是砸锅卖铁也要支持他。不知有没有和我一样想法的？', 1735426064, '61', '0', '264', '');
INSERT INTO `douyin_aweme_comment` VALUES (4702, '94269862615', 'MS4wLjABAAAALL5NOLtfY-VZyBhQRBm7_uSpgLBkhd030tJiXOxm2Q4', '390593905', 'The_________', '系水下洗手', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_10728a4b236bf171dfb0c857028cf248.jpeg?from=2064092626', NULL, '河南', 1769051077469, 1769051157079, 7575891615496192810, 7563908508011416889, '我们这之前有几次招编 学历要求硕士起 本科学历都跑周边考去了', 1763899722, '0', '0', '1', '');
INSERT INTO `douyin_aweme_comment` VALUES (4703, '158760824217655', 'MS4wLjABAAAAsHt2uFFkhC8MxGbl4wnOHfEO0sJ2-1VyQniBrBsrEBQ', '66505065285', '66505065285', '心无挂碍', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oUAnte8f9pi5ADAJCPBly6ibArMJgA6Ez3vAIA.jpeg?from=2064092626', NULL, '黑龙江', 1769051077480, 1769051157103, 7572821267326862115, 7563908508011416889, '人生中最后悔的事就是读研，上大学。', 1763184853, '1', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (4704, '85942471303', 'MS4wLjABAAAAHsRnD1li5jZsjrfXTA-1FphTywFBw8wFjFtu6lrV_MQ', '290636419', 'Y.H.7.', '只对会员开放             ╲', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_2df7c0003db6bda130ca9.jpeg?from=2064092626', NULL, '四川', 1769051077499, 1769051077490, 7575373888067584822, 7563908508011416889, '研究生很好找工作的，你不要再妖言惑众了，我有个朋友就是研究生毕业，人家现在一个月光是底薪就高达4500，还不含500绩效，200的全勤，比早几年出来上班的本科生只低2000左右', 1763779180, '0', '0', '0', '');
INSERT INTO `douyin_aweme_comment` VALUES (4705, '4185177147841012', 'MS4wLjABAAAAdWCSNOy7umHWaj78x-q9NHfY8KD_qwTtWYKF0o_Jhyj9Sxsb594IrC7pfxUOMHAf', '34787784338', '34787784338', '🍍', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_44960209db628cc3ea16b6e84597b0f6.jpeg?from=2064092626', NULL, '美国', 1769051077514, 1769051157116, 7573346310478545705, 7563908508011416889, '我03年的 初中毕业以后就没读了 后来移民来美现在在这边做餐馆 是个sushi师傅 明天中午11点上班 中午午休一个半小时 晚上9点半下班 一个星期休息2天 一个月工资加小费差不多5500美金[呲牙]虽然工资不算高 但是好在工作还算轻松 而且店里面包吃包住 基本没有而外开销 一年可以稳定存个4万多美金[呲牙]出来工作快4年了 也算是小有积蓄 去年年底也买了一辆自己喜欢的车 我相信生活一定会越来越好的[呲牙]', 1763307100, '11', '0', '27', '');
INSERT INTO `douyin_aweme_comment` VALUES (4706, '7578812379678262321', 'MS4wLjABAAAAkfp0qolfy5u3l02t07n32Qw5c_Y1TeH7U7wa44m03VndkBzIlk3MCG5k1p5Dcsq2', '90691865373', '90691865373', '阿水12', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/douyin-user-image-file_ffefb560fb96c7f8336caa0c0b475855.jpeg?from=2064092626', NULL, '北京', 1769051077530, 1769051157130, 7581935711213978417, 7563908508011416889, '如果你考上清北复交 还能出国深造 你确实能跨越阶级[捂脸] 但是近亿里挑一的可能性 你确定你是其中之一[捂脸]', 1765306981, '0', '0', '3', '');
