INSERT INTO `douyin_aweme_comment` VALUES (4793, '1085917746699469', 'MS4wLjABAAAAXYNyfsSs3XQlvCHWhzQsjZqJvJVXQ25NI4NWxsgv5hGZVQO74GEHl_Yen0G6gs5x', '2366486525', 'yi4823727', '阿巴阿巴', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oUQoh35UKlAABIY7dTPAZ4AUPiICMiAERjT1z.jpeg?from=2064092626', NULL, '内蒙古', 1769051165132, 1769051165128, 7553354911670240052, 7552476558477299004, '可是研究生时间也很宝贵啊，如果读研前目标明确，你就可以更好地为自己未来的发展方向铺路，如果你读研期间一直处于一个迷惘得状态，或者目标不明确得状态，很可能你读完以后依旧发现自己不知道该干什么并且哪条路都走不了或者走不好', 1758652509, '0', '0', '3', '');
