INSERT INTO `douyin_aweme_comment` VALUES (4796, '3518035510689799', 'MS4wLjABAAAAB4foH8YTV8MOzK59AhLwHl6--tBHIhBcc_NsFJAMNE-nCZlF3gcI65l4e3MID3ms', '4208313279', 'jinseanying655', '落泪情绪零碎', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c000-ce_og9zEifqgho7AIrPSAQCdrFoB6JrQff8FwA6DA.jpeg?from=2064092626', NULL, '北京', 1769051170075, 1769051170067, 7531813696373801769, 7530532804448783668, '我在北理光电读研。这个组，臭名昭著，因为某个人势力太大，不得已被发配到这个组。太痛苦了，周内要打卡9小时，周六要7小时，每天打卡6次，一个月只发100-200。现在快研二，也不让做实验，全是杂活，具体方向都没定，还天天PUA我', 1753637048, '533', '0', '8191', '');
