INSERT INTO `douyin_aweme_comment` VALUES (4798, '63216250899', 'MS4wLjABAAAAb_2SCCutfyPu0RPKyWmvFUQzHeFDtdQ578vdKOtQq8o', '163999639', '', 'Xt.', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_bc2482e4507e63a3e725150ba99f3d98.jpeg?from=2064092626', NULL, '江苏', 1769051170098, 1769051170095, 7532730336398590754, 7530532804448783668, '开学研三，小导，没有横向，没有早八，课题是导师给的，内容是导师帮忙一起做的，文章是导师一个字一个字给我改的。读研一路走来没有敌人，全是导师帮我扛下来了[比心]', 1753850459, '44', '0', '3191', '');
