INSERT INTO `douyin_aweme_comment` VALUES (4814, '100088129307', 'MS4wLjABAAAAd_mE_7iTdQAA5KYabljxYvHpd0oOsA_1Jfcno4XcmzE', '1099597169', '', '我想火辣鸡', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_cb2ae8e36eaf444ea35fa1917d9c61d1.jpeg?from=2064092626', NULL, '湖北', 1769051170270, 1769051170265, 7532476275181749042, 7530532804448783668, '感觉我导就是天使（虽然是个男导师）[看]从来不给我安排私活，一般都是自己实在弄不完了，就让我帮下忙（一般给四百到八百，一点事给这么多我拿的都有点不安心），设备和电脑啥的应有尽有随便用[看]啥比赛都给报销，从来不凶人，有路子和好处第一个想到自己的学生[看]', 1753791302, '7', '0', '105', '');
INSERT INTO `douyin_aweme_comment` VALUES (4815, '54637831705', 'MS4wLjABAAAAi_6Mb5qoTZkqApUfkhumhTxp-gmpiPAI002flvkgvZ0', '40215646', 'yangyangfang33', '洋洋方块', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_9b79dc9c4f6bd89bf26d2acd5725c2cd.jpeg?from=2064092626', NULL, '北京', 1769051173206, 1769051173201, 7595267044096082737, 7530532804448783668, '我的妈呀，我还在抱怨我的文科读研痛苦，我撤回，祝大家都有好前途[贴贴]', 1768410921, '0', '0', '0', '');
