INSERT INTO `douyin_aweme_comment` VALUES (4818, '50384074679', 'MS4wLjABAAAAZAmkswkNq17ieSeFjq9A_ZDH0DPBt3AgCbMtVyVWaWI', '81374299', '', '多肉猪猪肉嘟嘟', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_63abf5fd4f48b357b03aa0dc017a901f.jpeg?from=2064092626', NULL, '安徽', 1769051184202, 1769051184197, 7312448250694599462, 7312371494959500554, '十年前我们老师说，他有个学生同时考上了研究生和公务员，结果他放弃了公务员去读研了，老师说他脑子有问题[看]', 1702562036, '88', '0', '3178', '');
INSERT INTO `douyin_aweme_comment` VALUES (4819, '4446028573980436', 'MS4wLjABAAAABfZvPFwx1kmJQKlFxIylhylj6VvGnk8IELs3_7bcmJik8orb54ZggX6vEDihU7ku', '3045355855', 'xiaoying369956', '小瑛', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/mosaic-legacy_2e791000958175c7fbb3c.jpeg?from=2064092626', NULL, '江苏', 1769051184212, 1769051184208, 7312390059818713893, 7312371494959500554, '看来我儿子才是人间清醒，去年大学毕业就果断选择了一家国企工作，今年春季国企的人武部募兵，小子又参军入伍了，单位保留工作岗位……', 1702548489, '57', '0', '1315', '');
INSERT INTO `douyin_aweme_comment` VALUES (4820, '1063932801062493', 'MS4wLjABAAAAWCHLKxyEp1DHWpIDggoETApM32kGSQI3QKX7foH5rKmPpYIA0a40cxHRBxEtNkpL', '3533440694', 'xiaobaqi8076', '小霸气', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_oAAhZbIgCbAeUDnfFv9KOpbIAznxACAQCANkaM.jpeg?from=2064092626', NULL, '山东', 1769051184212, 1769051184212, 7313833875136971531, 7312371494959500554, '是的，我姐研究生毕业5000，我本科毕业找的工作1.2w', 1702884652, '5', '0', '48', '');
INSERT INTO `douyin_aweme_comment` VALUES (4821, '804438921982845', 'MS4wLjABAAAATlqiqQ5nWwpr6sF8i-5sgww-w3sAymlOpYhK4Sm75Nw', '2371075136', 'LHY20000712', '放羊🐑人', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-avt-0015_f7ebe7968459ae0e570268c91287da46.jpeg?from=2064092626', NULL, '湖北', 1769051184233, 1769051184229, 7316033161581085476, 7312371494959500554, '医学生路过  学医不考研  就相当于等死  学医超级看学历  一个有能力的本科生和一个985啥也不知道的  人家毫不犹豫还是选择985.起码学历对于学医而已超级重要！', 1703396713, '1', '0', '13', '');
INSERT INTO `douyin_aweme_comment` VALUES (4822, '1345400757564723', 'MS4wLjABAAAAmdSukgt_UhV9TUr5_cT_03-U06-TyUfgQ3yfHDreYxSam0lDIHO4urcKSHeRtase', '3462710416', 'xiewanyuan67', '谢万源', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813c001_ocePifvABAEIAcAqNQGkEQgeMQAXiy7yWLYBBw.jpeg?from=2064092626', NULL, '广东', 1769051184243, 1769051184239, 7312423731224691510, 7312371494959500554, '我妹华南理工的研究生，学风景园林，天天熬夜到2-3点，一看工资才8000多[捂脸]', 1702556326, '37', '0', '79', '');
INSERT INTO `douyin_aweme_comment` VALUES (4823, '95885036730', 'MS4wLjABAAAA8PoQZrUskpAmBfy76RL7Ab3fSNMbqffUWs5LCyiaGLM', '615305251', '', '我有办法', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_o030C2vAiSqiEA9AhgbEGdcAetB0BAAyAfWIkN.jpeg?from=2064092626', NULL, '四川', 1769051184245, 1769051184245, 7312414880018809626, 7312371494959500554, '17年大专毕业，计算机相关专业，现在从事大模型相关研究，年薪200万左右。我大专时候的同学后面升本，再后面读研究生，现在毕业了在家待着，他说他只想找一个月薪一万的工作，找了一年了根本找不到[捂脸]', 1702554266, '36', '0', '80', '');
INSERT INTO `douyin_aweme_comment` VALUES (4824, '4252502772419907', 'MS4wLjABAAAAZqaS2fKHDYK4XO3x-C46boegX_06fy95ab2o-t3nAqGbjJ0SVUDVuPhNF0JLzxng', '2320494022', 'dy8lbdiqksmt', '鹅鹅哦豁', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_eca64fdb75a54f1391a1c6259552da59.jpeg?from=2064092626', NULL, '湖南', 1769051184262, 1769051184245, 7313103286625501978, 7312371494959500554, '我21年211本科毕业，保研985，读了两年研究生毕业后已经找不到我本科同学21年找的国企工作了', 1702714550, '2', '0', '14', '');
INSERT INTO `douyin_aweme_comment` VALUES (4825, '87714729308', 'MS4wLjABAAAATSG_JuwYjj9nv0rWrOrRxmq23aa4GSQJkEKFd1c1KiM', '269703322', 'S1ckNe5S', '长风山月', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_oQhVXAeAEAAtDIBUAyAgVUCdNCfoPVqziGaavK.jpeg?from=2064092626', NULL, '江苏', 1769051184272, 1769051184268, 7318857393239147318, 7312371494959500554, '我研究生都毕业了 我本科舍友还在考研 今天准备问他新年快乐 才发现给我删了[尬笑]', 1704054291, '1', '0', '5', '');
INSERT INTO `douyin_aweme_comment` VALUES (4826, '99172154287', 'MS4wLjABAAAAasMTl8ltBrNa_vEeQ83bXluedkA1ELvgjnFz6QCKHQI', '1142297367', '', '🧚‍♂️🧚‍♂️🌟', 'https://p3-pc.douyinpic.com/aweme/100x100/aweme-avatar/tos-cn-i-0813_44d3eb09786e4136a446deec33c46ea5.jpeg?from=2064092626', NULL, '四川', 1769051184279, 1769051184279, 7313024146798740261, 7312371494959500554, '我们是央企，职能管理部门岗位校招必须硕士研究生以上，本科连资格都没有。同行业的公司招聘也一样。成都蓉漂人才引进，你看看本科和研究生的区别，，所以，不用误导大家。', 1702696124, '3', '0', '22', '');
