INSERT INTO `xhs_note_comment` VALUES (58, '6076e29400000000010006b4', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/d784fc20c996f3d2f39d034c404f234e.jpg?imageView2/2/w/120/format/jpg', NULL, 1769047101548, 1769047101548, '664759b1000000001c035b9a', 1715952049000, '6644adde000000001e03363a', '中文翻译成英文再转俄语转法语转西班牙语再转中文，再自己读一遍把不通顺不是人话的地方改改，能降很多', 16, '\"\"', '0', '263');
