INSERT INTO `xhs_note_comment` VALUES (198, '66e994d0000000001d03271d', '用户已注销', 'https://sns-avatar-qc.xhscdn.com/avatar/645b7f83b46568f580649586.jpg?imageView2/2/w/120/format/jpg', NULL, 1769047164487, 1769047164487, '674b79930000000007005c21', 1732999572000, '6460868b0000000014024a54', '答辩是大学生进入社会的第一课，领导讲话不能反驳，跪着听完奉承几句，因为我们没有话语权', 1, '\"\"', '0', '9');
